/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20251125-9","meetingId":"r07-cm11","date":"2025年11月25日","dateIso":"2025-11-25","committee":"文教委員会","time":"午前１０時００分～午後 ２時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"令和７年陳情第４７号、品川区私立幼稚園保護者負担教育費の軽減に関する陳情","agenda":"令和７年陳情第４７号、品川区私立幼稚園保護者負担教育費の軽減に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それと、入園料補助金が、今、一律１０万円出されているということで、実際、入園するときには、費用はどのくらいかかるのか伺います。何割ぐらい出しているのか、その辺りを伺います。","respondent":"佐藤保育事業担当課長、芝野保育入園調整課長","answer":"１２か月を実施した際に、１食分５００円程度と算出しますと、２億１,６００万円程度の予算が必要となると想定できます。こうした制度全体を賄う国や東京都の補助はない認識です。入園料ですが、おおむね１１万円から１６万円の範囲内で皆さん設定しておりますので、その差額についてはご負担いただくことになっております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"私立幼稚園における給食の状況、実態を伺いたい。区立との費用負担の差はどのくらいあって、区としてはどのように認識されているのか、伺います。","respondent":"佐藤保育事業担当課長、芝野保育入園調整課長","answer":"区内には私立幼稚園は１７園ございまして、給食の実施状況はそれぞればらばらです。保育料の中に含まれているという考えからゼロ円の園から、月額で１万円程度お支払いをいただいている園があるという状況です。 預かり保育は、４５０円を上回る負担をいただいている園もあります。最高で１,１５０円取っておりますので、その差額ですから、７００円を負担しているという園があります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"検討されているということでしたけれども、区としてはこの是正が必要だと考えているのかどうか、その認識をお伺いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"是正が必要かですが、私立幼稚園は、区の幼児教育の中心を担っていただいておりますので、今後は是正に向けた検討も併せて行っていきたいと考えております。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"私から１点、確認させていただけたらと思いますが、補助対象者の拡大という記載があるのですけれども、１号給付の保護者のうち、１２日４８時間以内の、例えばパート勤務の方々の預かり保育のニーズがどれだけあるのかを、もし区として把握していることがありましたら、説明を求めました。","respondent":"芝野保育入園調整課長","answer":"申し訳ありません。４８時間以内のパート勤務で預かりを希望される方の数字は持ち合わせておりません。","id":"exchange-004"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"陳情が求めています１から４の項目がありますけれども、また、全てを即座に実現することはとても困難というのはお話の中で分かりました。実現に向けて継続的に調査、そういうのをしていただきたいと強く要望して、意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"給食費の無償化や預かり保育料の補助金の増額をさらにご要望されているわけですけれども、また、預かり保育料も。そもそも私立幼稚園は私立なのであって、公立ではないので、あまり私立であるにもかかわらず、公的補助、税金による補助を求めていいのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"一方で、今回は給食費の無償化、また、預かり保育についての新たなご要望ということで承りました。したがいまして、今回の陳情については、趣旨で採択をするということでお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"２億１,６００万円ということですけれども、支援していきたいと思いますので、採択です。もう少し具体的にどのように、なぜこれを求めているのかという理由を書いていただくと分かりやすいということだけ述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"陳情要旨として１から４まであるのですけれども、区では、それぞれかなり細かく助成なり補助なりして、金額も増やしてきている部分があります。この１から４の要望に応えていくのは厳しいと思いますが、私立幼稚園の教育状況の向上等のご要望ということに関しては理解するので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"科学的な根拠に基づいたニーズ調査ですとか、他の地域における先進的な研修の在り方なども研究してほしいと思いますので、要望します。地域のＰＤＣＡが機能しやすいような仕組みを構築するという視点を持ちながら、今後の幼児教育を捉えていただきたいということも要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"採択と趣旨採択で決を採るというのはできないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"令和７年陳情第５０号、品川区内の小・中・高・特別支援学校における「いじめ」をなくす取り組みに関する陳情","agenda":"令和７年陳情第５０号、品川区内の小・中・高・特別支援学校における「いじめ」をなくす取り組みに関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"陳情の中に、いじめが重大な人権侵害であるということとか、社会問題だということは、私もそのとおりだと思います。数値目標を設定するべきだと書いてありますけれども、区の考えと国のそう言っている理由、根拠があれば伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"品川区のいじめの認知件数につきましては、国の１,０００人当たりのいじめの認知件数に比べて、随分の差が開いているという認識に立っております。そういったことから、平成２９年から、全国的にもかなり認知を上げて、子どもたちへの対応を進めてあります。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"数値ばかりを追い求めてしまって、数値目標を設定するのは、私は違うと思います。区として、いじめ対策、どういったことができると考えているか、実際やっているとは思いますが、伺います。","respondent":"丸谷教育総合支援センター長","answer":"教員研修も充実させるという意味で、年間１０回のいじめ予防の教員研修を行っております。子どもたちの認識、教員の意識を高めて、進めていきたいと考えております。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"本当に自治体としてできることは、たくさんあると思うのです。ぜひそうしたところも含めて、自治体として、いじめ対策を進めていくということをやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"そういうところから入ってきたので、何点か、この文章に沿ってそれぞれ区の見解を確認だけさせてほしいと求めました。こういう陳情者の意見、主張が何点か端的に出ていますので、それぞれ区の見解は確認をしておきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"品川区のいじめ防止対策推進基本方針、この中でも、家庭や地域との連携についてうたってあります。家庭においても、そういった子どもたちへの働きかけをしていただきたいという説明も行っておりますので、そうした連携が大切だと考えております。","id":"exchange-015"},{"speaker":"筒井副委員長","kind":"質問","question":"そうしたいじめの重大化を防ぐことにつながったのかという、そうした実績、そうした状況はあったのでしょうか。それをお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"月に１回、月に１回のいじめのアンケート、初期の段階で学校が把握する取組を行っております。早期に教員が声をかけて、いじめを初期の段階で対応した事例もありますので、こうした取組を継続的に行っていきたいと考えております。","id":"exchange-016"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"ぜひ初期での発見を積極的に行ってほしいと求めました。いわゆる区の行っている取組の理解の浸透度はどのぐらいかを、どのように区としてお感じになっているのか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"保護者の認識というところでの細かな調査を行っているものではございませんけれども、その中で保護者の方の認識も上げていただくといった取組を昨年度から行っておりますので、家庭との連携も強固なものになっていくものと考えております。","id":"exchange-017"},{"speaker":"まつざわ委員","kind":"意見","question":"これをすることによって、本当に助けてほしい子どものＳＯＳが聞こえなくなると思います。学校だけ、教育委員会だけでなく、オール品川でこの問題は解決していきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"しっかりご説明を、さらに皆さん全員で実感をしていただいて、本質的にいじめをなくしていってほしいと求めました。結論としては不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"いじめ根絶協議会ですか、自治体ができることはほとんどありませんという意見は、私はなかなかうなずけないところがどうしても当然あります。ですので、しっかり区教育委員会がまさに現場の学校のご支援をしながら、いじめの根絶に向けてさらにご努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"のだて委員","kind":"意見","question":"自治体にできることもたくさんあると思います。そういった様々なことが自治体ではできると思いますので、本陳情には賛成できませんので、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご説明をいただいて、その中で、陳情の内容の１、２、３は、ご説明からするとそぐわないということで、不採択でお願いします。そして社会全体で対応していくべきものだと思っていますので、こちらの趣旨は賛同できないので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"第１２３号議案、児童福祉法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","agenda":"第１２３号議案、児童福祉法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"乳幼児を預かる施設という認識でよいのか確認させていただきたいのと、あと、児童センターも今回対象になるのですか。実際のところは、具体的に区は今までどういった対応をしてきたのか、今回と変わるところがあれば伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"案件によっては、園へどのように今後アプローチしていくのか検討し、区で関連する部署があるのであれば、関連した部署との協議などを行います。保護者の方、そして、お子さんの様子を継続的にフォローしております。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今までの対応とこれからは本当に何も変わりはないのですか。それ以外では特に区の対応として変わるところはないということでよろしいか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"変更点について触れていなくて、大変申し訳ございません。変更点が、東京都と児童福祉審議会への報告というのが課せられましたので、そちらについてはしっかりと対応していきたいと考えているところです。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"この４ページは、職員はどういう処分、そこら辺はどのようになっているのかというのが１つ。大きく３つあると思いますけれども、社会福祉士とか専門職が判断するところは、どこの資格になるのかも教えてほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"ですが、通報等をとどまってしまうようなことがないように、様々な機会を用いて、通報の必要性を継続して投げかけていきたいと考えています。そうした職員、部門との連携を図りながら、一つ一つのケースに対応しています。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問・要望","question":"区としてそこに意識を強く持たせるための何か工夫等があれば、またご検討いただきたい。初動の誤りというのが必ずついて回るので、今さらですけれども、よくよくそこはご対応ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"まつざわ委員","kind":"質問","question":"区長にどのタイミングでどう伝えるのか、そういった報告体制があれば、まず説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"緊急性を要するような、児童の身体や生命に危害が及ぶような事例が起きた際には、早急に区長等にも報告を行うとなっております。どのように判断していくのかというのが示されてありますので、そうしたものを参考に区としては対応していきたいと考えているところです。","id":"exchange-027"},{"speaker":"まつざわ委員","kind":"質問","question":"もう１個は、そういった、変わりましたという周知をどう徹底していくのか。やはり内部通報者の保護を徹底した、そういった仕組みもしっかり明記していく必要があると思いますが、いかがか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"今回、通報等をより実施していただくために、オンラインで２４時間お受けするような窓口を設置しています。区としても当然、そうした点については細心の注意を払いながら対応していかなければならないと考えております。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"２番の通報後の区の対応の保育所の場合の図を見たときに、もう一度詳しく教えていただけたらと思います。オンラインで２４時間の通報の窓口を設置するということなのですけれども、それぞれどういった受付の窓口になっていくのかをご説明いただきたいです。","respondent":"佐藤保育事業担当課長","answer":"東京都と２３区で会議体を設けて実施してございまして、その中において、今後どのような連携を図っていくのか。まずはそれぞれ施設を所管している部署において対応していくこととなりますが、対応する所管の連絡先は記載している状況です。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"指導方針の協議、虐待有無の判断になってくると思うのですけれども、こちらの判断等もそれぞれの所管で異なってくるのでしょうか。組織としての判断をどうしていくのか、もし分かりましたら、説明を求めました。","respondent":"佐藤保育事業担当課長","answer":"それぞれの所管において判断されていくと考えていますが、そこについては対応ができる職員の数ですとか、連携を図りながら対応していきたいと考えています。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"区の方針やフォローアップにつなげてほしいと求めましたので、他区ですとか東京都とも今後スタートしていくということですので、ぜひ適切に進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどの１個目の質問と少し重なりますけれども、どのようにして保育士たちが気づくのを学んでいくか、それを教えてほしいと求めました。それをほかの保育士がこういうのを見つけた、そういう少し具体的なのがあれば、１つか２つ教えてほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"さらに園長会等において議題として取り上げることで、理解を深めていくことも実施しています。大きな声での指導が、少し過剰になってしまっているようなケースなどがあると認識しています。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"意見","question":"賛成です。そういう園の風土も大切なので、ぜひそちらも、虐待に至らないような園の風土をつくるようにお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-04","title":"第１２４号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第１２４号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１つ目は、先ほどと同じということで、ここもこれまでと変化がないのか確認させてほしいと求めました。今回の変更は、家庭的保育事業だけなのか、そこも伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"事前に医師会や、実際に公立保育園で園医を行っていただいている医師の方に内容等を説明し、ヒアリングを実施しています。同様に変更に対応することができるような構成となっているため、今回、改正が不要となっているものです。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"今回、保育所などもその対象で、保育施設全般的に変更になるのですか。この対象の施設、もう少し詳しくお示しいただけたらと思います。","respondent":"佐藤保育事業担当課長","answer":"今回の改正による対象施設ですけれども、今お話しいただきましたような保育所がまず１つあります。続いて、地域型保育施設の家庭的保育施設、小規模保育施設などが改正の対象となっております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、幼稚園とか、あと、オアシスルームとか、そういったところは対象にはなっていないのか、確認をさせてほしいと求めました。","respondent":"佐藤保育事業担当課長","answer":"今回、児童福祉法の関連ですので、幼稚園につきましては対象とはなってございません。オアシスルームは一時預かりの施設ですので、健康診断は求められている施設ではないと認識しております。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"例えば、保健所における１歳６か月、３歳健康診査をしたときに、その情報をどこで利用する前の健康診断を省略できるのか。相互なのか、どういった具体的なケースが考えられるか、説明をお願いできますか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"具体的な例としましては、健康診査、１歳半健診や３歳健診を受けたお子さんが保育園に入園するときに、母子手帳等に、その実施の記録の記載がありますので、そちらの写しを頂戴することができれば、代えることができるものとなっております。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"例えばなのですけれども、そういった児童相談所に入所、一時保護とかを受けた場合も健康診断とかが行われると思うのですけれども、そういったケースでもそのような形になるのか尋ねました。","respondent":"佐藤保育事業担当課長","answer":"委員お話しいただいたとおりでございまして、児童相談所の一時入所などを行った際に健康診断が行われていた場合、その後に保育園への入園が必要であると判断があった際は、そちらで行った健康診断を基に入園することができるものです。","id":"exchange-038"}]},{"id":"topic-05","title":"第１３３号議案、指定管理者の指定","agenda":"第１３３号議案、指定管理者の指定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、家庭あんしんセンターの指定管理で、申請した事業者が１事業者のみだったということで、まず、区の受け止めを伺いたいと思います。いかがでしょうかというのと、どうなのか、どの項目が低いのかを伺います。","respondent":"吉野子ども家庭支援センター長","answer":"利用者の方、やはり運営をしていくにはなかなか難しいという観点から、応募の部分を回避された事業者が多かったのだろうと考えております。全て３点以上になっておりまして、問題ないかという、ここが普通とつけられておるところになります。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、収支予算が普通だったとお話がありましたけれども、そうした評価項目別でぜひ出してほしいと求めましたがいかがでしょうか。運営計画の収支というお話でしたけれども、そうするとよかったところはどういったところがあったのか、伺いたいと思います。","respondent":"吉野子ども家庭支援センター長","answer":"評価の項目についてですけれども、検討させていただきたいと思います。それから、(1)番の公の施設の管理者として適切な施設維持の考えを持っているかなど、そういったところが評価としては高く出ております。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、選定委員会では、お二人の外部の方が入っていると思うのですけれども、このお二人を選んだ理由を伺いたいと思います。その中でどういった意見があったのかも含めて、伺います。","respondent":"吉野子ども家庭支援センター長","answer":"こちらの外部の方ですけれども、こちらの方は、子どもに関係しております、そういったところの事業をやられていた方になります。質疑応答の回答、２つ目の母子生活支援施設、的確な回答がありましたというようなご意見をいただいております。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"もう１名の方は、どういうことをやっているのかも含めて、区の事業とかに関わっていらっしゃるのかということも含めて伺いたいと思います。母子生活支援施設の具体的な質疑について的確に答えられた、この質疑は何を質問されて、どういう答えだったのか伺います。","respondent":"吉野子ども家庭支援センター長","answer":"そういった中で、生活上の課題の整理や解決に向けての面談を行い、自立支援計画とかに沿って対応してまいりますということです。１年間のアフターケアを行うこと、利用者に対して電話を入れますというような、丁寧な対応をしていきますというご説明をしていただいた次第です。","id":"exchange-042"},{"speaker":"のだて委員","kind":"提案","question":"それはもともと提案内容に書かれていることという感じがするのですけれども、特によかった、区の認識を伺いたいと思います。これがどういったことなのか伺いたいのと、提案内容で、これまでの運営と比べて新たな提案はあったのか伺いますとの意見を述べました。","respondent":"吉野子ども家庭支援センター長","answer":"子育て短期支援事業なのですけれども、こちらは食物アレルギー対応、服薬対応など。の選定になりますので、今まで継続してやってきた事業者というところでいきますと、新たな提案はありませんでした。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"質問すれば出てくるわけですから、ぜひ資料の充実を求めたいと思います。最低賃金以下になっていることはないと思うのですが、そういったところをどう見られているのか伺いたいと思います。","respondent":"吉野子ども家庭支援センター長","answer":"これは、日本の離職率が、少し古いですけれども、２０２３年度、１５.４％になっておりますので、離職率に関しましては低いと考えております。やはり定着支援、手当とか、そういった部分で充足していると考えております。","id":"exchange-044"},{"speaker":"のだて委員","kind":"提案","question":"離職率が１３.７６％ということで、この定着支援、どういったことを提案されているのか伺いたいと思います。労務は３年、新規事業者でもやっていくということですけれども、決まったら来年やるということなのかどうか伺いますとの意見を述べました。","respondent":"吉野子ども家庭支援センター長","answer":"定着支援ですけれども、実際に業務過多、負荷がかからないように調整し、残業や長時間労働などの解消を図る。それから、労務調査ですけれども、こちらも早めにやっていただきたいと考えておりますので、そこは検討させてください。","id":"exchange-045"},{"speaker":"横山委員","kind":"提案","question":"この後１年間、利用者に対して、こちらから電話を月１回入れていくというような、そういった提案の内容ということでよろしいでしょうか。１０ページに他業種への資格取得を推奨しているというような表記がありまして、こちらはどういった形で推奨しているのか尋ねました。","respondent":"吉野子ども家庭支援センター長","answer":"原則１年間、あと、生活の状況を確認させていただいています。介護福祉士の免許を取りたいとなれば、この部分の経費とか、取った後にそういった手当もつくというような形になっております。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"イベントの参加を促していただくのも、すごく大事な視点だと思っています。定期的に確認できるような形で、そういったこともぜひ働きかけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"提案","question":"１つだけお尋ねするのですが、人材の確保と離職を防ぐための職場定着支援に対する方策の提案内容が評価できるというのと、１０ページも。社会福祉法人全体として運営が大丈夫なのですかというのは、この委員たちの意見の中では、予備委員会も含めて出てこなかったのか尋ねました。","respondent":"吉野子ども家庭支援センター長","answer":"選定委員会、予備委員会でも、人材確保のところでいきますと、法人全体で、今後、外国人籍の方も受け入れていくとか、遠隔地の方の採用とか、努力していくというようなことの提案もありましたので、委員会ではそういった努力がされていると評価された次第です。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区としても、法人としての運営をチェックしながら、または支援しながら進めていってほしいと求めました。全体の業務量と運営の体制で懸念、心配があるので、お話しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"筒井副委員長","kind":"質問","question":"家庭あんしんセンター自体、かなり多岐にわたる業務があり、なかなかそういう家庭あんしんセンターを運営したい事業者は現れにくいものなのですか。その辺りの原因はどう捉えているのか、説明を求めました。","respondent":"吉野子ども家庭支援センター長","answer":"やはり特に母子生活支援施設、いわゆるひまわり荘といったところ、そういったところでやはり二の足を踏んでしまうのはあると思います。短期支援事業であるとか、幾つか事業もやらなければならないことになりますので、手を挙げてくるところがやはり限られてくると考えています。","id":"exchange-050"},{"speaker":"筒井副委員長","kind":"質問","question":"いろいろな課題が出てきたと思うのですが、その辺りの課題はある程度クリアした、クリアに向けていろいろご努力されている認識なのでしょうか。その辺りを説明するよう求めました。","respondent":"吉野子ども家庭支援センター長","answer":"先日のモニタリングでもお話しさせていただいたのですけれども、令和７年度から、こういった人件費の部分については、委託料としまして出すような形になっていますので、その辺の課題は解消されるようになります。","id":"exchange-051"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"やはりせっかく指定管理者制度を活用しているわけですから、競争させ、よりよい事業者を選ぶというのが趣旨だと思うのです。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-06","title":"第１２１号議案、令和７年度品川区一般会計補正予算（歳出等 文教委員会所管分）","agenda":"第１２１号議案、令和７年度品川区一般会計補正予算（歳出等 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"１２月まで区としても延長するということですけれども、これから寒くなっていくので来年度に向けた購入の補助か確認させてほしいと求めました。今入所をしている人数が分かれば伺いたいのと、一遍にやらないとしても、今後必要な受け皿はどのくらいを見込んでいるのか伺います。","respondent":"佐藤保育事業担当課長、柴田子ども施策連携担当課長","answer":"こちらの考え方は令和４年度から実施していますが、一貫してそのような補助となっております。続いて、熱中症対策についてですけれども、来年度に向けた補助かですが、委員のお話のとおりです。建て替え期間中の進め方全般ですけれども、現在３６名の定員が一時的に２４名、マイナス１２名という状況を想定しています。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"今回は３,８２３万円の増額ということで、不調になった原因というのが、その公共単価によらない建設資材とはどういうものなのか伺いたいと思います。その仕上材はどこのところなのか、あと、どういったものに変えたのか伺います。","respondent":"佐藤保育事業担当課長、荒木学校施設担当課長","answer":"実績は、すみません、詳細が手元にないのですけれども、令和５年度の予算で言いますと、補正額は９,１００万円で実施しているものです。私立保育園、認可保育園や地域型等にお支払いをしています。２点目の変更した仕上材の内容ですが、こちらも何点かございまして、１点目が体育館に今回スポーツ床のシートを採用する予定です。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"いろいろ工夫をされて工事費を縮減されたということで、今回この約３,８００万円増額すると、全体では４億５,５００万円ですけれども、この額でまた不調になったら困ると、不調にならない額だというとで、区の認識を伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"この初回入札時の予定価格とは、それに対する応札も実は１者からあったのですけれども、そこの予定価格と応札額との乖離が約５億円でございました。","id":"exchange-055"},{"speaker":"まつざわ委員","kind":"意見","question":"初めから何でそういう仕上材を使って、何か変な言い方になってしまいますけれども、工期短縮の努力は何かなかったのか。今のお話を聞いていると、逆に初めからそういう仕上材も含めてですけれども、工期短縮の工夫ができたと思うのですけれどもとの意見を述べました。","respondent":"荒木学校施設担当課長","answer":"このＳＴＥＰ３の新校舎新築工事で今申し上げた仕上材を使用するのですが、この３８.５か月というのは特に変更はございません。ただ、令和１１年１２月から１月にかけて校舎完成を目指しているのですが、全体の工事期間を変えない工夫で進めていきたいと考えています。","id":"exchange-056"},{"speaker":"まつざわ委員","kind":"意見","question":"だからそういうお金も含めてですけれども、なるべくコストを落とす製品をという考え方が正しい、一般的だと。初めからそのように安くうまくやる、そしてまたしっかりしたものという考え方だと思うのですとの意見を述べました。","respondent":"荒木学校施設担当課長","answer":"委員のおっしゃるとおりで、当然区でも初回の発注時から一番これが安価で工事に適したものであろうと見込んで発注はしているのですけれども、この間。今回再入札に向けて仕上材を変更したのは、そういった理由もあります。","id":"exchange-057"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"積極的に何かそういうところはしっかり話し合って、もう少し単価を落とせるようにできるかは、ぜひやってほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"高橋（し）委員","kind":"質問","question":"その工事と今回の改築推進経費との関係がなくて、何か分離されたもので、こちらは本体の工事の話になるのですか。それともセットでなのかを少しお尋ねしたい。","respondent":"荒木学校施設担当課長","answer":"こちらの仮設校舎との区分です。今回、再入札を目指すものに関しましては、それとは別の工事請負の契約を結ぶものです。","id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"では、仮設校舎の予算の変更とかはないまま、このまま完成まで持っていけるのかが１つ。それから、ぜひ現在の予定どおりの工期になるように様々ご努力いただきたいのですけれども、そこのところはどうか尋ねました。","respondent":"荒木学校施設担当課長","answer":"１点目の仮設校舎の変更につきましては、こちらは特段予定はございません。工事の工期の変更に関しまして、受注者と発注者側でしっかりと協議をして臨んでいこうと考えていますので、その辺りは進めていきたいと思います。","id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今年の１年生が６年生になったときに何とか新しい校舎で生活できるように、今お話があったようにしっかりと工事の進捗をお願いします。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"横山委員","kind":"質問","question":"児童養護施設ですけれど、グループホームとあるのですが、小規模グループケア地域型ホームのことでしょうか。地域小規模児童養護施設と、小規模グループケア地域型ホームと多分あると思うのですけれども、少し説明いただけたらと思います。","respondent":"柴田子ども施策連携担当課長","answer":"グループホームがどのタイプに該当するかですが、施設からは、今回新たに設置を予定しているホームにつきましては、小規模グループケア地域型ホームを予定していると聞いております。","id":"exchange-062"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回裁判を起こしたということですけれども、連絡が今取れない状況で、電話とか訪問とか、連絡を取る手立てはどれだけ行ってきたのか伺いたいのと、あと生活状況などは把握されているのか伺います。","respondent":"柏木子育て応援課長","answer":"１つ目の督促に関わることですが、督促といたしましては、電話、文書、あと自宅訪問、それと自宅訪問の際に不在票を置いて実施しています。どれも複数回にわたって実施しているものです。","id":"exchange-063"},{"speaker":"のだて委員","kind":"意見","question":"裁判を起こして取り立てるのは、自治体の姿勢としてはそぐわないと思いますので、引き続き連絡が取れるように手立てを取っていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"}]},{"id":"topic-08","title":"三ツ木保育園の公私連携型保育所への移行","agenda":"三ツ木保育園の公私連携型保育所への移行","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"どのような内容をチェックしていくのかを伺いたいのと、この制度でいくと、質が高くて安定的な運営を確保できると。安定的なというのは土地・建物が無償なら確かに安定的な気がしますが、ほかのところがもしあれば伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"その中のいただいた意見については、今後の園運営に反映していますので、これも併せて実施させていただきたいと考えております。運営的にも安定して保育の質に力を使っていただけるような内容になっていますので、双方にメリットがあるという制度になっていると考えています。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"安定のところは、さっき質が高くというのは、最初のご答弁で理解しました。安定的というのは確かに建物とか土地代の負担がないし、その他で何か安定的な事業者にとってのメリットはないですかという質問です。","respondent":"芝野保育入園調整課長","answer":"失礼いたしました。５年間しっかり協定内容を遵守していただく代わりに、５年間は運営にしっかり携わっていただくことになりますので、この制度がいいと考えております。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"運営状況とか財務状況等の資料も提供義務が出てくるということで、これは新たに追加されるものなのか、どういった資料になるのか伺えればと思います。その中で高い評価を得ているということでしたが、実際どういった意見が出て、何が評価されているのかも伺います。","respondent":"芝野保育入園調整課長","answer":"この財務状況・運営状況については必要に応じてということですので、定期的に出していただく認識はございません。具体的な意見としては、公立園と比べて個別対応の手厚さを感じているという内容や。","id":"exchange-067"},{"speaker":"のだて委員","kind":"確認","question":"今、高い評価を得ているということで、利用者は良いと思うのですが、職員の環境、待遇としてはどうなのか伺いたいです。実際の今の職員配置などはどうなっているのかですとか、あと、正規・非正規の割合ですとか人件費比率などが分かれば、伺います。","respondent":"芝野保育入園調整課長","answer":"職員配置とか正規・非正規の率、離職率等々、こちらは基本的に変わらないと認識しております。協定でしっかりと一定程度の実務経験を踏まえた職員を配置してくださいというような記載をする予定ですので、今事業者とも少し話はしておりますが。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、職員の待遇は変わらないのか確認させていただきたいのと、今の運営状況で人件費率とかが分かれば伺いたいと思います。今後の予定で、１２月に保護者説明会があるということですが、日程が決まっていれば、具体的な日程も伺います。","respondent":"芝野保育入園調整課長","answer":"公設民営の場合は、運営費については国や都から特定財源が見込まれますので、区の負担としては年間７,０００万円程度になると想定しております。最後に、１２月に保護者向けの説明会ですが、まだ日程は決まっていませんが、１２月中旬辺りにはやっていきたいと考えております。","id":"exchange-069"},{"speaker":"横山委員","kind":"確認","question":"このように考えてほしいというお声があったり、今回は保護者の意見については、協定書の中にどういった形で反映させていくのかを確認させてください。ないと思うのですけれども、万が一、協定違反が起きた場合には、どのような措置が取られるのかというのも確認したいと求めました。","respondent":"芝野保育入園調整課長","answer":"反映させていくという仕組みになっておりますので、直接書くというのはないと思いますが、その中で反映させていただきたいと考えております。協定違反をしてしまった場合の対応ですが、そちらでしっかり担保していきたいと考えております。","id":"exchange-070"},{"speaker":"横山委員","kind":"質問・要望","question":"起きないことが第一だと思うのですけれども、万が一そうした場合にはどのようになるのか、確認させていただきたいと思っています。","respondent":"芝野保育入園調整課長","answer":"失礼いたしました。万が一そういったものが生じてしまった場合には、協定に基づきまして、必要であれば法人の指定の解除という形になろうかと思います。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問","question":"どうしても民営化すると何かの行事をやるからとか、新たな保育を入れるからということで、徴収です。ですから、それが５年生きるのではなく、その辺はいかがか尋ねました。","respondent":"芝野保育入園調整課長","answer":"こちらも負担が生じないように、しっかりと協定書の中で記載していきたいと考えております。見直しにつきましては、何か生じた場合にはしっかりとそこで協議して良い方向に向いていくように見直しをしていく形で進めていきたいと思います。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"意見","question":"公私連携型保育所としてうまく運営していくかどうかというのはやはり今回にかかっていますので、しっかりとお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"若林委員","kind":"質問・要望","question":"逆になぜ最初から公私連携型ではないのかも含めた意味とか意義をお聞かせいただきたいのと、順次、５年間の検証もしつつという考え方はどうなのか。この２点、確認したいと求めました。","respondent":"芝野保育入園調整課長","answer":"１つ目の平成２８年の民営化基本方針を定めたときに、なぜこの制度を検討しなかったのかということですが、把握してないところです。そのような条件を踏まえまして、この制度を活用した民設民営化の検討は順次行っていきたいと考えております。","id":"exchange-074"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"会計年度職員の交通費支給について質問されて、答弁は前向きに検討を進めるというようなご答弁だったのです。その交通費に関して具体的にどういうことを想定、あと、その経験年数といわゆる報酬との関係についても関連して検討されていくのかというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/843512?Template=document&Id=7221#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":57043,"voices":246}},{"id":"r07-20251125-5","meetingId":"r07-cm11","date":"2025年11月25日","dateIso":"2025-11-25","committee":"総務委員会","time":"午前１０時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認だけします。次の工事も予定されていると思うのですが、その調整はどのように図られたのか、説明を求めました。","respondent":"長尾施設整備課長","answer":"施工者の現場代理人であるとか技術者の配置については当初予定よりも延びているところではありますが、その辺りは双方で協議した上で工期延伸というところで調整が整っておりますので、過大な負担をかけて無理強いをしているというような状況ではございません。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"下請の方もたくさんおられると思うのですけれども、その調整を含めた形で大丈夫ですということなのか尋ねました。","respondent":"長尾施設整備課長","answer":"現在、工事としましてはまだ、地中障害物を撤去して、土をとめるための土留めの工事をやっている最中でして、そこに関わっている下請業者も含めて調整をしているという状況です。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"人件費等は年に１回、そんなことがあるのですかと逆に言われたのですが、その辺についてご見解をお聞かせください。機械でも「１年ないし早くても２年で、何かすごくギャップがあるのですが、その辺についてどのようにお考えか尋ねました。","respondent":"佐藤経理課長","answer":"人件費については、国が設計労務単価という基準になる単価を、基本的には年に１回改定して出していると。そういったところで感覚のずれはあろうかと思いますけれども、工事全体としては上がっていっているというところは確かかなと考えております。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"実際、何のために行政としてインフレスライドを採用して、労務単価をこうやって上げているのかなと。二次下請、三次下請には行かないのではないかという疑念まで持ってしまうのですが、そういうことはないですよねとの意見を述べました。","respondent":"佐藤経理課長","answer":"まず、その調査結果に基づいて幾らというのを出しているということですので、市場の中で人件費が上がっているというのは確かなのだと思います。近年、そういったところにお金が行くようにということで取り組んでいるところですので、そういった形だと思います。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"ぜひともそういう一次・二次・三次下請にも賃金アップが回るように、区としても何かよい方法を考えていただいて、確実に渡っているのだという確証をとるような方法を考えるべきではないかなと申し上げて、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"そこまで確認をとっていないのですけれども、変更の幅というものも、それは今回どうだったのでしょうか。なので、１か所がということではないと思うのですけれども、それはいかがなのか尋ねました。","respondent":"佐藤経理課長","answer":"変更額の幅が５％以内に収まるということで、本日この後ご報告しますけれども、機械設備工事のインフレスライドに基づく契約変更があります。本体の建築工事については、やはり５％以内ということで、後ほど専決処分の報告をします。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"これからまたインフレスライド条項等で変更せざるを得ない状況があるのではないかという予測は立てられているのですか。いかがか尋ねました。","respondent":"佐藤経理課長","answer":"１点目の議決にするかどうかというところは、委員からもお話がありましたけれども、議会のほうで議論いただくところかなと考えます。協議があれば、契約変更について応じていくという立場でありますので、今後もそのように対応していきたいと考えております。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"ただ、１０年間増えているのだから、このままいくと工事が終わるまでにこれぐらいの負担がでてくるのかなという予測は立てられているのですか。いかがか尋ねました。","respondent":"佐藤経理課長","answer":"それがどのぐらい上がるかというところを見通すことはなかなか難しいのかなと考えておりますので、ご議論いただいた上で議決いただいているということですので、今後についても同様かと考えています。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"これはなかなか委員会の中で話ができるような内容ではないと思いますが、そういうのは多分計算しているのだろうなと私は思っています。もしも仮に不十分であれば、そこを強化していただきたいと考えていますので、これは意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"賃金が行っているかどうかということは、やはりきちんとそのケアと確認はするべきだと私は思いますので、しっかり区としても検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"令和７年請願第２０号、生理用品配布の拡充に関する請願を議題とし、審査を行いますが、予定表３、報告事項(13)総合庁舎女性トイレへの生理用品の設置","agenda":"令和７年請願第２０号、生理用品配布の拡充に関する請願を議題とし、審査を行いますが、予定表３、報告事項(13)総合庁舎女性トイレへの生理用品の設置","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"そういう思いというのでしょうか、そういう認識で検討されていくのかというのを伺いたいのと、生理用品が必要な方にはあるわけです。防災備蓄品がなくならずに継続できているというところで、配布の実績というのですか、ここで分かるのか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"場所については検討していきたいなというところはありますけれども、ただ、そういうところで使っていくことはできないのかなというところはあります。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"購入に困っている方、確かに区の考え方の配布だと、場所はそういう相談できる場所があるというところに限定されていくのかなと思います。今後そこへの設置はどう考えているのか、庁舎の３階と７階の女性トイレ、それで３階と７階の女性トイレの２か所になった理由も伺えたらと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"１つ目のお尋ねの公共施設を広げる予定はあるかというところですけれども、検討については、それを見ながら進めていきたいなと考えています。こちらについても、まず実施してみて、検討していこうと考えています。","id":"exchange-012"},{"speaker":"澤田委員","kind":"質問","question":"お聞きしたいのが、５０名程度取りに来られる方が継続していらっしゃるということなのですけれども、学生はいるのかなというのを教えてほしいと求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"申請は必要かというところに関しましては、申請は必要ありません。学校にはあるけれども、学校以外の場所での使用もありますので、そういうものについては取りに来ているのだなと考えております。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"だとすれば、例えばきゅりあんとか文化センターとか大きいところに、１００円とか入れてがしゃんと出てくる販売機があるではないですか。これは男性の方は分かりにくいと思うのですけれども、女性のほうが分かりやすいと思うのですが、そこら辺、考え方としてどうか尋ねました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"「優しさをかたちにプロジェクト」を少し広げて、「お困りの方も使っていいですよ」というような考え方で実施していますので、請願についても。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"それから、突発的な状況というのを考えたときに、私はどうだろうなという思いがあります。防災備蓄品の有効活用の一端と、そこはもっと周知徹底していただければいいのかなという思いがありますので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"生理用品の配布で、防災備蓄品を活用するということなのですけれども、この活用の仕方についてもう少し詳しく教えていただきたいと思っています。今年度、追加購入をどの程度されているのかという数が分かれば、教えてほしいと求めました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ただ、区としては、区としては５年で回していくという考え方でやっていると聞いております。今トイレに設置させていただいているものに関しても、多分使用の意図とは違うのでしょうけれども、夜用と半々ぐらいで置かせていただいております。","id":"exchange-016"},{"speaker":"塚本副委員長","kind":"提案","question":"かつてうちの会派から質問と提案で、広告を１つの原資として、広告を表示すると。このものについての検討はされたのか、今されているのか、現状をお聞きしたいと思いますとの意見を述べました。","respondent":"木村人権・ジェンダー平等推進課長","answer":"検討もいたしましたが、でも、庁舎内のほとんどのトイレは電波が入らないのです。今やる形としては、それを置くという選択肢は、今すぐには考えていなかったというところはあります。","id":"exchange-017"},{"speaker":"塚本副委員長","kind":"意見","question":"現状はよく分かりました。いよいよ始まったところでもありますので、そういった新たな環境の中で、また導入に向けての検討みたいなことは今後もお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"無料のやり方もあるわけですから、そんなに設置場所もかからないし、区が考えている多くの人を支援すると。そういうような方法でやっていかれたらどうかなという、今そういうふうに思いましたので、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出す、不採択でお願いいたします。先ほど質問させていただいて、運用についても検討されていくと思いますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"先ほどご質問させていただきましたが、使用期限はないものの５年で回しているというところで、支援につなげていただきたいというところになります。項目４のところで、予算を確保し恒常的な支援として位置づけてほしいという、「優しさをかたちに」ということを広げていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"塚本副委員長","kind":"質問","question":"支援していきたいというのですか、防災備蓄品を使って、現状ではそこの中で収まっていると。足りなくなって配れないということはないということもありますので、現状の考え方で進めてほしいと求めましたので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今や全国的なのですかね、そういう中で区が庁舎内にというところは、すごく大事だなと思っています。反映していっていただきたいなと思いますので、それを後押しするという立場で、採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"松本委員","kind":"確認","question":"これは確認しながら検証というところで足りるかと思うのですが、１回起きてしまうと、ここは結構慎重に考えないといけないと。今回の備蓄品を使うのと比べて、そこは時流に合わせて考えていただきながら対応していただければと思って、うちの意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということと、不採択でお願いします。請願項目については慎重に進めるべきだと思いますので、ということを考えた上で、じっくり進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"西本委員","kind":"提案","question":"私が提案した、そこは総合的に考えていただきたいのですが、ただやみくもにばらまくみたいな状況はやめてほしいなと思います。慎重にという話もありましたけれども、やはり慎重に考えていただきたいと思って、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-03","title":"令和７年陳情第４４号、区民の知る権利として、適切な中身のある議事録を公開することを要求する陳情","agenda":"令和７年陳情第４４号、区民の知る権利として、適切な中身のある議事録を公開することを要求する陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"原案のとおり承認された」という、これのみなのですけれども、助成する事業を選定していくわけではないですか。もう少し書けるのではないかなと思うのですけれども、そこら辺、区としてはどのようにお考えか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"現状、ＳＤＧｓ推進・行財政改革特別委員会等で報告しているような資料については積極的に公開するように、ホームページ等に上げているところです。なので、現状といたしましては、公開可能な範囲で、区民の方に分かりやすく情報公開できるように努めているところです。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"提案","question":"でも、言われていることは至極真っ当だなと私は思うのです。もうちょっと議事概要の中身を改善させていくことを提案したりすることが区のほうからできるのか、それとも、そこを伺いたいと思いますとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今後の議事概要の公開内容に改善の余地があるかどうかというご質問です。会議録については基本的には公開をしていって、実行委員会としても、引き続き実行委員会の中で検討してまいりたいと考えております。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"あれもさんざん経緯を説明してほしいということから出てきたということがあるので、なぜやるの、何のためにというのが分かりにくくなっているなと。なので、説明責任をどう考えられているのか、区としての考え方をお尋ねしたいと思うのですが、いかがか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２点目としまして、本陳情にありますように、納税者の税金を投じる事業を決定した経緯の説明責任というご質問です。そして区民への説明責任、こういったもののバランスを考慮しながら、可能な範囲で引き続き情報公開の充実に努めてまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"どこをどうやって従ってそう決めたのですかというところまで追及したくなるような状況です。これは改善していただきたいというふうに私は要望としてまとめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明のとおり、次年度もっと使っていくためにはどうしたらいいかとか、そういったものはもう少し載せるべきなのではないかなと思うところです。区民目線で情報を発信していくということでいうと、そういう事情も含めて説明することが求められるのではないかなと思うのです。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"議事概要にお示ししております審議の内容等につきましては、どの程度どのような議論がされたのかというところは、ここでの説明は控えします。区民目線での説明といったときに、重要だと認識しておりますので、引き続き実行委員会のほうで検討してまいりたいと思います。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、それはきちんと、こういう訳でできないのですと。３年か５年か分からないですけれども、人は入れ替えて、できるだけ公正な対応状況を生めるように実行委員会を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"澤田委員","kind":"意見","question":"理由としましては、区としても条例にのっとってご尽力いただいているものと理解しておりますし、今後も改善されていくものと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"山本委員","kind":"質問・要望","question":"透明化をぜひ進めていただきたいと強く要望します。ぜひ実行委員会に申し入れていただいたり、対応していただいて、その結果も今後教えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"１と２とあるのですけれども、２については、そういう理由です。１番については、ウェルビーイング・ＳＤＧｓ推進ファンド事業に対しての要望ということで、不採択というところになります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"高齢者福祉にしても障害者福祉にしても、そうした改善もずっと求めてきました。それを企業にも理解していただきたいなと、そういう立場に区は立っていただきたいなと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"松本委員","kind":"質問・要望","question":"加えて、点数も、上回っているところについては公開していくというのも一つの方策ではないかと。それは、公開の在り方というのは実行委員にももう少し考えていただきたいと私は思っておりますので、採択というふうに申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須貝委員","kind":"提案","question":"応募による提案ということですから、理由等について公開するということは、私はまた一つの弊害につながるかと思います。競争という原理がある以上、なかなか難しいかと思いますので、今回の陳情については不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"情報公開、その根拠となるもの自体の見方とか考え方とかということを考えていかなければならない時期に来ているのではないかなと強く感じました。様々なご意見をいただいて参考になるなと思いましたけれども、現状としての判断となると、不採択にならざるを得ないかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-04","title":"令和７年陳情第４６号、「税負担化」の実態を隠す「無償化」表現の是正を求める陳情","agenda":"令和７年陳情第４６号、「税負担化」の実態を隠す「無償化」表現の是正を求める陳情","exchanges":[{"speaker":"西本委員","kind":"質問","question":"そんなことありませんと思うのか、それは理解するけれども、でも、区として無償化という言葉を使うというふうにするのか、どちらですか。そして、やはり、これ全部税金ですから、その説明をきちんとしなければいけないと思うのですけれど、そのお考えはどうか尋ねました。","respondent":"加島財政課長","answer":"区政方針につきまして、それを区民の税金で、社会全体で負担していくということを明確に述べてきたところです。広報等を活用して年に２回、そういったところを通じて、この陳情者の趣旨にあるような分かりやすい表現というのも努めてまいりたいと考えております。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜ、なぜ子育てばかりにお金かけるのですか、税金使うのですかというふうに思うのは当たり前ではないですか。誰がお金払っているのですか、納税者は誰ですか、その納税者の中で合意が取れているのだったらいいかもしれない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、それが使われているというのが、多くの方がもう、理解されていると思います。税の役割だと私たちは思っているのですけれども、区の考える、この税の役割というのがあれば教えていただきたいのです。","respondent":"加島財政課長","answer":"区民に対してどのような行政サービスの形で還元できるかということを考えていくことが、まず、本旨だと考えております。これから少子高齢化社会を迎えていくに当たりまして、私どもとして、税を使って何ができるかというのは考えてまいりたいと思います。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"提案","question":"私たちも区議会議員ですから、区民の様々な、これが必要だ、これをしてほしいという声に応えて様々要求しているわけです。どういうふうに呼ぶかという提案がありますけれども、大変分かりやすいし、的確なのではないかなとは思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"須貝委員","kind":"意見","question":"中には賛同する方もいらっしゃる。この無償化という言葉を使って表現するというのは、何ら不思議なことではないと私は思うし、このまま続けていい言葉だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"澤田委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。先ほどご説明にもあったとおり、無償化の表現や税についての考え方を我々の会派としても感じておりますし、不採択というところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"山本委員","kind":"質問","question":"公費負担であるということ、これは事実でありますので、正確に伝えていくことが必要になってくるかなと思います。なので、そういうふうに様々進んできたときには、先々、そのような検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"塚本副委員長","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。陳情者の方の税の一つの見解から出てくる、無償化で全然よいかと思いますので、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。やはり様々要望がある区民の皆さんの要求をさらに教えていただいて、私たちも区議会で求めていくということも進めていきたいなと思っていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"松本委員","kind":"質問・要望","question":"憲法２６条２項は、義務教育はこれを無償とする、という、一番大きなところでも無償という言葉を使っている。逆にその無償化という言葉をやめて、全部公費負担とか税負担とかいう言葉に改めましょうというのも、それもそれで違うと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜ無償化するの、なぜそういうふうにやるのかということの説明が本当に少ない、足りないと非常に思っています。そういう方向に持っていくべきだろうし、事実いますので、それを支持したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]},{"id":"topic-05","title":"令和７年陳情第５１号、職員団体の組合費給与天引き（チェックオフ）手続の適正運用および行政の政治的中立性確保を求める陳情","agenda":"令和７年陳情第５１号、職員団体の組合費給与天引き（チェックオフ）手続の適正運用および行政の政治的中立性確保を求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。問題があるのであれば双方で話し合って、解決していくものと思っていますので、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということと、不採択でお願いします。組合の中の話なので、私は組合の中で議論して進めていってほしいと求めましたが、今回に関しては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"西本委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。品川区は該当しないということでのご説明ですので、これに該当しないと思うのですが、少し１件確認してよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"西本委員","kind":"確認","question":"終わって、確認したいものが１つあるのですけれど、この陳情はなぜ委員会にかかったのか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"確認","question":"委員長に聞きたかったのですが、意見書は紹介議員がいないと、ということなのですけれど、これはすみません、それだけの確認。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-06","title":"令和７年陳情第５５号、新たに給付金か食料配布を求める陳情","agenda":"令和７年陳情第５５号、新たに給付金か食料配布を求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったところでは本当に早急に手を打っていただきたいな、もっと早く、もっと迅速にやるべきだなというのは思っていました。新たな給付金か食料配付ということで求められておりますが、区の独自の給付金１人３万円というのが実施されまして、１４０億円ぐらいでしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に１万円でも２万円でも手元に入れば、したらどうかなというような思いが、これを読んでいてしました。３万円のときが１３５億円ということであれば、そういったことをぜひ検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"加島財政課長","answer":"今回、食料品等の価格高騰に対する支援を行うというふうに述べておりますので、区としてはまず。この重点支援地方交付金を使うことの中で区民のほうに速やかな支援を届けてまいりたいと考えておりますので、独自での給付金は考えておりません。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に迅速に対応していただきたいなというところで、そして給付金ということにぜひ応えていただきたいなと思いますけれど、その実績を聞いても……。〔「所管が違うのでは」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問","question":"お聞きはしたかったのですけれども、どういう形があるのかあれですが、可能なのですよね。〔「所管外だと言っているのだ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"だけど、企画課とか財政課もあるので、そういったところで、可能なら、もしそういう申出が、所管がどこなのかどうか、そういったところも、分かる範囲で教えていただけたらと思います。","respondent":"加島財政課長","answer":"申し訳ございません、実績については持ち合わせておりませんで、区として事業の一つとしてフードバンクができるかというところなのですけれども、所管のほうに意見をお伝えさせていただこうと思います。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"実際にこれ求められていることを実施するという部分では多分所管が違ってくるだろうなとは思ったので、なかなか、分かりました。引き続き、国が出したというところで、もっと前倒しで区として独自にやっていただけることがあったらやっていただきたいなとのが、私の思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"先ほど、財源が豊かなどと質問の中であったのですけれど、財源が豊かですか。〔「また難しいところだな」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問","question":"その中で、では財源どうですか、財源は大丈夫ですかということなのです。私はそんなに潤沢に、やりくりきちんとしていかないと赤字になってしまうのではないかなというぐらい思っていますが、いかがなのか尋ねました。","respondent":"加島財政課長","answer":"こういう規模の大きな経済対策につきましては、国の交付金を活用することによって区民の方に支援を届けておきたい、そんなふうに考えております。移動支援をどう取り組んでいくかというところで、区として様々どういう支援を伸ばせることができるか、複合的な施策の展開によって。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区としてこういう問題が出てきたときに、要求出てきたらどこまで答えられるのですかという、そんなに潤沢に財源ないでしょうという話です。そこの線引きというのはある程度決められているのですか、まだこれからなのでしょうか、区としての考え方です。","respondent":"加島財政課長","answer":"それは例えば今年度でしたら決算見込みだったり、令和８年度の歳入予測であったりというところ、目下のところを少し考えていくことになります。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"だけれど、きちんと説明責任を持って、こういうところに税金を使わせていただきますという説明をこれからしていただきたいなと思っています。できる限り努力していただき、財政負担というのもしっかり見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区独自の生活救済措置ということを実施してほしいということですけれど、そういうふうに政府がやってくれたのだからいいかと私は思います。もう、すぐにでも助けてほしい、支援してほしいという方に重点的に支援をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"澤田委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。さらに対応が必要であれば適宜検討もあるかもしれませんが、まずはこちらからといったところなのかなということで、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"山本委員","kind":"意見","question":"国のメニューにもよりますが、支援が必要な区民の方に幅広く行き届くような支援の仕方の検討を進めてほしいと思います。無駄な事務費用を使わない、効率的で有効な手段の検討についても、併せて検討を進めることを望みますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"塚本副委員長","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。物価高に対する対策というものが一定なされるというところを見て、当分はこちらで進めてほしいと求めましたので、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、本当に今、２０２１年に物価高が本格化していますので、その間ずっと苦しい人は苦しいわけです。本当に困っているので何とかしてほしい、ぜひ区としての給付金や食料配布を、区の税金で実施してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"松本委員","kind":"提案","question":"２１日に国のほうで総合経済対策が出てきましたので、まずはこれを確認してからというところかと思います。こうしたことを審査して提案するためには、これがうまくいくのではないかなということを発言させていただきまして、意見としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"午前中の議案に続いて、やはり改めてこのインフレスライド条項による変更が多いなと感じた次第です。少し改めて教えていただきたいのですけれども、インフレスライド案件の数がどう推移しているかというのを教えていただきたいというのが１点と、あと。","respondent":"佐藤経理課長","answer":"昨年度決算で令和６年度は１７件、契約変更しておりまして、１１億６,０００万円ほど増額しております。２点目のほうですけれども、その結果として、契約変更の手続について経理課のほうで担当しているという形です。","id":"exchange-072"},{"speaker":"山本委員","kind":"質問・要望","question":"一昨年からという質問させていただいたのですが、少なくとも足元では増えているということで確認をさせていただきました。具体的には事務負担軽減、それから実際その件数も増えていくというところでいうと、人件費というところも含めて予算に織り込んでいただきたいなです。","respondent":"佐藤経理課長","answer":"２点、インフレスライド条項の適用に関する負担の対応ということかと思います。人員の確保についてはそれぞれ、経理課もそうですし工事所管課もそうですけれども、人事関連課と協議しながら進めているです。","id":"exchange-073"},{"speaker":"山本委員","kind":"質問・要望","question":"お伝えしたいところとしては、物価が上がることでいろいろなところにすごく影響が及んでいて、そういったところそれぞれに負担が多分かかっていると思いますので、そういったところにも目を向けて、来年度予算に向けて進めていただきたいというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]},{"id":"topic-08","title":"専決処分の報告について（報告第３６号）","agenda":"専決処分の報告について（報告第３６号）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"大分前も指摘したことがあるのですが、庁舎の車は、追突防止の安全装置、センサーなどというのはまだついていない車がたくさんあるのですか。誤って追突したということですけれど、通常、そういう装置がついていれば相当軽微なものに終わったかと思うのですが、説明を求めました。","respondent":"佐藤経理課長","answer":"私のほうからお答えしますけれども、そういったところは車検のタイミングでつけられないかというのも検討したのですけれども、結論的にはそういった安全装置がついていない車も多数あります。","id":"exchange-075"},{"speaker":"須貝委員","kind":"質問・要望","question":"数年もう乗りこなしているならば、多少費用がかかったとしても、やはり安全な車に切り替えていくべきではないでしょうか。人間ですから、そういうところを補うためにその安全装置車が今普及しているので、そういうところはしっかり考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-09","title":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"何がどういうものを私的流用したのかなどという、対応も言えません、という状況で終わっていたかと思います。なぜそう、その根拠をしっかり示してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=7271#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":63585,"voices":240}},{"id":"r07-20251126-6","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"区民委員会","time":"午前１０時１０分～午後 ２時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"区内事業者向け経営相談・融資あっせんＷＥＢ面談システム運用開始","agenda":"区内事業者向け経営相談・融資あっせんＷＥＢ面談システム運用開始","exchanges":[{"speaker":"おぎの委員","kind":"意見","question":"１月５日から始めるということで、今後ずっと実際の面談とウェブというので併用していくのかということが１点と、１日の受入れ枠などです。相談を受け入れる件数と、順番に窓口に来たときと同じような形で何人かで対応に当たるのか、その辺りをお聞かせいただけたらと思いますとの意見を述べました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"このウェブの比率が増えていけば、その段階で今後、一本化するのか、そこはまた将来的な検討になろうかと考えております。２点目の誰が対応するのかといったところですけれども、そこはウェブでも変わりません。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問・要望","question":"継続していくということで、ニーズといいますか、要望を聞きながら調整していただけたらと思います。今までの方が対応するということで、場所はやはりこの事務所内になるのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"１回当たり１時間の相談枠を設けておりまして、これは現在も基本的にはその時間で区切ってお答えをさせていただいているところです。相談に当たっているのですけれども、ウェブ用のモニターも配置して相談に当たるといったところを考えているところです。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"意見","question":"個人情報というのも会社の情報を取り扱うことにもなってきますので、そういったことにも配慮されている形であったらいいかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"結局、余計にやはり個人の事業主の方にはその辺、寄り添った対応をしてほしいと求めました。その辺り、中小企業支援サイトに掲載とは書いておりますけれども、具体的に教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"いろいろな文言でヒットできるような、そういう言葉を使って皆様の検索に引っかかるような、そんな工夫はしてまいりたいと考えております。","id":"exchange-004"},{"speaker":"こしば委員","kind":"質問・要望","question":"チャットボットだとか、あとはそれこそトップページにばんと載せてもいいと思うのです。そのぐらい、すぐ目に見えるような形で取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"オープンカレッジのことでお聞きしたいのですけれども、そもそもリカレント、これ自体がそもそもリカレント教育には多分ならないとは思うのです。その辺りのお考えについて教えていただきたいのが１つと、私はそう認識しているのですけれども、その辺り。","respondent":"大森文化観光戦略課長","answer":"現在の仕事で必要なスキルの変化に対応していくために新しいスキルを習得することというような話だったので、今までの品川区のやり方だったりとか。なので、知識の上書きというところから始めていって、今後様子を見ていきたいなと思っているところです。","id":"exchange-006"},{"speaker":"こしば委員","kind":"質問・要望","question":"その辺り、現役世代の方々が社会の中で生きる中で何を求めているかというのはアンケートもいろいろあるとは思うのですけれども。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私も星薬科大学で年２回の春と秋の薬草のお話のときなどは参加していて、どういったことを想定されていて、教えていただきたいなと思います。","respondent":"大森文化観光戦略課長","answer":"広がりとしてやはり、大学ほど広がっていないなというふうに、肌感はそういうところを感じているところです。地元の高校とせっかくつながりがあるので、もう少し何か、連携を強めるような企画を提案していければと考えています。","id":"exchange-008"},{"speaker":"おぎの委員","kind":"提案","question":"１６歳以上ということは高校生も対象になっていますので、生徒もうまく巻き込みながら、皆さんが参加できる企画があればいいなと思います。私も考えて、何かアイデアがあったら提案したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"せらく委員","kind":"質問","question":"私からもオープンカレッジの課題で上げている点についてお聞きしたいのですけれども、参加者の７６.５％が６０代以上と偏りがあると書かれています。","respondent":"大森文化観光戦略課長","answer":"オープンカレッジの実施の時間や曜日ですけれども、やはり開催日時は、主となるものが平日の午後２時や４時などが多いのです。今考えていることなのですけれども、できる部分で若い世代、子育て世代等にリーチしていくものができたらなと考えています。","id":"exchange-010"},{"speaker":"せらく委員","kind":"提案","question":"子育て世代という言葉も出てきまして、今後の展開については楽しみにして、私も何か提案できることがあればしていきたいと思います。追加でもう１点、オープンカレッジ自体は無料で受けられる講座なのか確認させてくださいとの意見を述べました。","respondent":"大森文化観光戦略課長","answer":"それから、生涯学習というものに興味を持っていただいた方にそのまま継続していただいているというところがあります。シルバー大学同窓会も一緒なのですけれども、生涯学習とか仲間づくりといったものにご興味がある方が継続してくださっていることが多いです。","id":"exchange-011"},{"speaker":"せらく委員","kind":"意見","question":"それから自分も学びながら支えていく側になっていくということがすごくいい循環になっているなと感じました。そういったところもオープンカレッジを通じてできるといいなというふうに、感想にはなりますが、そう思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"藤原副委員長","kind":"質問","question":"この中で一番高齢者ですから。どうか尋ねました。","respondent":"大森文化観光戦略課長","answer":"ただ、高齢の方の学びというものはある程度形としてはできているのではないのかなとも考えております。人が集まる講座といったものを研究していく、検討していくというのは必要なスタンスなのではないのかなと思っているところです。","id":"exchange-013"},{"speaker":"藤原副委員長","kind":"質問","question":"それはそれでいいのではないですかという意味で言っていて、若い人はどんどん参加してくれればいいわけですから、会場の確保が課題になっているって。いかがか尋ねました。","respondent":"大森文化観光戦略課長","answer":"会場の確保については、中小企業センターを使ったり、私たちの所管である文化センターを使ったりなどということで、あとは大学ですね。なるべく区民の皆様にも使っていただく施設として空き状況を確保するというところに努めていかないといけないのかなと思っているところです。","id":"exchange-014"},{"speaker":"藤原副委員長","kind":"質問","question":"そこを活用していくということで、こうやって区民委員会でも、部は違いますけれども、地域センター所管の課がいるわけですから、地域センターの活用。今、課長のご答弁の中に地域センターという一番会場としては個数があるところが抜けているのではないかと思うのですけれども、いかがか尋ねました。","respondent":"大森文化観光戦略課長","answer":"シルバー大学の会場にも区民集会場と書いてあるように、あえて新たに開拓するところというところでは挙げなかったというところで、すみません。本当に地域振興部にはとてもお世話になっているというか、非常に協力をいただいているというところを付け加えします。","id":"exchange-015"},{"speaker":"おぎの委員","kind":"質問","question":"今の藤原副委員長の場所の確保という話から、私もそういえば、１点思い出したことがありまして、講師の確保の面なのですけれども、シルバー大学、オープンカレッジ等で講師を務めていただく方への謝礼といいますか、お礼というのはどういった感じになっているのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"講師の謝礼につきましては、内規というような形がございまして、かなり事細かに決まっていて、そんなに多くは支払えないところはあるのですけれども、皆様、今、その金額でご納得いただいた上でご協力いただいているです。","id":"exchange-016"},{"speaker":"おぎの委員","kind":"質問・要望","question":"できれば先生にも交通費を出してあげてほしいみたいなお話は上がっていますので、検討していただけたらなと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西村委員長","kind":"質問","question":"私も質問させていただいていいですか。やはりその中で培われてこられているチームワークだったり、実際に行かれてお感じになった感想も含めて現場感を伺ってよろしいか尋ねました。","respondent":"大森文化観光戦略課長","answer":"月１回、第１日曜日、第３日曜日に実施している各コースにも参加しております。大体３時ぐらいに終わってから、そういった現実があるかなというところの中でそういう気持ちのある方々に支えられている会であるなと考えています。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=7229#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":17078,"voices":52}},{"id":"r07-20251126-7","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"厚生委員会","time":"午前１０時１０分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件整理しています。","topics":[{"id":"topic-01","title":"（仮称）小山七丁目障害者グループホームの開設時期の変更","agenda":"（仮称）小山七丁目障害者グループホームの開設時期の変更","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"幾らぐらいのものが、今回、高騰で幾らになるのか。東京都の補助金と品川区の補助金があると思うのですけれども、その補助金の額も教えてほしいと求めました。","respondent":"佐藤障害者施策推進課長","answer":"建設費の総額というところかと思いますが、１,０００万円ぐらい、当初の想定より増額になっているというような状況と聞いております。それから区の補助金が５,０００万円ほどということで、１億３,０００万円程度の補助金が支給されるグループホームとなっています。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"ここは１０人の施設ということだったと思うのですけれども、何人くらいの応募があったのか。入居に当たっての入居者の選定の仕組みというのがどうなっているのか、伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"建物が２月頃の竣工を予定しておりまして、４月頃から見学等も含めて、事業者のほうでは予定していると聞いております。事業者からは区分４以上が５名以上入れるようにというところで提案を頂いているところですが、検討中、協議中というようなところであるのが現状です。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"その点も伺いたいと思います。その点についても伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"事業者のほうで検討しているような状況で、区としましては、確認して協議していくというようなことを考えているところです。新規採用を６割程度、見込んでおりまして、八人の新規採用が必要かというところを考えているということです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"提案","question":"この入居者募集については、出石つばさの家のときも、かなり応募が多かったと思うのです。事業者からの提案もあって、公平性・透明性が確保できるような仕組みにぜひともしていただきたいということでお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"何か予算など、今回は別に変更の議案というのはないのですけれども、例えば区の計画の中でどういう影響があるのか。その辺について説明を求めました。","respondent":"佐藤障害者施策推進課長","answer":"総額としては大きく変わるものではございませんので、そこの時期がずれていくというところが１つあるかとは思われます。令和７年度中開設ということで見込んでいたところが、必要な部分についての支援は、細やかな対応で進めていきたいと考えております。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"着工の時期はいつですかという質問をしたのですけれども、一、二か月ほど遅れたということで。その理由のところをしっかり、きちんと伝えていただかないと、議会への報告ということで私たちは伺っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどお伺いして感じたのですけれども、１,０００万円の増額で、調整に相当そんなに難航したのかなという新たな疑問もやはり生まれてしまいました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"どういう方たちに入居していただくかによると思うのですけれども、そういうことへの新たな補助などというものは何も考えられていないのでしょうか。事業者との話合いなどはしておられるのか、現時点でお話しできる範囲で教えていただきたいと思うのですが、いかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"こちらの施設の運営に関しては、きちっと対応していくことを予定している事業者と、こちらでは認識しています。利用の支援やケアの部分については、丁寧に対応していくというようなところで、きちんと対応していくというようなところで。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"個別の相談とともに、今日は議会への報告を受けておりますけれども、利用を想定されている方たちへの説明会などというのは行われないのでしょうか。今までのご説明にあったら、聞き漏らしたのかもしれませんけれども、その点をもう一度説明を求めました。","respondent":"佐藤障害者施策推進課長","answer":"今のところはございませんが、そういったところが出てきた場合は、当然、対応については、こちらでもすることになります。この内容そのものについての説明会というのはまだ行う予定はございませんが、施設の説明・見学というところでは考えているということを。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"大変誠実に対応はされているとは伺っておりますが、しっかり区としても関わっていただきたいなと思って、その辺を強く要望しておきます。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点確認なのですけれども、開設時期が遅くなったということで、それに伴って、区から法人に対して何かしらのペナルティなどといったものはあったりするのか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"特段、ペナルティというようなところはございません。そういった部分で影響が全くないとは言えない状況ですが、特段、これに対して何かこちらから課すというところはございません。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"確認","question":"令和８年３月３１日までなのかなというところで、その辺はもう、おとがめなしということでよろしいのでしょうか。確認です。","respondent":"佐藤障害者施策推進課長","answer":"おっしゃるとおり、事業者の公募の時点ではそういった形でさせていただいておりましたが、今回の理由に関しましては、社会情勢等に鑑みて、やむを得ない理由というところで考えておりまして、そこについては、特段の対応というのは予定しておりません。","id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"質問","question":"使用貸借の契約から３０年ということなので、これは３か月ずれたことによって、契約期間の開始と終了はずれてくることはあるのでしょうか。説明を求めました。","respondent":"佐藤障害者施策推進課長","answer":"こちらの契約の開始期間については当初の想定どおりで進めてございまして、ずれた時期を鑑みまして、そこを変えるところまでの予定はしていないというところで、業者とも確認しています。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"あくつ委員との質疑の中でも詳しくいろいろ事情をお伺いしたので、やはり区側としても受け止めてほしいといいますか、その辺はいかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"そういった情勢も踏まえて準備を進めているところで、今回の事例も踏まえて、そういったところの確認・調整等は十分にしていきたいです。どういった形で運営していくのかというのは、その都度、判断していきたいと考えております。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そうですね。もし何か不測の事態があれば、早めに動けるというか、対応できるような体制を取ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"意見","question":"この間、区としては、５や６の重度者の方をここのグループホームに入居させてほしいというふうなことというのはどう考えられているのか。その点を説明するよう求めました。","respondent":"佐藤障害者施策推進課長","answer":"５・６というところも視野に入れて入居していただけるような形で、事業者とは、申込みの流れも含めて検討いただいている。支援区分だけで、それからリフト浴対応の居室等も設計ではしていると受けておりますので、一定程度の対応はできると認識しています。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"意見","question":"軽中度と重度ということで、グループホームがどれぐらい必要かという所要量を出して、それをどう整備していくかという計画にしているのです。これから所要量も出して、そういった意味では、重度の方もしっかりと入れていただけるようにということでお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-02","title":"品川区立障害児者総合支援施設の指定管理者候補者の選定","agenda":"品川区立障害児者総合支援施設の指定管理者候補者の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、継続を求める切実な声が多く寄せられていたという状況や様々な当事者の方や当事者の家族の方々からの継続の要望があったわけです。","respondent":"松山障害者支援課長","answer":"品川区の指定管理者制度運用における実施要領によれば、３年目に実施しておりますので、今回。令和２年度に実施いたしました指定管理者の選定においては、設置目的を踏まえて、通常のとおり。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問・要望","question":"伺いたいのと、何というのですか、すごく大きな差があったのです。一番初めに指定管理者となったところが要望されているという満足度調査の変化というのがあったのですけれども、そういう点で、改めて。","respondent":"松山障害者支援課長","answer":"品川区指定管理制度運用における実施要領によりますと、公表とすることとしているものというのが規定されております。満足度調査は特にこちらに規定されているものではございませんので、情報公開での対応ということになろうかと考えています。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは、次の５年後もそういうことになるのでしょうか。どうしても緊張感が薄れていくと、５年後についてはどうなるのかということを、まず確認させてほしいと求めました。","respondent":"松山障害者支援課長","answer":"品川区指定管理者制度活用に係る基本方針ですけれども、連続して１０年を限度として選定をすることができるということになっております。日中一時支援の環境整備や定員を増やそうということに努められたり、児童発達支援センター、そして大人の地域生活支援拠点として。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"意見","question":"では、あと１０年間は可能性としては継続する可能性がある。その点については、議会はじめ地域も含めて、しっかり見ていきたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"指定管理を外れた方からもご意見を伺ったりして、なるべくバランスのよい視点で、この事業の継続を見させていただいておりました。その辺は事業者とも議論をした結果、両者の合意というふうに理解したいのですが、そういうことでよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"強度行動障害の方を受け入れるという想定はございまして、そのために、落ち着けるように個々の空間を設けているというようなしつらえかと思います。対応させていただいておりまして、建物管理に日々、努めているところです。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そういう不具合というのは、作ってみて初めて分かるところもあるではないですか。それで、今指摘したのは直っていますかというのも、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"対応できるものは区と一緒になって対応していますし、また次のときに向けて、こうしたいというご提案は頂けるものと考えております。","id":"exchange-023"},{"speaker":"吉田委員","kind":"確認","question":"非常用電源は別に確保されているエレベーターだと確認したのですけれども、ぐるっぽ自体、そういう不具合が運営に影響してきてしまうと思うのです。それで、改めて修正された点があったら、ご報告いただければ大変うれしく思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-03","title":"発達障害・思春期サポート事業","agenda":"発達障害・思春期サポート事業","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"何年前ぐらいからされている事業なのか。それと、この事業に対しての区の評価はどういう評価だったのか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"本当に事業開始当初と比較して支援体制が充実してきたということで、今回の、今年度１月から３月の間に引継ぎをしていただく。ただし、そのバトンは、児童発達支援センターや発達障害者支援施設に渡されるという流れが来たのかなと思いまして。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、その件数や利用人数などを教えていただきたいのと、４年生以降の場合も全部。その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"来年度につきましては、児童発達支援センターの児童学園では、ペアレントトレーニングも既に実施しております。２か所の児童発達支援センター、あるいは発達障害者支援施設でも、そちらに統合していく予定です。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これから５歳児健診も始まりますし、何というのですか、その人に合わせた支援というものも求められる状況になってくると思うのです。どうしても、パルレとしては赤字のためにできないということで伺ったのですけれども、続けられなかったものなのか。","respondent":"松山障害者支援課長","answer":"今回、パルレからの申し出の中に、別に実施する計画相談事業所に注力したいためです。それぞれご利用者の意思もありますし、どのような支援を受けたいかというのは、まだこれから確認していくものです。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に、社会的には、こういう発達障害の支援の施設というのは、これからもっと求められてくると思うのです。毎年伺っていたところだったのですけれども、事業所を継続できるように、ぜひともしていただきたいという思いがしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"吉田委員","kind":"確認","question":"赤字をどう補填しているかというと、ＮＰＯ法人なので、本体の事業からそれを補填していると伺っておりました。でも計画相談事業所としては残るわけですから、今後の問題として話合いが進んでおられるのかどうか、確認したいと求めました。","respondent":"松山障害者支援課長","answer":"今、既にＮＰＯ法人パルレが行っている計画相談事業所も含めて、相談支援体制促進事業ということで、区が独自に補助をしております。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"質問","question":"本当に区においても、区民にとっても損害だと思っていて、非常に残念な気持ちになっております。恐らく年間２,７００万円ぐらいの補助は入れていらっしゃると思うのですけれども、何か継続できる、その辺についてはいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"障害児通所支援の利用増加に伴って計画相談が増加傾向にありますので、既に実施の計画相談事業所に注力したいということでございました。やはり４月以降は引継ぎができないという話になってしまいますので、各センター、決して赤字が理由ではないということを申し上げます。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"実はこんなことなのではないですかというようなことを聞くぐらいは、信頼関係もある事業所ですから、いろいろとお話はしてほしいと求めました。これは要望でとどめておきまして、相談者などと面識があったり、従業員の方の引継ぎというのはどのようになっていらっしゃいますか尋ねました。","respondent":"松山障害者支援課長","answer":"今年度は急な対応ということになりますので、やはり社会福祉法人げんきが対応することになります。そのような形で、今年度は急な申し出によりまして、まずは今年度は社会福祉法人げんきで対応していただくということになろうかと思います。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。４月以降に関しては、新しい、げんきに行ってくださいなどということは特に言えないということだと受け止めてよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"そこまでご説明を区には頂いておりませんが、従業者の方とお話しして決めることであると、区としては思っております。区のほうは、その先の相談というのは継続していただきたい気持ちはあるのですけれども、パルレの問題と捉えております。","id":"exchange-032"}]},{"id":"topic-04","title":"令和８・９年度後期高齢者医療制度保険料率の改定（算定案）","agenda":"令和８・９年度後期高齢者医療制度保険料率の改定（算定案）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"２０２２年１０月に制度改定されて、所得に準ずる、今年の９月３０日までは外来窓口が１か月３,０００円までという措置のことでいいのでしょうか。約２割ぐらいの方が、品川区ではどれぐらいの方が増えるということになるのか、伺いたいと思います。","respondent":"山下国保医療年金課長","answer":"ご説明については、１・２割負担の皆様について、７２億円の公費の減が見込まれたというところで認識しています。赤字は区ということでご説明しているところがあるのですけれども、今実際、もう少しそれよりは少ない数値という状況です。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問","question":"その一番下のところを見ると、５項目の特別対策というところで、財政安定化基金拠出金がゼロになっているではないですか。その辺のところはどう考えられているのか伺いたいのと、平均で１万２,４７１円、１１.２％もの値上げということになるわけです。","respondent":"山下国保医療年金課長","answer":"今回、先ほど冒頭ご説明申し上げましたように、１１.２％の増というところでした。一定、ご負担が減るように努めてきたところですけれども、現状はこういった状況だです。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"そこに向けて、もう少し、これが何らかの要因で下がるということはあり得るのかどうなのか、伺いたいと思います。これは東京都全体での額ですから、１１.２％の１万２,０００円を超える値上げというのは本当に厳しい状況なので、そういうところはどうか尋ねました。","respondent":"山下国保医療年金課長","answer":"この間、算定されてきているものを区でも受けて、連合規約の改正ということで上程していくという形になります。特別対策の実施を継続していくということと、今後、本算定というところを見据えてまいりたいと考えています。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"意見","question":"もう６割が赤字で、自治体病院は９割が赤字と言われて、どうしても必要なのです。やはり国が軍事費に巨額の税金をつぎ込むのではなくて、こういうところにこそ使うべきだということは申し上げておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"テーマが大きかったのかどうかというところで、１点だけご説明があったのですが、特にやっていないということなのですか。介護予防への活用ということは、今、品川区でやられているということはこれだけでいいのかということでの確認を求めました。","respondent":"樫村高齢者地域支援課長","answer":"今年度から実施しております、その課題解決を図っていこうという取組に対してご説明させていただきましたが、高齢者地域支援課としましては。スマホでゲーム体験」なども昨年度から実施しておりまして、高齢者の方がデジタル社会に、全体的に進めているところです。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"なぜかというと、そのことも今日伺おうかと思っていたのですが、少し気になったので質問させていただきました。１つの企業のものであるものを、そこまでやっているのかどうかというのを今回聞いてみたかったのですけれども、教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"あくまでも全体的な概要の操作方法だったりというところのご説明になりますので、一方で、「スマホよろず相談」という事業もあります。ご本人同意の下ですけれども、ダウンロードの操作方法等を一緒に操作しながら教えるというか、そういった内容で対応しています。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"よろず相談ということで、ちょっと確認したいのは、それは誰が相談に乗るのか。キャリアのメーカーなのか、それとも誰がやられているのかということをまずお聞きしたいということと、何を求められているのかというところです。","respondent":"樫村高齢者地域支援課長","answer":"こちらは区から委託しておりまして、アライ電機産業という業者に委託しておりまして、その受託者に講師になって教えていただいているような状況です。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"継続率というのですか、グループ数も２１グループと、社会参加の意義があるとは思っています。そういったニーズをつかんでのデジタルサポート的なものも、ぜひお願いしたいと思いますけれども、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"現在も先ほど申し上げておりましたとおり、スマホ教室やスマホよろず相談等で、きちんとアンケートを取ったり、それからどういったご質問が多いかなどというような分析はきちんと取りますので、ニーズに合わせた展開というのを引き続きしてまいりたいと考えています。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実績がどれくらいあるのかというのを教えていただきたいのと、ここで実績が、どういうふうにされているのかというのを教えてほしいと求めました。そういう要望があったときに、どういうふうに応えていただけるのかという。","respondent":"樫村高齢者地域支援課長","answer":"まず会場としましては５会場で実施しておりまして、それぞれ教室は、今年度は延べ３２０名の定員でやる予定になってあります。最終的には１組最大５人でチームをつくって行うですので、区の介護予防事業や、その中で参加を呼びかけているところです。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"そうしますと、５人１組で申し込むみたいな感じになっているのでしょうか。アライ電機産業ですか、そういうところで派遣してもらえるみたいな仕組みというのはあるのか、その点も説明を求めました。","respondent":"樫村高齢者地域支援課長","answer":"最大５人でというところで、一応このアプリは２人から５人までというような形で、２人から５人で選んでいただくような形になってあります。それから、今は派遣という形はやってございませんで、それぞれ会場で日時が決まっている中でお越しいただくといった内容でやってあります。","id":"exchange-042"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結構、地域包括支援センターごとにスマホ教室をやっていて、結構それがすごく要望がたくさんあるというのを伺ったのです。そういう要望というのはあるのではないかという思いがしますので、ぜひこれからはそういう要望にも応えられる体制を取っていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"大倉委員","kind":"質問","question":"みんチャレアプリのグループが２１グループということで、どんなテーマのグループがいらっしゃるのかというのを教えてください。社会貢献、そういうところにつなげられているのかなというところが気になったので、教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"高齢者クラブなどの高齢者活動支援事業に参加している方に呼びかけをさせていただいて、この２１グループが前期でそれぞれつくられたということです。教室の中で知り合った方と組まれている方というのもいらっしゃるということで、多岐にわたると認識しています。","id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。今のご説明だと思ったのですけれども、もう一回、その辺を教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"チームをつくろうかとなったときに、チーム名をつくって、例えばハードにやりたいグループもあるでしょう。チーム名もそのときにいろいろ話し合っていただいて、チームというか、テーマというかを決めていただくような運用になってあります。","id":"exchange-045"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。その辺はどういうふうにつなげていく、社会参加などにつなげていくみたいな方針というか考えがあるのかというのを教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"これは我々も一番重要なテーマと考えてございまして、それを区の事業などでなくても、日常の生活の中で「自主」的に地域の中で継続していく。ちょっとこれは予定なのですけれども、様々な趣味活動にもつなげていっていただければと、構想としては考えてあります。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問","question":"フレイル予防にも、デジタルデバイドというか、高齢者のデジタル社会への参加というところで進めていっていただければと思いました。何かもらえたりみたいなのも、そういうポイントなどというのは考えていたりされているのか、やっているのかも含めて教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"寄附という形を取るような仕組みがありますので、品川区も今後、そういったところができるような取組を進めていきたいと考えています。","id":"exchange-047"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。参加したことで、さらにいいのかなと思いますので、ぜひ寄附のプロジェクトを進めていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺について、私としてはそういうことも考えていただきたいなと。興味があるという方もいらっしゃると思うので、今後の展望になると思うのですが、その点についてはいかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"２１グループつくってありますけれども、そちらに区からお知らせ等の情報発信というのは、そういった意味での周知等はできると考えています。社会福祉協議会とも、連携の上でにはなると思いますけれども、そういったところも視野に入れて検討していきたいと考えています。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"せっかくの仕組みですので、その発展形ということも、ぜひ今後検討していただけたらと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"確認","question":"すみません。そもそもの確認なのですけれども、「みんチャレ」というのは何の略で、正式名称は何か尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"恐らくになるのですけれども、「みんなでチャレンジ」だと。今、資料を持ってきたのですが、正式な名称はたしか、「みんなでチャレンジ」だったと認識しています。","id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"確認","question":"これは確認ですけれども、お考えとしては、その導入みたいなお考えなのか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"ただ、ＬＩＮＥを使っている方も多いのでというところで、今回これを採用したところです。１日１回、何でもいいので１枚送ることによって、ＬＩＮＥとの違いといったところです。","id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"どちらかというと、ふだんＬＩＮＥを利用されている方だと、みんチャレにすんなり入りやすいなどというところもあるのでしょうか。いかがでしょう。","respondent":"樫村高齢者地域支援課長","answer":"一応、そういったところも想定はしておりまして、そこも含めて考えたところです。","id":"exchange-053"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そうなると、何というか、みんチャレというのは当然、運動や社会参加、区から通知があったりという、非常にいい要素があるのですけれども、あまりデジタルデバイド的な要素は、そんなに比重としては、区としては低いというか、そういったお考えでよろしいか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"その中で、みんチャレアプリを使うことによって、デジタルデバイドの解消にも寄与するものと考えています。これをやることによって、それにも効果があるとは考えてあります。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"孤独孤立防止の１つになるわけですから、プラス社会参加というところを、少し広がりを持ってやっていただきたいなと。ちょっと取り留めのない質問になってしまいましたけれども、デジタルデバイド対策もぜひやっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"そうですね。高齢者地域支援課だけの範疇にとらわれずに、所管課と連携して説明をスマホ教室の内容に一緒に盛り込んで行うような対応を行っていますので。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１点だけ聞き忘れてしまったので確認です。６０日間継続率８３％というのは非常に高いなと思ったりするのですけれども、他自治体の６０日間の継続率などという数字が、もし分かれば。","respondent":"樫村高齢者地域支援課長","answer":"委員ご指摘のとおり、みんチャレアプリにつきましては他の自治体でも実施しておりまして、委託業者の資料によりますと、他自治体につきましては、６０日間で７５％の継続率ですので、品川区の継続率は、これと比較すると高いのかなと認識しています。","id":"exchange-056"},{"speaker":"えのした副委員長","kind":"質問","question":"時計に、「もう１時間座っているから立ちなさい」などと、ＡＩなどで促されるわけです。ここ１週間、暖かくなったので動きませんか」などといった機能というのは、あるのかないのかというのを伺いたい。","respondent":"樫村高齢者地域支援課長","answer":"私の説明不足で申し訳なかったのですが、３種類ぐらい選べるのですけれども、その役割というのはＡＩキャラクターが果たしていると認識しています。","id":"exchange-057"},{"speaker":"えのした副委員長","kind":"意見","question":"そんなアプリのＡＩキャラクターについて、さらに認識いたしました。私もやはり何歩以上歩いたときに、またさらに続けようかなという気持ちになるので、そういった機能を活かして続けていけるようなサポートをぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"委員長に言っていただいたとおりなのですけれども、あくつ議員の質問の中で、介護保険のサービス利用者に対して、負担軽減に資する時限的な措置を行うという答弁があったと思うのですけれども、それが具体的にどのようなことなのかを伺いたいというのが１点です。","respondent":"菅野高齢者福祉課長","answer":"一律減免は行わないこと、過去に実施された会計検査の結果においても、費用負担の公平性を損なうおそれがあると考えられると指摘されております。とはいえ、物価高騰に対応した措置として、介護サービス利用者の負担軽減に資する方策を今後検討していきたいと考えております。","id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問","question":"サービス利用者の負担軽減ということは、サービス利用料というのが基本１割で、所得に合わせて３割というのもあると思うのですけれども、その利用料の負担を減らすという考え方でいくということなのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"確かに委員がおっしゃったとおり、利用者の負担割合は、所得に応じて１割から３割という形で負担していただいております。介護保険の負担割合の部分に限らず、もう少し幅を持たせた感じの部分も含めた方策について検討していきたいと考えているところです。","id":"exchange-060"},{"speaker":"鈴木委員","kind":"意見","question":"利用料というのは基本１割のところから、低所得者は１割ではなくて５％の利用料などと、部分的にやっているというのもあると思うのです。これからということなので、できる範囲で結構ですので、お願いできたらと思いますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"確かに委員がおっしゃるとおり、他の自治体では、どちらかというと低所得の方に対しての利用料の何％などという形で負担している例があります。","id":"exchange-061"},{"speaker":"鈴木委員","kind":"質問・要望","question":"一般財源を入れてやっていたところが１か所あったような気がして、品川区でもやってほしいというようなことも要望した記憶があるのですけれども。楽しみにしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１１月２０日の藤原議員の質問で、外国人の国民健康保険料滞納者に対して、出入国在留管理局と連携して対応していくというご答弁があったと思います。具体的にどうなっていくのかということで、外国人の滞納の状況や理由なども含めてご説明いただきたいということで、お願いしたいと思います。","respondent":"山下国保医療年金課長","answer":"区として、東京出入国在留管理局に協力を要請しまして、来月１２月から本制度の活用を開始することで、収納率のさらなる向上に努めてまいります。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問","question":"１年以上、出入国在留管理局に区から知らせて、出入国在留管理局から区役所に来庁するようにということを勧めてもらう制度ということですか。品川区に在住されている外国人の中で何％ぐらいなのかというのも教えていただけたらと思います。","respondent":"山下国保医療年金課長","answer":"もう一度改めてご説明申し上げますと、区から出入国在留管理局に情報提供します。令和６年度末時点で５,０００人程度ということで、被保険者は大体６万人ですので、８％程度という状況です。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"一般的に、国民健康保険の加入者というのは１５％ぐらいかと思うのですけれども、約半分近くの少ない割合ということで考えていいのでしょうか。保険には入って、そういうふうに考えていいのかということを教えていただきたいのと、その人数かパーセンテージかを教えていただけたらと思います。","respondent":"山下国保医療年金課長","answer":"先ほど、国民健康保険加入者における外国人の人数のところをご説明申し上げたところです。通訳を介しながら情報を説明させていただいているということのほか、冒頭の説明で申し上げましたけれども、こういったもので周知をしています。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、外国の人に特別分かるような対応というのは、何かされていることはあるのか尋ねました。","respondent":"山下国保医療年金課長","answer":"納付のご案内時期等をお知らせするものについては、今は２言語ですけれども、そういったところでお読みいただけるように対応しているところです。こういった仕組みを有効に活用して、収納率の向上というところと、制度の適正な運営に努めてまいりたいと考えています。","id":"exchange-066"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これから２０２７年度に向けて、国としてやっていくわけではないですか。何というのですか、そこに寄り添った対応というのが求められるのではないかと思うのですけれども、その点についても伺いたいと思います。","respondent":"山下国保医療年金課長","answer":"先ほど、私どもとしては努めていかなければならないところと捉えておりますので、そういう取組を強化していきたいと考えています。例えばこういった出入国在留管理局との連携という中で、区にお越しいただく機会を少しでもつくっていきたいと考えています。","id":"exchange-067"},{"speaker":"鈴木委員","kind":"質問・要望","question":"一般的に通知を出して１年間滞納、私はぜひとも慎重にしていただきたいと思うのですけれども、いかがでしょうか。区として把握しているところがあったら教えていただきたいですし、ぜひともしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"山下国保医療年金課長","answer":"日本語と、またそれも英語を含めて、２言語ですけれども多言語で個別に対応しているところがあります。寄り添った対応に努めている中で、今後も引き続き丁寧に、寄り添った対応に努めてまいりたいと考えています。","id":"exchange-068"},{"speaker":"鈴木委員","kind":"意見","question":"そこのところは、慎重な対応と親身な対応ということを、ぜひともお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かなり貧困というか、生活が苦しくて未納になっているみたいな方も想定されるかと思うのですけれども、こういう方も外国人の国民健康保険としてカウントされるイメージでよろしいか尋ねました。","respondent":"山下国保医療年金課長","answer":"国で６３％、区で７７％という収納率でご紹介申し上げたケースというのは、外国人の方の世帯主ということでピックアップしているところです。世帯が分かれていくという中で、別れられた外国人の方が世帯主になられているのであれば、数には含まれてくるものと考えます。","id":"exchange-070"},{"speaker":"やなぎさわ委員","kind":"質問","question":"範囲が広くなると、この中で国民健康保険に加入している外国人の方というのは、それ以外で大体どういった方が一般的に想定されるのでしょうか。もしご紹介できれば、国民健康保険に加入している外国の方の属性といいますか。","respondent":"山下国保医療年金課長","answer":"属性ということで申し上げますと、なかなか属性というのを表現し難いところがあるのですが、在留資格というところで申し上げますと、やはり留学で来日されて、国民健康保険に加入されていらっしゃる方が一番多いようには把握しています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"意見","question":"例えば品川区で受給していた方がどういう状況にあるのか、自治体でやるのはやめてほしいということを、たしかおっしゃっていたかと思うのです。やめてほしいというか、どれぐらいの困難があるのかという、今の感想をお聞かせほしいと求めました。","respondent":"豊嶋生活福祉課長","answer":"継続している方であれば、やはり５年間保存という規定がありますので、データがすぐ手元にない方もいます。なるべく正しく正確に早くできるような体制を整えることしかできませんので、その間、何とか問題なく給付できるように頑張ってまいりたいと思います。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そう判断された、そこについては本当に国の責任だと強く思うし、それを自治体が被るというのは本当に迷惑な話だと思います。権利がある方には追加給付をしていただきたいという立場ですから、本当にご苦労をおかけしますけれども、そこはぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238890?Template=document&Id=7227#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":62450,"voices":196}},{"id":"r07-20251126-8","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"建設委員会","time":"午前１０時１１分～午後 ０時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"「品川区中高層建築物等の建設に関する開発環境指導要綱」等の改正","agenda":"「品川区中高層建築物等の建設に関する開発環境指導要綱」等の改正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の改正に当たって参考にしたひな形ですとか、他区の例などはあったのかというのを伺いたいと思います。そういうビルが増えているのですけれども、それらは今回の要綱改正の対象に入るのか、それとも既に対象になっているのか説明を求めました。","respondent":"高梨都市計画課長","answer":"調査・検討の委託もさせていただきまして、今回、改正内容についてまとめてきたところです。その間の周知ですが、窓口でのご案内はもちろん、区ホームページ等でご案内をする予定です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"建て主はどういうところで、どのような方々が住んでいるところが多いと区は把握しているのか、伺いたいと思います。区内の数を把握しているのか、もし区として把握しているなら、ここ数年の増加状況を少し教えてほしいと求めました。","respondent":"高梨都市計画課長","answer":"地域から声も寄せられているところですので、民泊に関する指導を所管している保健所等とも連携をして、地域の声に応えてまいりたいと考えています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し伺いたいのですが、厳しくした点と緩くした点があると思うのですけれども、それをもう少しご説明ほしいと求めました。キッズルーム等の基準変更というのはどういう内容なのか、もう一度、すみません、ご説明ほしいと求めました。","respondent":"高梨都市計画課長","answer":"説明が早くてというところがございましたけれども、そういった内容についても可能とすることで、しようかと考えているところです。冒頭申しましたとおり、燃えるごみの収集日は朝来てくださいねといったことも、建物の規模に合わせて柔軟に対応してまいりたいと考えています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に、この内容とは直接関わらないのですが、１点お伺いしたいのが、駐車場ですとか駐輪場の設置義務についてです。解体説明会の案内の対象にぜひ私道の所有者を入れていただきたいと思うのですが、いかがか尋ねました。","respondent":"高梨都市計画課長、川原住宅課長","answer":"これから要綱の改正作業に入ってまいりますけれども、何か工夫できるか、しっかりと考えてまいりたいと考えています。当然考えましたけれども、特段今回の改正内容に入れなくても大丈夫かなといったところで… 解体については住宅課で指導要綱を作成している関係で、住宅課から回答します。引き続き丁寧な対応をしていくとともに、私道の持ち主に関しての周知というところは、ご意見として研究させていただきたいと思います。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"主流なのでしょうか、２０部屋以上は。３点目、それにも関わるのですが、２０部屋以上とした根拠を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"次に、駐輪場についてですが、これは集合住宅の面積によって設置する台数を分けています。もう少し面積の狭いものについては１室当たり１台、ワンルームタイプ等であれば１室につき０.５台という形で換算をして、要綱の中で設定しています。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"努力義務なのか、求めるだけなのか、それとも義務なのか、そこを確認させてください。それとも週２とかか尋ねました。","respondent":"高梨都市計画課長","answer":"社会情勢の変化等も踏まえて変わってくるものであるという認識ですので、また利用者の動向等、今後も検討を進めてまいりたいと考えています。人的対応が必要な場面においては、そこを、建物規模であるとか周辺の状況に応じて配置を求めてまいりたいと考えています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に具体的には大型のスクーターというのでしょうか、持ち主に言わせれば、実際によく見て対応していただきたいと要望しておきたいと思います。今回、４０平方メートルから５０平方メートルに上げたということなので、その辺はどういう規模だったのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"そもそも４０平方メートルという面積、誘導する居住面積として４０平方メートルというものがあるところから、４０平方メートルにしてございました。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほど、寄宿舎が区内にどれだけあるか分からないが、相談件数が増えているというお話があったと思います。宅配ボックスの設置については、指導対象がどのぐらい増えると見ているのか、お聞きできればと思います。","respondent":"高梨都市計画課長","answer":"年間の要綱対象の事業数が約７０件ほどでここ数年推移をしています。宅配ボックスについては、ほとんどの集合住宅が対象となり得ると考えていますので、年間そのぐらいの、７０件程度が要綱対象となるのではないかです。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"確認","question":"要綱ですので、先ほどの議論の中にも努力義務的な基準、手続になる、物理的な拘束力というのは、というお話もあったと思います。そこを手厚くしたり、考慮したりされるのか、そこだけを確認でお聞きできればと思います。","respondent":"高梨都市計画課長","answer":"今回の要綱改正では、一定規模以上の集合住宅における宅配ボックスの設置といったところです。一定規模以上、要綱でしっかりと設置義務というか、事業者でしっかり設置してくださいねといったところで進めてまいりたいと考えています。","id":"exchange-009"},{"speaker":"せお副委員長","kind":"質問","question":"５年に１回の見直しということだったのですが、どういった方たちで検討されてこういうふうになっているのか。を教えていただけますか尋ねました。","respondent":"高梨都市計画課長","answer":"我々区のほうで専門会社に調査・検討委託を行い、あと一般的に全国的な状況等も踏まえて検討して、改正をしていくところです。社会情勢等を踏まえておおむね５年ごとにしっかりと見直していきましょうねといったところを、要綱の中にも記載させていただいているところです。","id":"exchange-010"},{"speaker":"せお副委員長","kind":"質問・要望","question":"次は５年後になりますが、進めていただきたいと、そこは要望します。５０平米以上にして、今って、例えば５５平米で品川区内だともう１億円を超えたりするではないか尋ねました。","respondent":"高梨都市計画課長","answer":"バリアフリー、夫婦２人と子ども１人の居住に適した面積としては５０平方メートルが今回は適切だろうということで、上げさせていただいたところです。区としてもファミリー世帯の居住、定住促進というところでは、しっかりと考えていかなければいけない課題かなと考えています。","id":"exchange-011"},{"speaker":"せお副委員長","kind":"質問・要望","question":"この前も質問しましたが、そういったマンションに皆さんが住めるよう、支援をぜひ考えていってほしいと求めました。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"令和８年１月区営住宅入居者募集","agenda":"令和８年１月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"４人世帯というのは、例えばお子さんが障害をお持ちですか、そこら辺のイメージを伺いたいのが１つ目です。今まで品川区は住宅ストックが余っているということも説明してきたと思うのですが、改めてその理由を伺いたいと思います。","respondent":"川原住宅課長","answer":"今後の検討としましては、子育て世帯の区外転出がいろいろと今増えているところです。そうした子育て世帯への転入を図るなどの、家賃助成ではない形での子育て支援、住まいの支援を引き続き検討しています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"合計２２１億円も投じて、かけて建てるのですかという、なぜ区営住宅の増設も家賃補助もしないのか。全然それでは足りないと思うのですが、どのようにお考えでしょうか、伺います。","respondent":"川原住宅課長","answer":"令和３年からスタートして、区内の不動産会社のご協力をいただきながら、１年当たり約１００件単位で入居の促進を図ってまいりました。そういったところを援助していきたいと考えています。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"区営住宅の増設と家賃補助、せめて杉並区で行っているような、落選者に一定期間補助をする。そういった補助金を検討して実施していただきたいと、改めて要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"今もありましたけれども、これは来年度予算に向けて今準備していると、そういうことなのですか。要するにどういう支援の中身なのかというのを知りたかったので、現状で結構ですので、分かる範囲で。","respondent":"川原住宅課長","answer":"今、中身については検討の段階ですので、委員の皆様にお示しできるときがまいりましたら、きちんとご説明をさせていただきたいと考えています。細かいところは今検討中でございまして、そちらにつきましても、早急にまとまり次第ご説明させていただければと考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"こちらいかがかという、現状の考えを伺います。関連の質問ですが、最後にいかがか尋ねました。","respondent":"川原住宅課長","answer":"子育て世帯の転居費用の助成を考えているところですが、やはり上昇傾向にあるというところは、私どもも認識しています。そういった住戸の供給に併せて、様々な子育て世帯の住まいの支援は検討していきたいと考えています。","id":"exchange-017"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"順番を変えて３から伺っていきたいと思います。防災公園等に設置しているマンホールトイレなども使えるようにするためには、耐震化の対象にしていく必要があると思うのですが、いかがか尋ねました。","respondent":"関根河川下水道課長","answer":"マンホールトイレを設置している公園についても、災害時に重要な施設ということで、これまでに耐震化を実施してきております。具体的には、その中にマンホールトイレ設置公園というのも位置づけておりまして、その中で耐震化を実施したところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"併せて聞いてしまいますが、上水道の耐震化の記載がないのですが、それはなぜなのかお伺いしたいと思います。あるいは区としても、状況を把握して区民にお知らせすることが必要ではないかと思うのですが、いかがか尋ねました。","respondent":"関根河川下水道課長","answer":"先ほど申し上げたところ以外については実施済みということで、先ほど申し上げた実施中のところを着実に実施していくという形で考えてあります。トイレもそうですし、トイレ以外も含めて、排水については地震時も使用できるという認識をしています。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこはぜひお願いしたいと思いますけれども、東京都に求めていただくというようなことはいかがでしょうかと質問させてほしいと求めました。総合支援メニューということで、何か一緒にセットにすればさらに上乗せというのがあるのですが、これを設定した理由というのも伺いたいと思います。","respondent":"関根河川下水道課長、大友公園課長、森建築課長","answer":"先ほどの３番のところにつきまして、少し補足等させていただければと存じます。区役所、上下一体となって耐震化が図られているものと認識していますし… 先ほどマンホールトイレ、公園等に設置してあるトイレについて、全てのマンホールトイレが下水に接続しているわけではありません。貯水槽ではないですが… 財源ですけれども、おおむね国が２分の１、東京都が４分の１、区が４分１を負担している形になってあります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは不燃化特区支援事業に移行するなり、そういうのを東京都に求めるべきだと思うのですが、いかがでしょうか、伺います。伺いたいのは、区としてそういった数字を算出してほしいと求めましたけれども、いかがか尋ねました。","respondent":"関根河川下水道課長、小川木密整備推進課長","answer":"水道の耐震化について、私からお答えします。避難所と申し上げましたけれども、具体的には小中学校等５２施設ということで、小中学校をメインとして完了していると聞いてあります。別の、その中で新たな助成支援というものも考えられていると聞いてありますので、新たな地区等については検討していきたいと考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういった考えを持っていただきたいのですが、東京都に求めていただけませんでしょうか。伺います。","respondent":"小川木密整備推進課長","answer":"避難路、または救援救護路の役割といったところでは、非常に重要な防災まちづくりの取組の一つだという認識です。今あった特定整備路線の中の不燃領域率等々の算出につきましては、そういったご意見があったということは東京都にはお伝えしたいと考えています。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、当初は地域が限定されて、集中的にやるという議論でしたが、今は区内全域で実施されております。これはどのような政策判断、政策の発展なのか、改めて伺いたいと思います。","respondent":"森建築課長","answer":"除却につきましても、こちらにつきましても、さらに加速させていこうということで区内全域へ拡充してきているところです。戸建て住宅除却工事は除却のみなのかというところですけど、除却のみです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"区内全域にすべきだと、こういう考え方も持っているのか、改めてもう少し詳しく伺いたいと思います。除却費だけでなく、引っ越し代や設計監理費や工事費等建て替えに係る費用の一部助成も行うべきではないかと、いかがか尋ねました。","respondent":"森建築課長","answer":"地域を限定してなぜ集中的に実施したかというところですけれども、やはり予算の面等も含めて、集中的にやっていたのではないかと考えてはいます。社会の情勢を含めて、引っ越し費用等も増やすべきだという状況になりましたら考えてまいりますが、進めてまいりたいと考えています。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"いつ起きてもおかしくない大地震に備えるのであれば、直ちに手をつけるべきときだと思うのですが、改めてこの点を伺いたいと思います。そういう意味からも、除却費だけでなく、引っ越し代などを含めて支援を進めていくという意味合いが私はあると思うのですが、改めていかがか尋ねました。","respondent":"森建築課長","answer":"建て替えの助成等につきましては、現在、木密整備推進課の事業等で行っておりまして、この中で実施しています。区内全域に広げることについては別途検討していくことなのだろうと思いますけれども、今後また考えてまいりたいと考えています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを目指すべきだと思いますので、ぜひ除却についてもセットで区内全域に広げていただきたいと、これは改めて要望をしておきたいと思います。こういう考えを持つべきだと思うし、こうした考えはぜひ持っていただきたいと思うのですけれども、最後にいかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"危険度が３と、やはり効果的・効率的な防災性の向上を図るため、まずは危険度の高いところから優先度をつけて取組を行っているところです。は危険度の高いところを解消していきたいといったところで、今の地区を指定させていただいているところです。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"重なってくるというのは、区としてはどういうスタンスなのかと思うのですけれども、お考えを伺いたいと思います。そうした政策判断を後から都市開発課がかぶせてくるような、こうしたのはなぜなのか、最後に説明だけほしいと求めました。","respondent":"小川木密整備推進課長","answer":"無接道宅地の解消といったものにもつながってまいりますので、再開発の取組というのも地域主体の防災まちづくりの一つという形で捉えてあります。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"二葉二丁目ですか、広範な地域で新たなまちづくりのアンケート調査が今始まって、恐らく上位計画をつくるための材料にされる。高度利用だ、スカイラインだ、魅力あるまちだという理由で高層マンションが建ったり、オフィスビルになったりするのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"ゆきた委員","kind":"確認","question":"私からは、３の下水道インフラの機能確保のところで伺いたいと思います。当時場所によってはマンホールが数十センチから１メートル飛び出している事態も確認したという報道もありました。","respondent":"関根河川下水道課長","answer":"車両通行に支障となるぐらい浮き上がることが見込まれるものについては、冒頭ご説明で申し上げた、弁を設置するという対策を取ってあります。一方で、この対策を図ることで、その浮き上がりを抑えて、災害時にも緊急車両等が通行できるようにする、このような認識です。","id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"事務事業概要で確認させていただきましたが、ここについてどう捉えているか、お聞きできればと思います。","respondent":"関根河川下水道課長","answer":"耐震化の状況につきましては、私ども品川区で受託をしている以外にも、東京都下水道局が実施しているものもあります。そういったところで東京都のホームにご案内するとか、そういったところで周知はさせていただければと考えています。","id":"exchange-030"},{"speaker":"ゆきた委員","kind":"確認","question":"区民にとっては、一つ一つ確認していくというのがかなり難しいと思います。品川区も確認させてもらったのですけれども、区民への安心を提供していくのも一つだと考えますが、その辺についてお考えをお聞きできればと思います。","respondent":"関根河川下水道課長","answer":"ご提案いただきましたホームページの見える化につきまして、下水道の耐震化を主体として実施しています東京都下水道局、上水道につきましても東京都で全て直営でやってありますので、東京都と連携しながら、どういったことができるかというのは考えてまいりたいと思います。","id":"exchange-031"},{"speaker":"松永委員","kind":"確認","question":"少し確認なのですが、先ほどの質疑の中で、無電柱化道路とかマンホールのことについては、上下水道、こちらは私道も含まれて、全体という意味でこのような事業になっているのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"下水道管の耐震化につきましては、私道の地中に入っている排水設備は、それぞれの方の私有財産という形になっております。この下水道の地震対策として実施しておりますのは、東京都下水道局の所有している下水道について実施をしているものとなっています。","id":"exchange-032"},{"speaker":"せお副委員長","kind":"質問","question":"ここの事業周知・啓発の実施について、書かれていないのでお聞きしたいと思います。せっかく３年間の期限付きの集中取組なので、アウトリーチというか、そういったことはされているのかというのをお聞きしたいです。","respondent":"森建築課長","answer":"過去には、個別訪問等を行っていたのですけれども、現在は行っていない状態です。ただ、皆さんに活用していただきたいので、様々な手法を取りまして、区民の皆さんに対して周知してまいります。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/109228?Template=document&Id=7273#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":37623,"voices":105}},{"id":"r07-20251126-9","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"文教委員会","time":"午前１０時１０分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"条例の一部を改正する条例、(2)第１４２号議案、学校教育職員の給与等に関する特別措置に関する条例の一部を改正する条例、(3)第１４３号議案…","agenda":"条例の一部を改正する条例、(2)第１４２号議案、学校教育職員の給与等に関する特別措置に関する条例の一部を改正する条例、(3)第１４３号議案…","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"組合とは団体交渉を行ってきた中で妥結をしたのか伺いたいのと、あと義務教育等教員特別手当の見直しで、校務の種類を考慮したものにするというのはどういうことなのか、どう変わるのか伺います。","respondent":"酒川指導課長","answer":"妥結については、したものと捉えております。それから、校務の種類についてですが、これは年々、高まる担任の負担への配慮と理解しております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"４％から１０％、区としてはこの１０％引上げで十分と考えているのか、伺います。","respondent":"酒川指導課長","answer":"段階的な引上げについては、予算の問題と捉えております。働き方改革につきましては、この教職調整額の引上げと併せて進めていく、さらに処遇改善が図られていくよう努力していくものと考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"前進をしたということで、さらに引き上げていく、そしてしっかりと残業代を支払っていくようにしていくことが必要と思います。それが教員不足解消に向けても一歩となると思いますので、区としても取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"若林委員","kind":"質問・要望","question":"給料表の改正で、毎回そうなのでしょうけれども、（１）と（２）のそれぞれ若年層に考慮したという表現がありますけれども、具体的にこの給与表でいうと、それがどう数字で見えるのか教えてほしいと求めました。","respondent":"酒川指導課長","answer":"なかなか給料表からどこが高まっているかを申し上げることは難しいのですけれども、一般企業の初任給等々が上がっている背景を踏まえ、教員不足を解消していく必要があるということで、若年層に厚みを持たせてあります。","id":"exchange-004"},{"speaker":"若林委員","kind":"質問","question":"なかなか数字では、厚みというのはそういうことですか。ということは、この数字よりも、幼稚園教育職員でいうと３.８％の引上げよりも率とか金額がこの号給では厚くなっている理解でよろしいのか尋ねました。","respondent":"酒川指導課長","answer":"その理解でよいと考えています。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"管理職のことでお尋ねしたくて、先ほどの給料表になるのでしょうか、その辺はどのようにお考えか尋ねました。","respondent":"酒川指導課長","answer":"管理職手当ということで、当然ながら同じように支払われているわけですけれども、やはり特に副校長業務が激務であるのは承知しております。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"区ができる範囲については今後、業務量の削減はもちろんやっていただくのですけれども、待遇の改善をしていっていただければありがたいと思うのです。その辺り、いかがか尋ねました。","respondent":"酒川指導課長","answer":"やはり都費の教員ですので、区で対応はなかなか難しいところはありますが、やはり東京都に引き続きの処遇改善については働きかけを行っていくべきものかと考えております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"意見","question":"都の職員との公平性、平等性に関わるというところで合わせていくべきだと思いますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-02","title":"文化財の登録","agenda":"文化財の登録","exchanges":[{"speaker":"横山委員","kind":"確認","question":"３月なので、その辺り、どのように変わっていくのかを確認させてください。今後の保存活用の方向性について、何か現段階として分かっていることがあれば説明を求めました。","respondent":"舩木庶務課長","answer":"これは一定程度、この実施に際しては、この登録がしっかりとなされたことを区民に関心を持っていただけるように努めていきたいと考えております。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問","question":"区としては、区民の方に関心を持っていただいたりとか、あと周知を行っていくというのが区の役割としてある理解でよろしいでしょうか。区として活用していける部分がもしありましたら、ぜひお願いしたいと思うのですけれども、その辺りのお考えを説明するよう求めました。","respondent":"舩木庶務課長","answer":"現時点で６件ほどございまして、この６件の中には、通常公開されていない施設もあります。教育委員会と、それから文化観光戦略課とも連携を取りながら、周知も含めて進めてまいりたいと考えます。","id":"exchange-010"},{"speaker":"まつざわ委員","kind":"質問","question":"建築家の榛沢さん、有名な方が何か手がけた能楽堂、施設。すごくいい視点と思っているのですけれども、そこら辺、いかがか尋ねました。","respondent":"舩木庶務課長","answer":"１つには、これは先様の法人ともよく協議・連携しながら、進めていければと考えます。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こちらは有形文化財ですから、貴重な建物の中で体験できることなのであれば、それが１つ。そこは文化観光戦略課と連携してやっていただきたいのですけれども、その２点、お願いします。","respondent":"舩木庶務課長","answer":"そういった意味では、もちろん通常どおり利用いただけるものと考えておりますので、そこら辺は問題ないと捉えております。いろいろなメニューへの追加については、どういう連携の取り方、興味関心を持っていただける方法があるかはしっかり考えていきたいと思います。","id":"exchange-012"}]},{"id":"topic-03","title":"標準服購入費用保護者負担軽減事業","agenda":"標準服購入費用保護者負担軽減事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"電子クーポンを保護者の方に配布するということで、これはどういった形でやられるのか、あと地元の販売店の方がどう関わってくるのか、今までどおり、保護者の方は地元のところで買えるのかということなどを含めて、伺います。","respondent":"石井学務課長","answer":"例えば通常の電子決済ですと、その金額とかを表示するのではなくて、読み取るだけでそのまま決済が完了するという仕組みで進めております。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"ＱＲコードで配布をする。そうすると、そういったものは配備がしっかりできるのかどうか、販売店の負担などはあるのか伺います。","respondent":"石井学務課長","answer":"本クーポン事業を開始するに当たって、これまでクーポンの設計とかも含めて、各６社の販売店のご意見を伺いながら進めてまいりました。１２月３日に、改めてその画面のデモなどを用いた販売店向けの説明会を行うこととしております。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"地元の販売店が、これまでずっとやられてきたところもあると思いますので、そうしたところが今回の事業で排除されないように進めていただきたい。確認させてほしいと求めました。","respondent":"石井学務課長","answer":"お見込みのとおり、現在の標準服事業者に関しては、本事業の導入に伴って排除されるようなことはございません。","id":"exchange-015"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ＱＲコードが本当によかったのか、悪かったのかとか、そういった振り返りをしっかりして、この事業の改善を図っていってほしいというのが１点。クーポンで、先ほどＱＲコードをやると、そのままだという話なので、要は天井がない、金額、そこの何か縛りがあるのか説明を求めました。","respondent":"石井学務課長","answer":"１月から３月までの間、３月末まで使えるような形で、きちんとやっていきたいと考えています。きちんとその辺りについては事業者と連携を密に取りながらやっていきたいと考えております。","id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そこまでしてくれるのは安心しました。そういう家庭が随分、増えているとお聞きもするので、改めてこういったクーポンの周知をしっかりとしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"横山委員","kind":"確認","question":"先ほど義務教育学校のお子さんに対しては、現４年生から６年生ですか、経過措置として考えているという理解でよろしいのか確認させてください。例えば４月とかに転入されてというような、そういった場合にはどのように対応するのか、説明を求めました。","respondent":"石井学務課長","answer":"そういうケースについては、各学校にいろいろご意見を伺いながら、取扱いを検討していきたいと考えております。配布後の転入に関しては、もちろん入学前に制服を購入できるような形で、きちんと対応してまいりたいと考えております。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"１１月１４日に、ホームページで既にご案内が詳細にされていますが、それ以降、保護者、ご家庭等からのこれに対してのお問合せはどのような感じか尋ねました。","respondent":"石井学務課長","answer":"学校を通じて保護者に案内していたということもあったので、ホームページ掲載後については、何らかお問合せをいただいているということはございません。","id":"exchange-019"},{"speaker":"若林委員","kind":"意見","question":"何で通常学校のみんなは無料クーポンで、何で特別支援学校だけ補助金なのと。そこら辺についてのご見解を聞きたいのと、６社で、その２つとの意見を述べました。","respondent":"石井学務課長","answer":"特別支援学校に通うお子さんなのですけれども、あと補助教材ですとか給食費、そういったことも併せて補助事業を実施しております。誰もが所得制限なく必要なものを手に入れるということを考えておりますので、あくまでも標準服を支給、購入できるという形で設計をしています。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問","question":"値段は、これは分からなくていいですか。値段をどう見せるかも、だからこそ見せるべきという考え方もある。","respondent":"石井学務課長","answer":"価格も統一して実施できるものがあるために、補助教材ですとか給食費というのは、それで各学校が会計をしているというスキームになります。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"１月から注文するということは、先ほどの２月の私立中学の入試等もあれば、児童にどう伝わっているかということが１つ。それからもう１つは、もちろん業者がやることですから、その点についてお願いします。","respondent":"石井学務課長","answer":"そういったものについては、各学校を通じて、入学予定の方々に伝達をするです。あくまでもこの物価を反映させた上で、価格を決めていきたいとおっしゃっておりました。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"どうしても学校の場所を使って採寸したり、学校の協力も必要になってくるので、そこはうまくきちんと連携を取ってやっていただきたい。それからもう１つ、ぜひチェック、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"筒井副委員長","kind":"確認","question":"確認も含めて、改めて今回、電子クーポン制にした理由を説明するよう求めました。","respondent":"石井学務課長","answer":"そういう本来の目的とは違う課題も出てきてしまうということを考えた上で、紙クーポンも考えましたし、電子クーポンも考えました。ただ、例えば紙クーポンにすると、印刷コストがかかるですとかそういったこともありまして、最終的に電子クーポンを採用するに至りました。","id":"exchange-024"},{"speaker":"筒井副委員長","kind":"質問","question":"そのコストの話ですけれども、紙だと高いということだと思うのですけれども、今回、電子クーポン導入に当たって、システム業者とかに依頼と思うのですけれども、その業者はどこなのか、かかる費用はどのぐらいになるのか尋ねました。","respondent":"石井学務課長","answer":"クーポンの事業者につきましては、ＴＯＰＰＡＮの会社に頼んでおります。電子クーポンのシステム構築費用のほかに、初めに各ご家庭にご案内を送る通知の発送費用等も全部含めて、１,０００万円弱となっております。","id":"exchange-025"},{"speaker":"筒井副委員長","kind":"質問","question":"では、その１,０００万円弱は、今回そのシステムが出来上がったら、大規模更新はなく、そのままずっと使えるということか尋ねました。","respondent":"石井学務課長","answer":"ＱＲコードとかを書いた通知を発送するためには、いわゆるバックオフィス機能でそういった事務処理センターのようなものを設ける必要があります。その維持費用は各年度かかってくると考えております。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"今、大変流行しているということで、何か対策は行っているのかどうかと、今後の見通し、子どもたちが元気に成長していただけたらと思うのですけれども、区の対応はどうなっているか伺います。","respondent":"石井学務課長、染谷保育施設運営課長","answer":"この傾向を見ていますと、２年前の状況と少し似ていると考えています。２月頃にはやり出すという過去の例がございましたので、基本的な感染症対策の徹底などについて呼びかけていきたいと考えております。 それからあと月１回、インフルエンザについての対応について、感染症予防の対策をしています。令和６年度、同様に令和５年度の傾向と近い部分があるというようなところを、しっかりと予防を継続して実施していければと考えています。","id":"exchange-027"}]},{"id":"topic-04","title":"令和６年度品川区立学校における不登校・いじめの状況","agenda":"令和６年度品川区立学校における不登校・いじめの状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"もう一度伺いたいのと、あと全体としては８％の人が指導などを受けていないということで、こうした子どもたちへの対応をどうされていくのか。不登校のうちの約１割ですけれども、受皿になり切れていないのかと思ったのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今後の対応ですけれども、現在、メタバースの取組なども行っております。今年度は、継続的な指導が受けられない生徒は限りなくゼロに近づいていくだろうという見込みです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"１５校に配置されているということで、今後さらに増やしていくことは考えているのか伺いたいのと、その効果と現状を伺います。不登校数が１年生と７年生で大きく減少したと、資料にも書かれているのですけれども、理由をどのように分析されているのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"支援の場になっていることは間違いないと捉えておりまして、こういった施策の１つが、防げた１つの理由になっていると捉えております。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"１つ確認なのですが、まず確認させていただきたいのと、その受け止めを伺います。その傾向も含めて伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"一方で、重大化を防いでいかなければいけないという認識です。法に基づいて適切に対応している表れではありますけれども、家庭、地域が一丸となって取り組んでいくべきものと捉えております。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"１年生と３年生で大きな差があるということで、これはどのように分析されているのか、伺いたいと思います。しっかり子どもたちが理解し、他者を尊重できるようにしていくことが１つ大きく減らしていくことになると思うのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長、酒川指導課長","answer":"昨年度から研修等も行い、取り組んでいますけれども、減らしていけると考えているところです。そういった取組も、市民科の授業の中を通して、教育活動全体で取り組んでいくことで働きかけを行っているところです。 子どもと向き合う時間を増やすことが、一層の認知につながると捉えておりますので、教員の多忙化解消には今後も努めてまいりたいと考えています。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"不登校・いじめ、なくなるのが一番ですけれども、できるだけ減らしていくということで取り組んでほしいと求めました。それで、２年生では認知件数が改善できたということですけれども、何か新たな取組をやったとか、どのようにして改善されたのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"１つその先の中学年、現在、学校の中でかなり積極的に認知をしている学校があります。区全体を挙げて、小さないじめでもしっかり認知をして対応していくと、現在それに取り組んでいるところです。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"具体的にどういうところを頑張っていて、どういった指導とかを行っているのか、教えてください。併せて２年生に重点的に行っていくことも、何かそういった全体的な展開として考えていらっしゃるのかというのを説明するよう求めました。","respondent":"丸谷教育総合支援センター長","answer":"継続的な指導を受けられていない６１人の児童・生徒についてですけれども、クロスとしての分析はできておりません。５年生、８年生では、指導に生かしている状況です。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"非認知能力の育成は、今年度から始まったのでしょうか。ぜひお願いしたいと思っているのですけれども、この５件は発生しているのか、その５件がどういった状況であったのか説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"不登校が継続してしまって、例えば１号のみの場合で、重大事態として認定するようなケースも出てくると捉えております。ケース・バイ・ケースの対応になっています。","id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"質問","question":"８８人がいわゆる登録されているのですけれども、幾つかのマイスクールでは１日に２人とか、数人ぐらいの通室になることもある。そういった意味で、この登録された方々がほとんど満帆という状況ではないと思うのですけれど、そういった状況についてはどのようにお考えか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"新規の受入れがなかなか難しい状況が令和５年度まで続いていたのですけれども、昨年度は、やや余裕があるような状況でした。マイスクールは公的機関の１つですので、何とか一歩、外に踏み出せる１つの居場所となれるようなマイスクールを目指していきたいと考えております。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ほぼ学校という形でしているわけで、何とか少し行ってみようかという感じでここに来る児童・生徒が増えていくことが、非常にありがたいと思うのです。高校にそのまま行く子たちもたくさんいるとお聞きしているので、そこの充実を求めていくのですが、そこだけ最後にお願いします。","respondent":"丸谷教育総合支援センター長","answer":"やはりマイスクールは学校との連携が密にできるので、日々の通室の状況ですとか、そういったものを綿密に行っております。そういった特性もありますので、今後も、そういった学校とも連携を密にした教室であるように努めてまいります。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そういうのは非常に学校と密にやっていただいているとお聞きしているし、今お話があったように、しっかりとそういった方向で頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"まつざわ委員","kind":"質問","question":"指導してくれている、そういうＳＮＳ指導のたまものであるのか、この数字はどう考えるのかというのが１点。昨日の話ではないですけれども、初期に見つけていくのが非常に大事だと思うのですけれども、そこだけ説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"学校では指導を継続して行っておりますけれども、また、家庭でも正しく使えるようにと指導は続けていきたいと考えております。早期に関わることが、やはり大切だという認識を我々も持っておりますので、支援体制についても今後の検討課題と捉えております。","id":"exchange-038"},{"speaker":"筒井副委員長","kind":"質問","question":"まず不登校の解消、その辺りはどのようにお考えなのか、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"少なくともこの資料左側の一番下の円グラフの中の相談・指導等を受けていない児童・生徒をゼロにするというのは、１つ目標にしたいと考えております。生徒では９４名、割合では２２.７％の生徒が学校に復帰、分析していきたいと考えております。","id":"exchange-039"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"やはり教育委員会としては、学校に復帰していただきたいということで理解しました。こうした原因が上位を占めていることについてどうお考えなのか、また、その解消についてどうお考えなのか説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"そんな中で、学校が安心できる場づくりを目指していかなければならないというのが、我々の認識です。取り組んでおりまして、子どもたち同士、教員と子どもの関係性・絆づくりも深めていきたいと考えています。","id":"exchange-040"}]},{"id":"topic-05","title":"品川区教育振興基本計画・品川区教育ビジョン アクションプラン","agenda":"品川区教育振興基本計画・品川区教育ビジョン アクションプラン","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"変更点などがあるのか伺いたいのと、冊子で８ページの重点施策で、これが何なのか伺います。ウェルビーイング教育になるとどうなるのか、実際どんなことをやるのかを伺いたいと思います。","respondent":"唐澤教育施策推進担当課長","answer":"これまでの教育からの変更点ですが、６ページの内容になりますが、これが教育振興基本計画でも示している学びの羅針盤です。各教科の中で活かしていく形で進めておりますので、周囲との関わりなど、意識変容につながっていくように取り組んでいければです。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"具体的にはどういった形になるのか、何か具体例があれば伺いたいのと、そうしたところがどんなことをしているのかをお聞きしたいと思います。冊子２１ページを読むと、促進していくのがウェルビーイング教育と受け止めているのですが、そこの確認もさせてほしいと求めました。","respondent":"唐澤教育施策推進担当課長、丸谷教育総合支援センター長","answer":"先ほど申し上げた冊子の２ページ、踏襲するものは踏襲、ブラッシュアップするものはブラッシュアップする形で進めていければと考えております。具体例は後ほどまたお答えしますが、考え方として… 社会全体がより豊かになったり、幸せになったりするにはどうしたらいいか、学習を進めていく内容になってあります。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"今、教科担任制ですから担任の先生が担当ではない教科のときには教室からいなくなってしまって、ほかの教科の人が授業をやりに来るということです。それをどうやられているか伺います。","respondent":"酒川指導課長","answer":"現在は、来年度は５校で、ここは東京都に学校の中でどのようにこの加配を使って教科担任制を行っていくかのプランを提示しながら行うものです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"２校あって、これから５校になっていくというところで、そこを伺いたいと思います。ほかに実施しているところと実施していないところの違い、理由を伺います。","respondent":"酒川指導課長","answer":"１人の教員との関係に苦しみを感じる子どももいる中で、実施している学校からは、相談先が増えたといった声も聞こえているところです。関わる教員全員が密に情報共有して、時にはそういった不安を感じる子どもには個別のケアを行うなどして、より円滑に実施しています。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"教育委員会の考えとしては、早めにやったほうがいいと考えているのか、伺いたいと思います。スケジュールのところで、令和９年度実施について検討と書いてあるのですけれども、これはどういったことを検討するのか伺います。","respondent":"酒川指導課長","answer":"開始の時期ですけれども、３年生から実施し始める学校、それから５年生から実施し始める学校があり。様々な調査を学校に実施、教育委員会が実施している調査を俯瞰してみて、この学力定着度調査についても実施の是非も含めて検討するものです。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"学力テストについては、区が実施しているものは精査する必要があると考えたということですけれども、そういう考えに至った経緯を伺えればと思います。できない子がよりストレスを感じる、自己肯定感が弱まってしまう問題があると思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"５２ページの特別支援教育の充実では、今後、どういった内容をお伝えしようと今のところ考えていらっしゃるのか伺います。言葉の教室とか、ぜひここは予算も含めて充実をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長、唐澤教育施策推進担当課長","answer":"設置が進んでおりまして、他自治体等も注視しつつ、設置に向けた検討を進めていこうという考えです。特徴としては、不登校状態にある児童・生徒の１つの学びの場として提供できたりといった学校となっております。特別支援教育の推進計画につきましては、必要な支援は現在も実施しておるところですが、検討していく形となります。","id":"exchange-047"},{"speaker":"まつざわ委員","kind":"質問","question":"例えばうちも６時過ぎに先生が電話をくれて、対応が随分、夜間でも実際やっていらっしゃるわけです。そこら辺の現状を説明するよう求めました。","respondent":"酒川指導課長","answer":"状況によるとは思いますが、全校で実施しているものですけれども、子どもの安全に関わる内容ですとか、緊急を要する場合にはそれによらない場合もあるとは考えております。","id":"exchange-048"},{"speaker":"まつざわ委員","kind":"質問","question":"冊子のページだと１１になります。例えばこの教育ダッシュボードがそもそも何なのか、教育ダッシュボードをやると、具体的に教師のマネジメントはどう軽減されるのか説明を求めました。","respondent":"唐澤教育施策推進担当課長","answer":"出欠状況、またはこれまでの支援とかアセスメントなどが一覧で分かることによって、校内委員会や今後の支援に係るそうした委員会の資料準備ですとか。今後、また検討していくようになりますので、子どもたちの情報を分かりやすくしていくという形で捉えていただけたらと思います。","id":"exchange-049"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"例えば現場の先生がどう思っているかとか、またそれが振り返りになるように、計画にぜひ入れてほしいと求めました。時間もかけてやってきているのですから、策定をすると決めたわけですから、最後にそこだけ。","respondent":"唐澤教育施策推進担当課長","answer":"策定に当たっては教職員の方から意見を聞くなどは、現在、実施している市民科と同様に必要と考えています。ご意見として承らせていただいて、現在はこのアクションプランを基に今後、教育委員会としては動いていくような形でご理解いただければと思います。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問","question":"私からは冊子の１２ページのアクションプランの進行管理をお伺いしたいのですけれども、具体的にどういった形で見直されていくのかと、詳細を説明するよう求めました。","respondent":"唐澤教育施策推進担当課長","answer":"適宜、実行するアクションプランについては見直しをして、数を修正していくという形で捉えています。５年間の計画という形で子どもから意見集約しておりますので、新たに令和１１年が終わったところで、そうした検討に入っていくものと考えております。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"やはりやってみて、そこでいろいろご意見等も出てくると思いますので、しっかり捉えて反映させていただきたいと私は思っております。令和８年にＣＢＴ化予定とあるのですが、こちらの例えば理科とか、どのようなものがあるのか説明を求めました。","respondent":"酒川指導課長","answer":"デジタル化したときに大きなデメリットになるのは回収率等があるかと。より精緻な結果の分析ができるといったこともあると思いますので、専門部署等とも連携しまして、より効果的なデジタル化を図っていきたいと思います。","id":"exchange-052"},{"speaker":"横山委員","kind":"質問・要望","question":"しっかりと意見が反映されて、しっかり届くように全体として考えていただきたいと考えていますので、よろしくお願いいたします。令和１０年に分教室型の設置になっているのですが、あとどういった形で、教えていただけたらと思います。","respondent":"丸谷教育総合支援センター長","answer":"分教室型は、東京都内でも複数の自治体がこの分教室型を進めているということもございまして、まずは分教室型を目指そうという考えに至ったものです。施設等につきましては、現存の区施設を様々検討いたしまして、決めていきたいという考えです。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つ目はＰＴＡの支援とあったのですが、現状でＰＴＡという組織がもし分かれば、もうやめましょうとなった学校がどれぐらいあるかお分かりですか。冊子の６９ページの表を見ると、令和８年度は敷地の測量とか、その点についてどうお考えになっているか。","respondent":"舩木庶務課長、石井学務課長、酒川指導課長、米田教育次長","answer":"会長とか副会長を置かずに、全ての方が役員という位置づけで、協力できる方が協力する中でという体系をとっているのが１校あると理解しております。… 私からは、１人１台端末の更新についてお答えいたします。まずは普及をすることが第１期の課題ではありましたけれども、引き続き… 区独自としまして、そこにあります指導助手それから区費の講師といった配置も行っております。地域連携を進める上では、学校地域コーディネーター… 学校改築の担当課長がおりませんので、私からお答えをします。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"確認","question":"タブレットについては、もう普及したので、今度、活用をどうやっていくか、学校も含め、教育委員会も含め、進めていくと確認しました。改築については、令和８年度の予算の中で教育の思いがどれだけ出てくるかを期待していますので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"筒井副委員長","kind":"質問","question":"１番目なので、各教科に合わせて、ウェルビーイングについて教えてください。時間の比重をかけずにやっていくのか、どのように進めていくのか、現時点で分かる範囲で教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"具体的には、ウェルビーイングを考えていったときに１つの指標を考えています。今年度の９月２１日に発行した広報しながわの教育特集号の中でも、こういった教材を活用しながら、子どもたちが学んでいくものになってあります。","id":"exchange-056"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問","question":"児童相談所の部分であったり、子ども家庭支援センターの部分であったりあると思うのですが、区のお考えをそれぞれ教えてください。再統合支援ですけれども、そののり代型の情報共有はどういう粒度で、どのような形で行われているのかという詳細を説明するよう求めました。","respondent":"長谷川児童相談課長、吉野子ども家庭支援センター長","answer":"それから家庭復帰後の支援と再統合ののり代になりますけれども、家族再統合事業を区において進めしています。その過程におきまして、子ども家庭支援センターも支援会議に同席していただいて… 子ども家庭支援センターとしての役割ですけれども、実際にご自宅に伺わせていただいて、家庭の状況等を調べします。それによって、あと育児ヘルパーが必要であれば、そういったものを提供するようなことをしております。","id":"exchange-057"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほど、乳児院措置児童の数が５名ということでお伺いしました。まだ児童相談所が品川区立になってから１年なので、今後の様々な施策に活かしていただきたいと思っておりまして、少しお伺いをしました。","respondent":"長谷川児童相談課長、吉野子ども家庭支援センター長、丸谷教育総合支援センター長","answer":"その都度、その子に合った支援やアプローチ方法については、個別に相談をさせていただきながら支援をしています。… 家庭の孤立を防ぐことであったりとか、小さな気づき段階の支援につなぐことが重要であるということは認識しております。ここで… ただ、様々な家庭状況がありますので、例えばＨＥＡＲＴＳに子どもや保護者から相談があったときにも、関係機関の１つとしてつなぐこともあります。","id":"exchange-058"},{"speaker":"まつざわ委員","kind":"質問","question":"子ども家庭支援センターの協議ケースと児童相談所の協議ケースがあって、合同会議があって、対応機関の決定と書いてあります。これは結局この会議をどう決めて、どういう方針がこの合同会議の中で行われるのかを少し詳しく説明を求めました。","respondent":"長谷川児童相談課長","answer":"自分の機関で対応できるのであれば、もうそのまま対応いたしますが、最速の動きをとっているのが実情になります。そこまでリスクが高くないので、子ども家庭支援センターの対応でお願いしたいという場合もありますし、それぞれの場面で使い分けている状況です。","id":"exchange-059"},{"speaker":"まつざわ委員","kind":"質問","question":"要は、受け入れようとしても、もうぱんぱんな場合はどうにもならないではないですか。例えばこうやってもうぱんぱんの状態の中で緊急な課題はどうするのかということと、このぱんぱんな現状でどう考えていくのかを説明するよう求めました。","respondent":"長谷川児童相談課長","answer":"その場合には、静養室を活用したりですとか、所内で工夫しながら可能な限り、対応しています。特別区と東京都の間で協定を結んでおりますので、広域調整ということで、他の児童相談所の一時保護所に措置を委託するというケースもあります。","id":"exchange-060"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"どうするかというときに、そういったそういう分野に特化した民間との連携も強化をしていく必要があるのかというと、子ども食堂と再発防止。そこのルール、マニュアルはあるのかというのが少し疑問なのですが、それを説明するよう求めました。","respondent":"長谷川児童相談課長、柴田子ども施策連携担当課長","answer":"現時点で適正な数を確保しておると考えておりますが、虐待対応件数から算出する部分と、適正な数を今後も確保していきたいと考えています。支援が終わったからといって、安定して地域での生活が送れているかどうかや… こちら利用に当たっては、措置（解除）が予定されている子どもに、早めにこの事業を周知して、施設にいる間、里親にいる間から認識をしていただく。","id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問","question":"３番の課題ですけれども、そういった面についての当局との働きかけ、リクエストはどうなっているのでしょうかというのが１つ。もう１つは６番の人材の話があるのですけれども、どうとかという中でのそういった職員の方への支援はどういう形でやられているのかお尋ねします。","respondent":"長谷川児童相談課長","answer":"その後、特にこちらからまた新たに財政課に話しかけることは特段してございませんので、区全体の調整の中で話は進んでいくものと認識しております。その事例の引継ぎをしていきますというのが、まずありますので、その全国ルールに基づいて運用しているのが実態です。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"児童相談所をどうしていくかというか、こういった児童相談所に関わる子どもたちをどうするかということを考えるような風土といいますか、その点だけ。職員の方、いろいろ本当に苦労されていると思うので、ぜひフォローとか支援の体制をお願いします。","respondent":"長谷川児童相談課長","answer":"例えば単独の区で設置した場合であっても、品川区として、どう施設面での折り合いをつけるかというところは本当に課題だと考えています。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問","question":"一時保護所を増設となるのか、フェーズを広げるということも考えていかなければいけないのかと思うのですが、そこのところを伺いたいと思います。そこをまず伺います。","respondent":"長谷川児童相談課長、原品川区児童相談所長","answer":"全庁的な議論の場で検討されていくものだと捉えておりまして、まず目の前にある子どもたちの支援に全力で注力しているという段階です。ただ認識的には気になる子どもは一定数いるかです。 発達課題のある児童について、少し補足的に説明します。あるいは自分の気持ちを言葉で表現できないとか、そういうような、一言で言ってしまえば愛着障害。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"今、区の考えがあれば伺いたいと思います。乳児院に入っている方が８２人ということで、そうした施設の増設も区内で整備していくことも必要なのかなと思うのですが、いかがか尋ねました。","respondent":"長谷川児童相談課長","answer":"支援していかなければならないというところで、全庁的な議論にはなるかとは思っておりますが、それがメインテーマにはならないと考えています。もう１つ、区にたとえ設置したとしても、なかなか判断としては難しいと思っています。","id":"exchange-065"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"えのした議員の質問のところです。もう１つは、現状は２,６８０円で一律なので、お尋ねします。","respondent":"酒川指導課長","answer":"現状ですけれども、現在、実費支給に向けまして、関係課と協議、調整を図っているところです。経験年数の加味については、今のところ、検討の俎上に載ってございません。","id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"質問","question":"東京都は今年度の４月から、１日、７,１００円と改定されたとお聞きしているのですが、その辺りの上限。例えば１０年、１５年やられた方が区費の時間講師をやろうとしたら、伺います。","respondent":"酒川指導課長","answer":"他自治体がどういった設定をしているかと研究した上で、品川区としてどのように設定していくか、検討していく予定です。これは絶対に実施しないということではございませんで、また、検討の余地があると考えています。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それはもう資質に応じてやはり報酬は高くなるべきだと思うので、ある程度、経験年数を加味した報酬にしていってほしいと求めました。検討するというお話だったので、それは今すぐはまず交通費で、経験のほうは、まだ来年度はそこまでいかない認識でよろしいか尋ねました。","respondent":"酒川指導課長","answer":"おっしゃるとおりです。どのような人を配置していくのが最適かという、総合的に判断する中で検討していくことになろうかと考えています。","id":"exchange-068"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もう１つは、思いをしっかりと財政的なところ等、進めていってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"会計年度任用職員の時給の問題で、私たちも全体としてということですけれども、長年勤めても給料が上がらない問題を指摘してきました。より充実したものが提供できるということになっていくと思いますので、ぜひ、そこは私からも時給アップをしていくことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/843512?Template=document&Id=7225#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":67677,"voices":252}},{"id":"r07-20251126-5","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"総務委員会","time":"午前１０時１０分～午前１２時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"引き続き、処遇等を同一労働同一賃金になるように、ここは改めて求めておきたいと思います。１３６、お伺いしたいのですけれども、引き下げていくという検討や判断はなかったのかというのをお聞かせほしいと求めました。","respondent":"藤村総務課長","answer":"今のご質問の趣旨としては、社会情勢を踏まえて、引下げの点はなかったというところだと思います。そちらを勘案させていただいたのを今回、議論、調整する形です。","id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"本来、公務員給与改定と同時に、区民の生活をどう支えるかという生活パッケージが私は提示されるべきだと思います。ご見解を説明するよう求めました。","respondent":"宮尾人事課長","answer":"ですが、一方で、これだけの物価上昇の局面の中で、区民の皆様の生活が大変厳しいものにあるという状況については、私もしっかりと認識をしています。","id":"exchange-002"},{"speaker":"須貝委員","kind":"意見","question":"品川区の周りにたくさんの中小規模の企業やお店、個人事業主がたくさんあるわけです、中小企業を含めて。実際、平均には見えないのですが、その辺りについてもう一回だけご答弁くださいとの意見を述べました。","respondent":"宮尾人事課長","answer":"そういったことも含めますと、今回も含め、人事委員会で出された結果というのは、しっかりと尊重していくことが望ましいと考えています。委員からいただいたご意見もしっかりと踏まえて、我々は今後の仕事に取り組んでまいりたいと考えています。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"もっと区民の目線、それから区内産業の目線というところを調べた上で、私はやってほしいと求めました。私は賛成できますけれども、ほかのパーセントで３０万円も４０万円も年収が上がるということ自体には、賛成いたしかねます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"今の社会情勢や経済状況を見るならば、上げるべきではないと思います。委員長がいろいろお話しいただきましたけれども、今の状況を見て、理解を得られる状況かといえば、そうではないと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松本委員","kind":"提案","question":"逆にそれは議会側から提案すべきかなと考えています。これは身を切る改革というところもかねてから、ぜひとも他の議員の皆様に、考えていただきたいという思いから反対いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"なので、社会変動に合わせていろいろ変えていくというのも当然あり得ることだと思いますので、これは正しい判断なのだろうと。それは議会の中での議論の項目であって、この場で話を進めることではないと思いますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"松本委員","kind":"意見","question":"本区の場合は、区長が既に自身の議員報酬の２割カットということをやられている。特別職のものについて反対していくというのは、そのような資格はないと考えておりますので、賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"特別職の話は先ほどさせていただいて、一般職のほうですけれども、こちらの算定の基準などで、従前、２年前までは反対していました。考え方によってはさらに悪化しているという状況ですので、こちらも我が会派に反対する資格はなしと考えますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-02","title":"第１２１号議案、令和７年度品川区一般会計補正予算","agenda":"第１２１号議案、令和７年度品川区一般会計補正予算","exchanges":[{"speaker":"西本委員","kind":"質問","question":"喜ばしいことではあるのですけれども、何が起きているのですかということ。それから収益という兼ね合いで、経費に関わるという現状なのか、経費がかかったとしても増やしていくという方向なのか説明を求めました。","respondent":"加島財政課長、宮澤税務課長","answer":"７２億円の予定価格に対しまして、最新の単価等で試算等を行いまして、再入札に備えたいという考えです。令和８年４月になりますと、１４億円よりもさらに上がってしまう見込みがあるということで、今回… ポータルサイトを利用する際の利用料というのは、寄附額の大体１０％から１３％が手数料としてかかることになります。寄附額の大体、返礼品の調達費用も含めて、５割以下が経費にかかっているです。","id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"計算してみたら５億円上がっているということで、それをもう一度やり直しという形の理解でよろしいでしょうかということで、確認させてください。９月は別にしても、ほかのところで１桁どころではないではないか尋ねました。","respondent":"加島財政課長、宮澤税務課長","answer":"ただ、現実問題、入札不調となったことにつきましては、所管課である庶務課もですし、財政課としても真摯に受け止めております。予算編成段階で、従来どおり３社から見積りを取りまして… ふるさと納税の部分ですが、まずは返礼品の品目を増やすというところで、いろいろなものを見ていただくというところが大きいところです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"何か人気のキャラクターとかを使ってやったのですか。これだけあるのはそういう力が働いたことなのだなとかと分かるのですけれども、どういうものでヒットしたのかなと思うのですが、いかがか尋ねました。","respondent":"宮澤税務課長","answer":"小型家電になるのですけれども、それが大変ヒット商品でして、寄附にも反映していると。で、例えば楽天トラベルまたはＪＡＬのダイナミックパッケージといった、品川区を宿泊先とする旅行も返礼品として用意しているところです。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"返礼品についてお聞きしたいのですが、これは約１億６,９００万円入って、事業費として８,０００万円以上かかってしまうということですか。というと、もし寄附がなくなれば赤字に転落するという状況になっているのか尋ねました。","respondent":"宮澤税務課長","answer":"経費の部分なのですけれども、寄附があれば初めて経費が発生するということになりますので、寄附がなければ支出は、基本的な部分はないということになります。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういうことも私は努力していただきたいと思うし、簡単に３社か４社だったら、言いなりになってしまうではないですか。このような手法というのは誤解も招くし、私はやはり改善するべきだと思うのですが、その辺りについてご見解を説明するよう求めました。","respondent":"佐藤経理課長","answer":"区の事業者の選定のお話ですので、私からご回答いたします。区内の事業者だけでは十分な競争性が担保されないという案件については、そういった条件を外して、広く入札に参加できるという条件を整えております。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"だから、このような不調になる事例も私は生まれるのだと思うのですが、そういう心配は経理課でされないのですか。そういうことも改善していかないと、皆さんの税金で成り立っているわけですから、そういうところの改善ということも考えられないのか尋ねました。","respondent":"佐藤経理課長","answer":"合わなくなったというところですので、今後については予算的にも、あるいは積算的にも対応するということで関係課で調整をしております。以前は事前の説明会というところで、現在そういったことをやっておりませんので、そういったところで不正の防止にも努めているところです。","id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"最後ですけれども、入札をまた皆さんに募集するということですが、昨日のインフレスライドでも値段が上がったのは平均３％です。それを思うと、今回またさらに上乗せして価格を設定するというのは、何か不思議なような気がするので、意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"松本委員","kind":"意見","question":"これは本当にマックスで、例えば懸念するのは、５割を超えてしまうと制度から排除されるというのがあるのではないか。これにバッファーも含めて、今回この補正を出されているということでよろしいのか、お願いいたしますとの意見を述べました。","respondent":"宮澤税務課長","answer":"委員ご指摘のとおり、経費を５割以内に収めなければいけないというところで、経費を算出していますので、委員ご指摘あった、例えば配送料が上がる場合という形になりますと、経費が上がる場合は寄附額を見直して、寄附額を上げるという形を取るということを想定しております。","id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"どうしても３割が返礼品でも、残りの２０％のうちのかなりの部分が業者に流れてしまっているという、これも問題がある制度だと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]},{"id":"topic-03","title":"令和８年度労働報酬下限額に係る品川区公契約審議会の答申","agenda":"令和８年度労働報酬下限額に係る品川区公契約審議会の答申","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"適正に労働者に賃金が払われているのですかというところまで踏み込まないと、これは絵に描いた餅で、何にもならないのではないですか。その辺りについてはどのようにお考えか尋ねました。","respondent":"佐藤経理課長","answer":"こちらは公契約条例の中でも想定しておりまして、対象になる契約を結んだ事業者から、支払っているかどうかという報告をいただくことになります。もちろん令和８年４月１日以降の契約になりますので、４月までの間に十分準備を整えて、適正に行っていきたいと考えております。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"区としても、本当に労働者を守れないという観点から協力してほしいという、そこまで踏み込んで私は見るべきではないかと思うのです。きちんと賃金をどのように払ったという明細書が出るわけですから、報告書をもらいます、報告書など幾らでも書けるではないか尋ねました。","respondent":"佐藤経理課長","answer":"公契約条例を制定、公契約条例の在り方について検討会ということで開かせていただいて、条例をどのような形にするかということを検討いただきました。区に申告いただいて、それに基づいて調査をするということはやってまいりますので、そういった形で運用したいと考えております。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"何か対応してあげないと、せっかくいい条例をつくったのですから、私は今後踏み込んでやってほしいと求めました。簡単に数字として出せるわけですから、そんなに負担はかからないと思うので、ぜひいい方向に持っていくように努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"西本委員","kind":"確認","question":"１の（１）のところに９０％を乗じて得た額と書いてあるのですが、９０％というのはどこかの目安みたいなのがあるのでしょうか。別に８０％でも８％でもいいということになるので、根拠はどこにあるのでしょうかということと、下請のところの末端の額のことを言っているのか尋ねました。","respondent":"佐藤経理課長","answer":"次に、一つは今申し上げたとおりで、実際働いている方がもらう報酬がこれ以上でなければならないという下限額というところです。特に工事で見られますが、下請のところの事業者に対しても、この金額以上の報酬を払うようにという立てつけになっております。","id":"exchange-022"},{"speaker":"西本委員","kind":"確認","question":"何を想定されているのですかということが１点と、さっきの須貝委員の質問にもあるように、それを誰が確認するのですかという話です。誰がやるのですかということを説明するよう求めました。","respondent":"佐藤経理課長","answer":"それについて９０％というのを下限にしようというところで、これまで他自治体でも議論されて、この数値になっているとご理解いただければと思います。支払っていることについては、区に対する報告を受けるという形で担保していくという形になります。","id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"それを監視というか、調査というか、確認するということの流れができてきていたのかなという思いがあります。なので、末端の働いている方々の給料にどのように反映されているのかということは、しっかり見ていただきますようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"１２月以降に区長が令和８年度の労働報酬下限額を告示ということで、していくべきなのではないかと思うのですけれども、その辺りはいかがか尋ねました。","respondent":"佐藤経理課長","answer":"１つ目は告示の仕方というところですけれども、指定管理の分野および工事、工事のほうは職種ごとという形で告示することを予定しております。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いかがでしょうかということと、資料の３ページ目の、３番の委員からの意見。ここで、それを行うことが望ましいという（１）（２）で、区としてはどうしていくのかというのを教えてほしいと求めました。","respondent":"佐藤経理課長","answer":"２点ありまして、こちらとしても考えているところですので、これから検討していきたいと考えております。委員からいただいた意見については、そういったところで引き続き、ご審議いただいていくことを予定しております。","id":"exchange-026"},{"speaker":"塚本副委員長","kind":"意見","question":"今回の公契約の審議会には、労働組合の団体からも２名ほど、たしか入っていると思います。もしそのとおりになっていないのであれば、そういったことについてもサポートできるのだろうと思いますが、その点について一言だけお願いしますとの意見を述べました。","respondent":"佐藤経理課長","answer":"共倒れではないですけれども、社会全体として回らないというところもあって、非常に建設的な議論をいただいたと考えております。労働者の方から申告いただく際もサポートいただけると考えておりますので、来年度以降、運用に向けて頑張っていきたいと考えております。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問・要望","question":"他委員からの質問の答弁で、来年度以降も審議会が開かれるということが確認できました。この基準を丁寧に見ていただきたいと思うのですけれども、区長に対し答申できる内容を固めてほしいと求めましたので、考えを確認したいと求めました。","respondent":"佐藤経理課長","answer":"来年度の数値が出てくるのがこの１０月ぐらいからというところもありましたので、今年度についてはそういった形で開催いたしました。来年度以降もそういった形で考えておりますけれども、あるいは追加してということがあれば、対応していきたいと考えております。","id":"exchange-028"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"それに対して、質問の中にありました高橋しんじ議員のところでは、警察と、それから区の見解の乖離があるという話です。今年の５月２日に、何をもって警察の見解と違うということを言っているのか、まずそこを確認したいと求めました。","respondent":"川村コンプライアンス推進担当課長","answer":"調査結果を受けました区の対応としましては、厳重注意の措置を行い、後日返却した旨の報告を受けました。今回の事案を受けまして、区では、再発防止と服務規律の徹底に努めてまいります。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"刑法第２５３条業務上横領罪に該当するものではないということなのですが、ただ、まず物品は何ですか。もちろん、相手側とこちらの誰か、個人情報がありますので誰かまでは言えないと思うのですけれども、どういうものかというのは公表できないのか尋ねました。","respondent":"川村コンプライアンス推進担当課長","answer":"前置きといたしましては、通報者の特定につながらないように、個別の詳細についてお答えできない部分があることはご承知いただければと思います。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"現在、どういう状況になっているのですか。関連団体に返したということか尋ねました。","respondent":"川村コンプライアンス推進担当課長","answer":"お答えできる範囲となりますけれども、保管してあったというところで、使用場所というところは把握できるものと思われます。返却につきましては、借りたところに返したという意味での報告です。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"返したのは、関連団体からの備品という一覧の中に、それは入っているということでいいですか。そこに返したということの証明がきちんと伝票等で、備品管理の中でもなされているという感覚でいいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（秀）委員長","kind":"質問","question":"だけれども、公益通報者には、警察はそういう考え方もあるのではないですかと言った。それが何で、どれをどうして何に使ったかというのをここの議会でやるのは、話がずれてきていると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"西本委員","kind":"確認","question":"だけれども、それをきちんと返したという確認は、どうされているのですかというのを聞いているだけです。それを確認していないのだったら、きちんと返したということを確認していないということではないか尋ねました。","respondent":"川村コンプライアンス推進担当課長","answer":"西本委員のご質問にお答えいたします。これが確認の事実です。","id":"exchange-034"},{"speaker":"西本委員","kind":"確認","question":"それはこの関連団体から、きちんと確認を取れているのですか。それを確認したいと求めました。","respondent":"川村コンプライアンス推進担当課長","answer":"通報者の特定につながらないようという制約の中でお答えしておりますが、報告を受けて確認しておりますので、これ以上のご回答は差し控えします。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"どこという名前を言ってほしいとは言っていません。関連団体からそれを受け取りましたという報告はいただいたということでよろしいか尋ねました。","respondent":"川村コンプライアンス推進担当課長","answer":"こちらとしましては、返却されたことはきちんと確認しております。","id":"exchange-036"},{"speaker":"西本委員","kind":"確認","question":"警察が言っていることと乖離がないということは、警察は横領的な行動ですと言っているのだから、そのような認識になるのではないですか。そうしたら、それに応じた処分が必要なのではないか尋ねました。","respondent":"川村コンプライアンス推進担当課長","answer":"警察では立件を予定していないということから、業務上横領罪として認定するに至らない理由があったのではないかとこちらは推察しております。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"それはどうなのですか。それはどうなのか尋ねました。","respondent":"柏原区長室長","answer":"そうしたところから考えますと、我々が不当利得に至っていないというところのアンサーというのは、差異はない。改めて申し上げますけれども、警察にも改めて確認したところ、立件はしない、事実認定はないというところを確認は取れています。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"５月に出てきました。この間の質問の答えは、警察の見解を踏まえて再度見直しをするということは、しないということだったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"そこはどうなのですか。警察の見解も含めて乖離はないというのは、今回の一般質問で分かった話であって、何も言っていないではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"西本委員","kind":"意見","question":"だから、それをやるべきだというのを高橋しんじ議員がとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜかというと、備品が帳簿上どうなっているのかというのは、ぜひすぐやってほしいと求めました。証拠となるものを頂くということは、ぜひやってほしいと求めましたので、それをお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=7275#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":40983,"voices":173}},{"id":"r07-20251126-10","meetingId":"r07-cm11","date":"2025年11月26日","dateIso":"2025-11-26","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982705?Template=document&Id=7199#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":3088,"voices":16}},{"id":"r07-20251127-21","meetingId":"r07-cm11","date":"2025年11月27日","dateIso":"2025-11-27","committee":"子ども若者支援・共生社会推進特別委員会","time":"午前１０時００分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"初めのところから伺いたいのですけれども、これからの重点取組というところで、令和１１年度の目標値というのが書かれているのです。その利用者数が令和１１年度の段階ではあまり変わらないというところでは、まだ令和１１年度のところでは、その点を伺いたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"必要な需要はあるというふうに見込んでおり、第２のフリースペースといいましょうか、なるべく早くと考えているところです。そして人員体制は、常勤職員が４名、それからサポートスタッフが様々いるという状況にあります。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこら辺のところはいつ頃までにとか、どのように適地を見つけていくのか、というところはどう考えられているのかということを伺えたらと思います。いろいろなことが求められると思うのですけれど、令和４年度に取られて、あったらお聞かせいただけたらと思います。","respondent":"柴田子ども施策連携担当課長、吉野子ども家庭支援センター長","answer":"決してたまたま見つかったからやるというわけではなく、本当に積極的に探しています。まだ、先方もあることだったりいたしますので、明言は避けします。 令和７年度も同じように実施させていただきまして、周知のほうを図っております。小学校６年生対象なのですけれども、そういった寸劇をやったり、ヤングケアラーとは何かというところのご説明のほうをしています。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"ヤングケアラーを支援するために必要だと思うのはどのようなことですか、３者面談のときとか、どれぐらいの学校でされているのかということについてもお聞かせいただけたらと思います。","respondent":"吉野子ども家庭支援センター長","answer":"令和６年度に１件あったのですけれども、あとは、学校のいわゆるいじめであったりといったところになります。なかなか手を挙げていただけるところが少ない状況でありますので、引き続き働きかけていきたいと考えております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に学校に求められることが多くて、大変だなと。このヤングケアラーというところも、今の段階では、そこら辺のところもどうなっているのかというのが分かったら教えていただけたらと思います。","respondent":"吉野子ども家庭支援センター長","answer":"確かに、養護教諭の方ですと、例えば兄弟がいて、その子の面倒を見ていたりなどといったこともあり得ると思いますので、今後なのですけれども、やはりそちらの学校のほうにはさらに働きかけていきたいと思っています。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"養護教諭のところに救いを求めてくるというか、養護教員も忙しいとは思うのですけれど、養護教諭は特にそういう研修はいろいろぜひともやっていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"もう一点が、小学生ぐらいの子ですかね、矢野耕平さんという方がネオ・ネグレクトという本出されています。実は独りぼっちの子などにもうまくつながるように、こちらから手を伸ばしていくような形、その辺に関してはいかがでしょうかというのが２点目です。","respondent":"東野福祉計画課長、柴田子ども施策連携担当課長","answer":"実は、１０代の子に対してのアプローチというのが今、そのための対策を考えなくてはいけないうちの一つだと認識しています。全国的に見ると、実は１０代の子からの相談が一番多いというような結果も出ておりますので… 全ての児童センターにフリースペースの案内のパンフレット、結構な枚数、毎年設置をしております。児童センターの職員もフリースペースのことを認識しておりますので、子どもたちが、体制のほうは整えているところです。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問・要望","question":"１０代の声も今後重点的にということですので、学校の先生はやはり忙しいので、うまくつながる形をつくっていただけたらなと思います。どうしたいのかなというので、今後継続的に地域とつなげるような取組があったらいいなと思うのですが、その辺についてはいかがか尋ねました。","respondent":"東野福祉計画課長","answer":"つまり、地域でのサードプレイスをどうつくってどう運営していくかみたいな話も、現在取り組んでいるところです。来年度の事業として、福祉計画課のほうで、コーディネートしながら取組を進めたいと考えております。","id":"exchange-007"},{"speaker":"澤田委員","kind":"質問・要望","question":"資料の１つ目のところで、具体的にはどんなことが挙がっていたのかなというのを、もし分かれば教えていただきたいなと思います。","respondent":"柴田子ども施策連携担当課長","answer":"こちら、こども計画を策定するに当たりまして、子どもの意見でしたり、子どもを支援する団体にヒアリングを実施し、生の意見をいただいたところです。ただ、このヒアリング自体は８団体が参加していただいて、幅広く意見をいただいた中の一つということで掲載しています。","id":"exchange-008"},{"speaker":"澤田委員","kind":"意見","question":"それと続いては、今度は資料の右側のところの、支援機関同士の連携をさらに強めていくと。強化というところで、どういうふうに具体的には強化をしていこうと思っているのか、お考えを聞かせほしいと求めました。","respondent":"柴田子ども施策連携担当課長","answer":"現在実施しております、品川区内の様々な５０ぐらいの子ども支援の団体が集まる大会のようなものが年に数回ありまして、広がり。子ども向けの事業ですとか説明会、講演会を実施する際は補助金というものも用意しておりますので、団体の活動を支援して。","id":"exchange-009"},{"speaker":"澤田委員","kind":"質問","question":"質問の仕方が変だったのだなというのを今、ありがとうあります、よく分かりました。ヤングケアラーのところで、ほかの委員からもお伺いしていたと思うのですが、そこへのアプローチというのはどのようなことをされているのか尋ねました。","respondent":"吉野子ども家庭支援センター長","answer":"まず、そこから少しずつですが、啓発といった形でやっていこうと思っています。ヤングケアラーとは何かというところから、そういったところのものを始めているところですので、少しずつ広げていきたいと考えています。","id":"exchange-010"},{"speaker":"澤田委員","kind":"質問・要望","question":"親の勉強会みたいなものがあるからぜひどうですかというので行ってみたら、参加者４人しかいなくて、何か考えていただけたらありがたいなと思います。それについてどうお考えか尋ねました。","respondent":"吉野子ども家庭支援センター長","answer":"今、様々なツールを使って、いろいろな方に呼びかけて、そういったところの理解をしていこうと考えていますので、少し参考にさせていただきたいと思いますので、なるべく広げていきたいと考えております。","id":"exchange-011"},{"speaker":"西村委員","kind":"確認","question":"ターゲットごとに大変細かくアプローチを変えていただいているなというのを改めて確認させていただけてよかったなと思っています。この目標値が令和５年度から令和１１年と大分幅がありますけれども、子ども若者応援フリースペースとエールしながわ、それぞれ伺えればと思います。","respondent":"柴田子ども施策連携担当課長","answer":"しかしながら、令和１１年度の相談件数を目標値として掲げているところです。そういった掘り起こしといいましょうか、そういったところを加味しての数字です。","id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"改めて伺いたいのですけれども、最近の傾向を教えていただきたいのと、改めて説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"２０代が２５％、３０代、４０代がそれぞれ５％程度という構成になっています。毎月のヒアリングで、ケースの中身などを聞いているところ、２０代から３０代が相談者の中心となっていると認識しております。","id":"exchange-013"},{"speaker":"西村委員","kind":"質問・要望","question":"子ども若者応援フリースペースみたいなものをどんどん増やしてほしいという思いは私もありますが、増えていないのではないかなという思いがあります。いつでも来ていいよという雰囲気の醸成をさらにお願いさせていただきたいなと思うのですが、その辺のアプローチ、何かあれば説明を求めました。","respondent":"上野子ども育成課長","answer":"委員ご指摘のありました、不登校のお子さんに対して、いつでも来ていいよというところでの周知ですけれども、児童センターも開かれた場所として現在もやっておりますが、今後、もっと幅広いお子様に来ていただけますように、積極的に周知に努めてまいりたいと思います。","id":"exchange-014"},{"speaker":"西村委員","kind":"質問・要望","question":"１点、私もずっと要望していることでして、不登校になった時点で子どもが孤立してしまう。学校との連携強化というのをさらにお願いしたいと思っておりまして、どなたにご答弁いただけばいいのか分からないのですが、お願いします。","respondent":"吉野子ども家庭支援センター長","answer":"ヤングケアラーのほうでは、配食支援というものをやっております。このときに、やはり、その家庭の状況であったりとかといったところも含めて確認のほうさせていただいている状況です。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問・要望","question":"そこをさらに、ヤングケアラーだけではなくて広げていただきたいなという思いで要望をさせてほしいと求めました。ここも伺いたいのと、アンケート結果ですから正しいのだと思うのですけれど、もし所見があればお聞かせほしいと求めました。","respondent":"吉野子ども家庭支援センター長、柴田子ども施策連携担当課長","answer":"令和７年度、１０月末ですけれども、前年度を超えておりまして１４４件になっております。こちらの件数は、だんだんとやはり周知というところが少しずつ広がってきておりますので、相談件数のほうは増えてきております。 どういった周知等をしているかというのは存じ上げないところがあるのですが、こども計画を実施するに当たって取ったアンケートのほうも、こちら正直な結果ということでお受け止めいただければと存じます。","id":"exchange-016"},{"speaker":"西村委員","kind":"意見","question":"タブレットからの、という認識があったので、ここは私も改めて調査をして調べていきたいなと思います。１点だけ最後に、個人情報になりますが、お伝えいただける範囲でお願いしますとの意見を述べました。","respondent":"吉野子ども家庭支援センター長","answer":"最近特に多いのは、親御さんが病気で、いわゆる精神疾患の方が多いというところで、要するに、家の、親御さんの代わりに家事をやったりとか買物をやったりとか、そういった事例が増えてきております。","id":"exchange-017"},{"speaker":"西村委員","kind":"質問","question":"そうなったときに、ＬＩＮＥ相談も大分頑張っていただいているので、子どもたちの相談するルートというのは何が一番多いか尋ねました。","respondent":"吉野子ども家庭支援センター長","answer":"先ほど、学校のタブレットというのをお伝えしたのですけれども、それ以上に、やはりＬＩＮＥ相談というものがとても多いです。こちらのほうで友達登録もされておりまして、こちらが少しずつですけれども増えておりまして、ここが一番多い形になっています。","id":"exchange-018"},{"speaker":"西村委員","kind":"意見","question":"昭和の時代というか、助けてと言える状況をつくっていかないと、本当に孤独・孤立というのはなくならないのだろうなということを改めて思いました。感想ですが、ありがとうありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"いろいろお話を聞かせていただきまして、ありがとうあります。３ページのこれまでの取組のところから、あと回答していない方はどのような背景があるとお考えか、お聞かせほしいと求めました。","respondent":"東野福祉計画課長","answer":"手元に回答数、回答状況の資料はないのですけれども、資料の設問にあったものを取り上げたということでご理解いただければと思います。","id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"今年の取組のオンラインカウンセリングについてもお聞きしたいのですけれども、症状が改善傾向にある一方で継続というのが指摘されております。こちらのほう、具体的に教えていただけますか尋ねました。","respondent":"東野福祉計画課長","answer":"先ほども説明させていただきましたが、区民１人３回まで無料ですというようなご案内をしています。民間機関へその人が継続したいのかどうかというところの調査、そういったものも今後やっていく必要があるかなと考えています。","id":"exchange-021"},{"speaker":"せらく委員","kind":"提案","question":"やはり３回はしっかり相談を受けてカウンセリングを受けて、４回目以降のところの検討、何かありましたらご提案などをさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問","question":"本来ならば社会全体で担うべき問題、どういう存在、説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"そういった様々なところが関わり合う、そういったところが望ましい形だと思い、社会全体で担うべきという表現にしています。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"どういった観点が必要なのかなというふうに、これは時代が変わってきて、そうならざるを得ない。そこのところはどういうふうな形で、そうさせない、ここのバランスというのはどういう状況で展開するのか改めて説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"いろいろメニューはあるのですけれど、それを受け入れる出口のメニューを社会全体で担ってくれるのが理想だというふうに考えています。通過点としてフリースペースが利用してもらえれば、そのように考えて、出口のところに力を入れているです。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"その辺をどういうふうにして、ある程度年度ごとのアジャストなどができると思うのですが、どういう視点で取り組んでいるのか教えていただきたい。そこの活かし方、いろいろ申し上げましたけれども、何かあれば説明を求めました。","respondent":"柴田子ども施策連携担当課長","answer":"それに伴って、既に３か所を実際に訪問させていただいて、これから年内に２か所、今のところ５個見てこようというような予定を組んでいます。５年後、新たな拠点を設置するに際しましては、そういった視点を持って実施していきたいと考えています。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問・要望","question":"だからやはり、そういう意味でも工夫というのですか、もう少しいろいろなものが進んでいると思うので、そういうのも取り入れながら。ラストワンマイルなのだというところの整備が必要なのかなと思いますので、ぜひ引き続き、いろいろな工夫をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今お話聞いていて、個人的に少し要望だけ伝えします。要望です。","respondent":"吉野子ども家庭支援センター長","answer":"私ども、子ども家庭支援センターのほうは、やはりそういった家族というところは大切にしていまして、あくまでも支援という形でやっております。ある程度支援が行き届きましたら、そこは当然、その家族の機能というところを大切にしていきたいと考えておる次第です。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その下の、どこがどういうふうにしていくのかという辺りを少し教えていただきたいというのが１つです。もう本当に８,０００円とか１万円などとというふうなことで、このマイシェルパへの委託料が幾らくらいなのかという点について説明を求めました。","respondent":"東野福祉計画課長","answer":"その４回目以降の支援を受けたい方についてなのですけれども、その辺についてまた、少し分析が必要かなと考えています。そういったものも含めまして、今年度の予算では４１２万７,０００円ほど予算を取っております。","id":"exchange-028"},{"speaker":"ゆきた副委員長","kind":"確認","question":"協定を結んでから１年少しで、ここから区の福祉に結びついたものというのがあるのか、さらに具体的なところがあればお聞きできればと思います。併せてなのですけれど、あなたのいばしょの担当者間で情報共有という定期的なものを行っているかというのも、ここも確認でお聞きできればと思います。","respondent":"東野福祉計画課長","answer":"詳細についてはお答えすることはできないのですけれども、それからひきこもりの方について、区の支援が必要だというような問合せなどもありました。今後、あなたのいばしょとの来年度の事業に向けての相談ですとか、そういったものも定期的に行っているところです。","id":"exchange-029"},{"speaker":"ゆきた副委員長","kind":"確認","question":"、確認できました。区につなげるというものも確認させてもらったのですけれど、先ほどの説明の中で、この辺について最後お聞きできればと思います。","respondent":"東野福祉計画課長","answer":"現状を考えたときに死にたいと思うことはありますかとか、そういった設問があるので、そこに対応した回答ということになっております。どう体制を取れるか、また、あなたのいばしょのほうとうまく連携を取りながら考えていきたいと考えています。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/404196?Template=document&Id=7277#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":33939,"voices":73}},{"id":"r07-20251127-10","meetingId":"r07-cm11","date":"2025年11月27日","dateIso":"2025-11-27","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982705?Template=document&Id=7231#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1078,"voices":8}},{"id":"r07-20251127-20","meetingId":"r07-cm11","date":"2025年11月27日","dateIso":"2025-11-27","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"全体で、モデル事業も計画と同じ３年間という事業期間なのか伺います。どのようなメンバーがいらっしゃるのかを教えていただきたいのと、都市型のウェルビーイングシティとはどういうものなのか、伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"地方における、そういった部分の取組がきちんと推進されて、ほかの地域に示すことができるかをチェックされていると認識しています。１０名、あとは、民間の方も含めて１０名の委員の方がいらっしゃると認識しております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"資料に基づいて具体的なところも少し伺いたいのですけれども、１ページの付加価値額のご説明があったのですが、はかり方を教えてください。これ、どのように目標値を達成する考えなのかについても、もう少し伺えればと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"より頻度高く調査を実施しているということがありまして、結果としてどういう数値がついてくるのかといったところで把握をしていると認識しています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは要望です。これは２０１３年度比５０％目標となっているということでよろしいのか、確認したいのと、そこについてはいかがか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"品川区も令和６年、やや低調に推移していますが、目標に向かって進めていかなくてはいけないところです。特に先ほど説明の中でも申し上げましたように、所管も含めて引き続き区として何ができるかは考えていかなければいけない課題と認識しております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ私は超高層ビル開発規制も検討すべきだと思うのですけれども、それについては、お考えはいかがでしょうか。要望したいと思うのです。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区としましては、広く事業部門、家庭部門のＣＯ２の削減の目標量を、達成に向けて区民の方への周知啓発、それから、事業者の方への啓発、多様なステークホルダーを巻き込んで進めていくところですので、特定の再開発について何か取組をする考えはございません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それを、申込みが来たら、法にのっとってやっているわけですから、開発部隊としては、そこに異を唱えるものではないと。やはり司令塔なわけですから、必要な手を打っていただく必要があると思いますので、それは私の意見として述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、それがどういう形で、読み方が間違っていたら。先ほどのお話から伺うと、区内の企業がかなり利益を得ているということでいいのかどうか、その辺りの考え方をまず説明を求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"９番、９の２ですので、こちらの９番とその中のターゲットの２番に該当する指標として設定をしています。令和３年度調査の結果によりますと、１５６兆２,９９５億８,２００万円となりまして、支社はその所在地の地域で計上されるという算出方法です。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"非常に兆という金額がすごくインパクトがあったものですから、本当にすばらしいと、普通に素直に思います。広報しながわに載せればいいというだけの話ではなくて、その辺りの工夫が必要だと思うのですけれども、少し長くなりましたが、いかがか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長、崎村企画課長","answer":"次、令和９年度からの第２期の計画の改定の時期などに合わせて、指標の大きな見直し等も併せて検討していければと考えております。各世代にとってどういった使い方が分かりやすいのかは、引き続き検討させていただければと考えておりま… 先ほど合計特殊出生率の分母になるような１５歳から４９歳までの女性の方というのが、２,４００人ぐらい増加をしているような状況です。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"要望、これからどういう目標を達成していくのか、ぜひそういったことをお願いしたいということが１つです。その中でそれは伺わなければいけないのですが、それも含めて１年目にしては頑張っている評価なのか、指摘もあったのか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回の１年目の進捗評価を受けてすぐにＫＰＩを見直すことについての是非もあるかと存じますので、引き続き検討してまいりたいと考えています。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"は区の方針として、非常にそこに力を入れていらっしゃると感じましたので、ぜひ今後とも慎重に続けてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"ＳＤＧｓの理念をしっかり品川区の事業に一つ一つ当てはめていくことが大事であるということを会派からは求めさせていただいたことがよみがえってき…その見せ方については大いにしっかり工夫をしていただきたいというのが１点と、２０３０年を超えた後、教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"計画については３か年ごとに策定する方針が出ていますが、４か年の計画とする方針が今は、第２期の計画の策定に当たっては。ウェルビーイングについても軌を一にすると考えておりますので、この取組、計画は引き続き同じように進めていきたいと考えているところです。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"世代別の見せ方もあろうかと思いますので、ぜひ工夫してほしいと求めました。ちょうど品川区の長期基本計画も策定が２０２９年と一つの区切りがあると思いますので、また取組を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"それと、あと、中小企業でやはりなかなか啓発が難航している部分、脱炭素、そういう話もありますけれども、具体的に何が障壁となっているのですか。壁となっている部分、それをまず説明を求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"中小企業の二酸化炭素排出量などのところでご説明させていただきましたように、優先順位が低く、壁となっている大きな理由です。企業にとってメリットになったり、より自社の中で取り上げていただくことができるのかといった検討をしていく必要があると課題を共有しております。","id":"exchange-012"},{"speaker":"まつざわ委員","kind":"質問","question":"いい取組をやっているのですから、五反田バレーなどが照明とか、電気制御などをやっている。こういう事業を区がハブになってやっていく、そういった取組を進めていくといいと、素人ながらにすごく思ったのですけれども、どうなのか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"昨年の２月にご提案いただいて、今年度から実証実験を八潮地区の区有施設で実施しているＴｒｅｅＬａｂ合同会社、実証実験を今年度始めています。","id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そんなすばらしい取組があったなんて知らなかった。ＳＤＧｓ推進に向けて、今も大分頑張っていただいていますけれども、さらに頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"その計画の中身と、あと、運用について課題があれば、教えてほしいと求めました。特に堅調に推移している指標と、この抜き出した基準とかがあれば、教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回ご説明させていただきました進捗状況、改めてギアチェンジできるような、そういったきっかけになったという成果として受け止めています。まだまだ取組が十分ではないと認識しておりますので、また、ターゲット別の伝え方などは研究を検討してまいりたいと考えています。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"その中でＳＤＧｓ未来都市等進捗評価シートを個別に見た中で気になったところを伺いたいのですが、これは達成度がマイナス２４％と、下回っています。どう対応していくのか、どう受け止めて、どう取り組むのかをお聞きしたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"棒グラフなどで視覚的に分かりやすく、三側面ごとに伝えていくことについてのご提案は、今後検討してまいりたいと考えております。その下のオアシスルームの実施拠点としまして、この後、オアシスルームの利用者数も伸びていくと捉えているところです。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"児童・生徒の不登校出現率の確認ですけれども、不登校ではなくしていくお取組を進めていくということでしょうか、それに対しては何かないのかです。もう１つ、ＳＤＧｓ未来都市等進捗評価シート右下の７ページの心身の健全な成長の項目の中で、教えてほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"東京都が実施しているような結婚のマッチングなどについて区として取り組む考えはあるのかというご質問でございましたが、区としては、充実ですとか。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"健康ポイントについては、ぜひ併せてご確認と改善を進めてほしいと求めました。日頃からＳＤＧｓを意識した行動を取っているかどうかについて確認する、意識調査にそういう今後確認する項目を入れないと、これが確認できないので。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"昨年、世論調査は２年に一回実施していますが、ＳＤＧｓの１７の目標のうち特に取り組んでいく必要がある目標については調査をしています。社会、環境の三側面で、区民への啓発としてどのような実態調査ができるかということは引き続き検討してまいりたいと思います。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"最後の浸透度をはかるところについては、それでぜひ確認を進めていただき、その意識を高める取組を併せて進めてほしいと求めました。期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"こうした指標の達成状況とかがよく見えて、見える化が進んで、非常にいいことと考えております。ミドル期シングルはミドル期ですから、しっかり反映していただきたいと思うのですけれども、その点いかがか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回は子どもを１つテーマとして大きく策定したところがありますので、子どもといったところに含まれているのは、そういった事情があるものです。区としても各取組を進めていますので、今後の計画の策定、計画改定に当たっては検討してまいりたいと考えております。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"ＳＤＧｓ未来都市計画の下の中央のページだと８ページ、結婚して、子どもを産み育てようとなるのか。やはり経済的な側面も入れたほうがいいと思ったのですけれども、その辺り、いかがお考えか尋ねました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"確かに合計特殊出生率を上げていくための要因は、非常に多岐にわたり、複合的な理由から成り立っているものと認識しています。先ほどもご説明させていただきましたように、子育て支援策のさらなる充実で、そちらも受け止めさせていただければと思います。","id":"exchange-021"},{"speaker":"筒井委員","kind":"意見","question":"ぜひよろしくお願いしたいと思うので、その辺、何かお答えいただければ。どう考えられるのかとの意見を述べました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"子育て支援策をさらに充実をして、ＫＰＩが上昇していくのかどうかという推移を引き続き区としては確認をしてまいりたいと考えていまして、ご意見として受け止めさせていただければと思います。","id":"exchange-022"},{"speaker":"こしば委員","kind":"質問・要望","question":"それをいかに解消していくかが大切なことで、そこは本当に間違うことは当然ないとは思うのですけれども、所管と連携をしてほしいと求めました。その辺り、課長のお考えをお聞かせほしいと求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"いじめ解消率について、目標値にこだわらずに、認知件数が上がったこと自体はいい傾向だと捉えて進めるべきというご意見をいただいたところです。","id":"exchange-023"},{"speaker":"こしば委員","kind":"質問・要望","question":"お願いしたいと思います。生まれているわけですから、求めるものを追求していってほしいと求めましたが、その辺りの考えを説明するよう求めました。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"養子縁組等含めて、そういった子どもたちへの対応を含めた区としてのＳＤＧｓの在り方についてのご質問です。きちんとした居場所ですとか、区として地域で子どもを育てていくということについては、引き続き取り組んでまいりたいと考えております。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579883?Template=document&Id=7233#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":34723,"voices":61}},{"id":"r07-20251128-22","meetingId":"r07-cm11","date":"2025年11月28日","dateIso":"2025-11-28","committee":"まちづくり・公共交通推進特別委員会","time":"午前１０時００分～午前１１時２５分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ＪＲがやることなのでしょうけれども、どんな状況でどういうまちびらきになるか、品川区が関わるのかということを伺いたいです。２ページの1)の広域避難場所の開放とあるのですけれども、広域避難場所というのはどこでしたかという確認をさせていただきたいです。","respondent":"泉広町事業調整担当課長","answer":"１点目のＪＲ東日本のまちびらきに対する区の関わり方ですけれども、区が直接的にそこに何か関与するといったところは考えてございません。けれども、地域と何かしらの関連性を持って地区一帯が盛り上がるような取組を進めてまいりたいというところで考えているです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、広域避難場所はこの地図でいうと書かれていない部分ということか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"今１ページ目でお示しをしている広町地区のまちづくりの着色がしてあるところにつきましても、基本的にはそこも指定がかかってあります。それに加えて、そちらも一部広域避難場所として範囲に含まれているというところになってあります。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"提案","question":"(2)で、なぜ公園と庁舎跡地を活用した具体的な提案がほとんど見られなかったのか、理由を聞いているなら伺いたいです。そこまで伺いたいと思いますとの意見を述べました。","respondent":"泉広町事業調整担当課長","answer":"建物がつながってということのお話がございましたけれども、今は建物をつなげる検討まで深まっているところではございません。建物そのものを一連のものにしていくのかといったところまでは検討が深まってございません。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"提案","question":"引き続き伺っていきたいのですけれども、６ページの大きい３番の活用方法の続きのところで、国と都が賃貸になっていくということなのでしょうか。最後に、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"そうしたときに、なかなか区民のニーズに柔軟に対応できるような、取得を目指していきたいというところでの記載をしています。活用の検討委員会の中では様々幅広い区民ニーズをいただいているですので、そういったことがかなえられるように目指してまいりたいです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"続いて、区画道路整備について、伺いたいと思います。補助２６号線を通る東急バスがここに入ってくるというふうに考えればいいということなのでしょうかという確認です。","respondent":"泉広町事業調整担当課長","answer":"具体的な人数につきましては現在検討中で、まだお知らせできる段階でないものですから、まとまりましたらご報告させていただきたいと思ってあります。こちらにつきましても、一定程度バス事業者と協議が整った段階で別の場面で改めてご報告させていただければと思ってあります。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いずれにしても、区民の貴重な財産がどのように使われていくのかというところを区民の皆さんもすごく期待とともに心配もしています。なので、区民の求める施設等の整備が大きく進む活用になるように、引き続き求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"その上で、何点かお伺いをしたいです。そこをお伺いしたいと思います。","respondent":"遠藤防災体制整備担当課長","answer":"その中で、非常に区としても大変心強いスペースの確保となっています。ＯＩＭＡＣＨＩ ＴＲＡＣＫＳができても１万人程度不足するところで、さらに一時滞在施設のスペースの確保というところが求められている状況です。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"私も地元の中延商店街の方からアーケードにハトの巣ができて、例えば虫を求めた鳥が住むのではないかとか、いろいろな視点が考えられると思います。そういうところまで踏まえて、学識経験者の思いがどういうところにあったのかということをぜひお伺いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"庁舎跡地等活用検討委員会の中でも、みどりの充実を求める声があったというところがあります。まずは不足するみどりを充実をしっかり目指していきたいというところで考えてあります。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"そこにバス停ができるのかどうかというのは分からないのですが、その手前のバス停の設置に対して私はぜひ区としては求めてほしいと求めました。今の時点でのご見解をお聞かせほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"バスの停留情報に関するお話ですけれども、現時点の協議の内容でお話ししますと、新庁舎の前に停留所ができるような計画は、現時点ではないです。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"都市軸という言葉に込められている思い、あとは拠点形成とか、このことについてもう少し詳しくお考えをお聞かせほしいと求めました。ここに違いというのが何かあるのかということを説明するよう求めました。","respondent":"高梨都市計画課長、泉広町事業調整担当課長","answer":"私からは、都市軸等についてお答えをします。そういったものを広域都市軸と位置づけて、それぞれの拠点だけではなくてそれぞれの拠点同士を結ぶといったところも計画の中では重要視しています。Ｂ－２街区と言ってあります本庁舎の敷地につきましては、住宅機能を活かした施設ということで、これは記載のとおりです。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"現在の建設費や不動産市況の継続が前提であるということについて教えてほしいと求めました。継続と言っていることの意味をもう少し詳しく教えてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"そういったところの精査といったところは当然我々のほうもしっかり行っていかなければならないというところで考えてあります。必ずしも上がるものではないところから、なかなか将来的な判断が難しいというところで、現時点のご提案という形でのものになっているです。","id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"ここは不安というか懸念要素だということで、かなり今後の各企業さんの判断に影響を与えるところだということを今認識いたしました。その点については今後ともまた注視していきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"今、塚本委員からもご質問がありましたが、庁舎跡地活用に関する対応型市場調査についてです。Ｂ－２街区には住宅機能、Ｂ－３街区には住宅機能を入れないという認識でよろしいか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"今私のほうでご説明した対話型市場調査の提案の中では、Ｂ－３街区のほうにも住宅を入れる案と入れない案ということで、２通りのご意見があったです。","id":"exchange-013"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。公益性の高い複合施設を導入ということですけれども、既に集客する起爆剤となるような収益モデルとかというのはアイデアとして出ているのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査の中では民間事業者も検討の深さに差がございまして、検討がかなり進んでいるところとそうではないところといろいろあったところです。","id":"exchange-014"},{"speaker":"えのした委員","kind":"確認","question":"なかなか収益の部分は、どの企業にとっても難しいところなのかなという確認が取れました。正式名称は東日本旅客鉄道株式会社と言うのか尋ねました。","respondent":"遠藤防災体制整備担当課長","answer":"３,０００人という大人数の備蓄品をストックするといったところで、１,５００人分ずつを２か年にかけて備蓄していくという計画を立てております。例えば災害用トイレ、公共無線ＬＡＮ、ＪＲ東日本から支援を受けて帰宅困難者に提供していくといったスキームになってあります。","id":"exchange-015"},{"speaker":"えのした委員","kind":"確認","question":"３,０００人分を１,５００人ずつということで、確認が取れました。その辺を説明するよう求めました。","respondent":"遠藤防災体制整備担当課長","answer":"大井町駅周辺で帰宅困難者対策協議会というものを設けていまして、こちらのほうで対応していきます。ただし、定期的に帰宅困難者協議会に対するサポートとして訓練の支援ですとか、こちらの操作説明を東京都と連携してご案内するなどの支援をして。","id":"exchange-016"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"これは役所の悪いところだけれども、１６社だ１３社だとやっていますが、こういう提案ができるのはデベロッパーだって５、６社しかいません。例えば１社に５,０００万円払って６社を選んで３億円を使ったとしても、その代わり本気で提案してきてくれますとの意見を述べました。","respondent":"泉広町事業調整担当課長","answer":"２００億円を想定していくというところでお示しをさせていただきました。効果的な募集のやり方、意見のいただき方といったところをしっかり調査、勉強してまいります。","id":"exchange-017"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"私はいろいろな会があったときには必ずこれを言っていきます。それだけは、言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]},{"id":"topic-02","title":"新庁舎整備に向けた工事説明会の実施結果","agenda":"新庁舎整備に向けた工事説明会の実施結果","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"確認ですけれども、３階にカフェがありますとあるのですが、このカフェは障害者カフェですか。食堂の代替になるようなカフェだということでいいのか尋ねました。","respondent":"小林新庁舎建設担当課長","answer":"カフェの内容とかありますが、従来からご説明しておりますとおり、３階には障害者就労を目的としたカフェを整備することで計画を進めてあります。例えば軽食の提供等も含めて現在検討をしているといったところです。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、やはり区役所の中に食堂というものがあったほうがいいのではないかと私も思っています。こういう質問が出た中で区がこういう回答をしていましたので、こうしたところでも食事ができる施設になるといいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"通常のこの周辺に勤務されている方の休み時間も１２時から１３時の中で、そういうご配慮というか、そういうことは言えるのでしょうか。細かい話で恐縮です。","respondent":"小林新庁舎建設担当課長","answer":"やはり発注者側のほうから何かこうしなさいという指示はなかなかできないのかなと思います。今お話しいただいた内容を含めまして、お話としては施工者のほうには伝えてまいりたいというふうに思ってあります。","id":"exchange-021"}]},{"id":"topic-03","title":"路線バスのバス停新設","agenda":"路線バスのバス停新設","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"本当に地元では結構スペースがあるのにどうして片側ができないのかということで、かなりご要望をいただいていましたので、大変によかったと思います。せっかくのこういった機会ですので、現状をお聞かせほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"ご指摘のバス停につきましては、東急バスのほうも精力的に働きかけ等を行ってきている状況ではありますが、委員ご指摘のとおり課題がまだ残っているという状況で、もう少し時間がかかるというふうに聞いております。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"暑さもありますのでバス停に屋根だけでも欲しいというような要望も多々、そういったところの検討というのは東急のほうとされているのでしょうか。運転士不足等もあると思うのですけれども、そうしたところの要望も区のほうには届いているのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"バス停の屋根の設置ですが、東急側のほうとしても費用面、ご要望等も含めて判断していくということになろうかと考えています。２６号線自体が朝と夕方以降は非常に混雑するということで、なかなか時間が読めないような状況もあるという話は東急のほうから聞いたことがあります。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"確かに、屋根は新たに建てるとなれば費用がかかってくると思うのですけれども、やはり利用する方の状況からすればバス停で待つということは多々あると思うので、利便性や利用率を向上させていくというところでは、こうしたこともぜひ引き続き求めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/676877?Template=document&Id=7279#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":27227,"voices":71}},{"id":"r07-20251204-10","meetingId":"r07-cm12","date":"2025年12月4日","dateIso":"2025-12-04","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"令和７年陳情第５４号、予算・決算委員会や常任委員会等のライブ配信とアーカイブ動画公開を求める陳情","agenda":"令和７年陳情第５４号、予算・決算委員会や常任委員会等のライブ配信とアーカイブ動画公開を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"具体的に伺いたいのですが、時期はどうあれ、確認させていただきたいのです。私たちは必要だと、行うべきだと思っているのですが、皆さんのご意見を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"これは議会運営委員会に付託されているので、議会運営委員会としてはどう考えるかというところが大事だと思うのです。私はそう判断しましたが、皆さん、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"意見","question":"今、声かけがあったのでお答えをしたのですが、どうも誤ってご理解をされていらっしゃる。議論はできないので、それだけは申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"どういう態度が出てくるのかというのはこれからなのかもしれませんけれども、まさかこれで不採択とはならないだろうなと理解したのです。それで、事務局にもお伺いしたいのですが、現在把握している範囲でいいのですが、他区の委員会の動画配信状況はどうなのか、伺いたいと思います。","respondent":"大澤区議会事務局長","answer":"２３区の中で、現在、委員会のライブ配信をしている区は５区です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、４年もの間この状況を放置するのはよくないと思っていまして、すぐにでも始めるべきなのではないかと思います。ぜひこれを採択すべきだと、採択してすぐにでも始めていく努力が品川区議会に求められているということを、意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"せお委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。例えば方法ですとか、新庁舎ということを頭に入れて検討していかなければいけないのではないかと思いますので、本日は不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"松永委員","kind":"質問・要望","question":"我が会派においても極めて重要であると、また、以前から常任委員会なども中継できる環境の整備を求めてまいりました。全委員会室へのカメラの設置等につきましても、要望していきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"同じようなライブ配信のことでのご要望もいただいたかと思いますが、これからあと４年後、皆さんも感じていらっしゃるかと思います。陳情者のおっしゃることは別に間違ってはいないと思いますし、これは検討すべき課題だと考えていますが、現段階では不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"この内容を否定する方は１人もいないと思いましたし、残念ながら今の時点で品川区は、この点では後れを取っていると。現時点でやってほしいと区民から陳情が出ているわけですから、早急に配信を始めるべきだと、それが開かれた議会にふさわしい在り方だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"令和７年第４回定例会","agenda":"令和７年第４回定例会","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"多様な人材の地方議会への参画促進を求める意見書ということで、提出者になっていただけるという方は、記載のとおりです。〔案文朗読〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"その上で質問ですが、前回、案が出されました。この案に対しての意見を伺っていくということだったと思いますけれども、どのような意見が出たのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"安藤委員","kind":"提案","question":"１０名の方が提出者にはならなかったということだと思うのですが、提案なのですが、項目２があるではないですか。この項目２の最後の部分、「厚生年金へ」というところ、これ以降の部分を削除する修正を行うべきなのではないかなと思うのですが、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"会社員の方は厚生年金へ入っていたりもするわけでしょうから、これは全国市議会議長会からもそういう幅をどんどん広げてほしいというお話があって。全国市議会議長会では判断しているということですから、そういう幅を広げましょうという、ただそれだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"その上で議論を続けると、そういった判断が必要なのではないかなと思うのですが、それは誰になるのでしょうか。そういった判断をしていただきたいのですが、皆さんなのか、委員長なのか、自民党なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういうふうに皆さんにご提示しているわけですから、多数でも決定をして、意見書を提出していく。ここに書いてあるとおり、そこへ提出をしていくということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"拙速に、一部の人が賛同できるからということでやるのではなく、１０人ぐらいは提出者になっていないわけですよね。ですから、全会派でもないわけなので、丁寧に議論すべきだということを改めて意見として述べさせていただきたいと、強く述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"令和８年第１回定例会","agenda":"令和８年第１回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"民生費のところを分割して日程を増やしてほしいという意見を言ってきたのですが、開かれるということになったと伺ったのですが、提案はしたいと思うのですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982705?Template=document&Id=7235#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":12084,"voices":72}},{"id":"r07-20251225-6","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"区民委員会","time":"午前１０時０５分～午前１０時２２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出等 区民委員会所管分）","agenda":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出等 区民委員会所管分）","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"ギフト券などをお届けしていただきたいということを要望させていただいたという経緯があったわけなのですけれども、今回、高く評価したいと思います。コールセンターを委託する理由について教えていただきたいのと、種類などについても、もし決まっているようでしたら教えてほしいと求めました。","respondent":"今井八潮まちづくり担当課長","answer":"コールセンターの設置の理由ですけれども、こちらについては、コールセンターの問合せ数が約１万６,０００件あったということで認識しております。現在まさに検討中ですけれども、検討の方向性としては、検討しています。","id":"exchange-001"},{"speaker":"こしば委員","kind":"質問・要望","question":"３か月か分かりませんけれども、早い段階で一旦コールセンターを立ち上げるということもあり得るのかどうか、その辺の考えを教えてほしいと求めました。","respondent":"今井八潮まちづくり担当課長","answer":"基本的には、ギフトカードの郵送前に設置する予定ということで、コールセンターなどへのお問合せも受けられるような体制を整えたいと考えております。使用期限を設定いたしまして、ある程度幅広に、使用期限後も一定の問合せを受けられるような体制を取れるように検討しています。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"こういうところで所得制限は設けるべきではないと考えていますので、多くいらっしゃるので、歓迎されると思います。印刷したりとかそういったことも視野に入れているのでしょうかというところと、主目的になっているのかという部分、まず２点お願いします。","respondent":"今井八潮まちづくり担当課長","answer":"検討中というところで、そういったところのバランスも考えながら、カードの種類については選定していく予定です。特にエリアで使用が制限されるということはありませんので、区内に限定せず、広く全国で使用できるようなカードになる予定です。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"確認","question":"本当に物価高対策というか、そういった生活支援というのが主目的だということを確認いたしました。これは一応、金券になるのですが、郵送はどういった形を想定していますか尋ねました。","respondent":"今井八潮まちづくり担当課長","answer":"郵送につきましては一定、配送記録の残るものということで予定しておりまして、例を挙げますと、簡易書留ですとか、ゆうパックですとか、そういったお届けをしましたという記録が残るもので郵送する予定です。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"他区だと、独自のポイントとか、区内共通商品券とかにするところもあるようですけれども、品川区でも区内共通商品券という検討はあったのかというのもお聞かせほしいと求めました。","respondent":"今井八潮まちづくり担当課長","answer":"配布対象にするかどうか検討はさせていただいたところではありますけれども、その規模に対応できるところといった部分を踏まえまして、今回のギフトカードという選定をさせていただいたという経緯です。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この辺は十二分に検討していただいて、迅速に配布できることを考えなければいけないので、そこはいろいろ検討していってほしいと求めました。これは要望なのですけれども、発行のときには注意喚起をぜひやっていただいて、対応をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=7287#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":5569,"voices":27}},{"id":"r07-20251225-9","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"文教委員会","time":"午前１０時０５分～午前１０時４２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第１４４号議案、令和７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"幾つか確認させていただきたいのですが、支給対象者のところで、９月３０日時点を基準にした理由を伺います。児童手当の認定を受けてない新生児の方が２,０００人と、公務員は４,０００人の児童がいるということですが、いつ頃生まれた方なのか伺います。","respondent":"柏木子育て応援課長","answer":"ですので、子育て応援課では、公務員の方については把握ができない状況です。その場合には手続をしていただく必要があります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこはプッシュ型ではなくて、申請が必要ということになると、漏れがないようにお願いしたいのですけれども、その点が大丈夫なのか伺います。そうしたことへの対応をしっかりとしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"柏木子育て応援課長","answer":"１０月に支給されている方は、９月３０日までに児童手当の申請をされている方になりますので、そういう基準で９月３０日を示していると考えています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"最後に公務員について、そうすると所属しているところから証明書が出されて、それを住んでいる自治体に提出する形になるのですか。その仕組みを伺います。","respondent":"柏木子育て応援課長","answer":"委員、今お話しされたとおり、証明書を持って、お住まいの役所に提出いただくことになります。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"２点目ですけれども、区民への周知で、児童手当受給者へ通知を送付するとあるのですけれども、こちらはいつ頃の送付を予定しているのでしょうか。１月中旬の様々な広報をされるタイミングで、これをお送りするのか尋ねました。","respondent":"柏木子育て応援課長","answer":"それぞれ理由があると思いますけれども、その方で今回、物価高対応子育て応援手当については支給してほしいという場合は申請が必要になります。それと周知の時期ですが、こちらはホームページ、広報等も合わせまして、１月中旬に周知したいと考えています。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから、コールセンターに約１,２００万円、これはプロポーザルか何かでコールセンター設置までに決めるのでしょうか。繰越明許費で約２４億円、こちらの子育て応援手当は約１２億円、これは年度内に決裁が済むから繰越明許費にならないのか尋ねました。","respondent":"柏木子育て応援課長","answer":"初めに、支給につきましては、物価高対応子育て応援手当として、児童手当とは一緒にせず、この手当としての支給をいたします。繰越明許費につきましては、物価高対応子育て応援手当についてはしないです。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"この事業が始まる連絡をする前に、プロポーザルをやったり、あるいは今までどこかにやっていただいたものに委託したりするのでしょうか。令和７年度のときに決裁して、言い方は変ですけれども、それを新年度になってからも支給していくので繰越明許費にならないという意味でいいのか尋ねました。","respondent":"柏木子育て応援課長","answer":"物価高対応子育て応援手当につきましては、今年度予算で全て執行ができるという考えですので、繰越明許費については想定していません。もう１つ、規模も違うということもありますので、プリペイドカードの購入等の関係があっての繰越明許費だと考えています。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどの転入のところは、１０月に引っ越してきた方は、品川区からいただけるのですか。それとも、基準日を越えてしまっているので、物価高対応子育て応援手当支給については前の区に申請しないといけないのか。","respondent":"柏木子育て応援課長","answer":"基準日の９月３０日以降に転入された新生児につきましては、品川区で支給いたします。ですので、そのときに子育て応援課に児童手当の手続をしている方につきましては、品川区から支給になります。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"今また詳しく聞きたいのが、自分でも整理がつかないのですけれども、品川区から外へ出てしまっている方にも出していることも考えると、また複雑になるので、また後で詳しくお聞きします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"申請の受付終了が４月中旬で、これでいうと３月３１日に生まれた方は、４月中旬だと僅か２週間程度の中で申請をしなければいけない。ここはどのように、仕組としていわゆる漏れなく担保されているか、お聞きしたい。","respondent":"柏木子育て応援課長","answer":"４月中旬までというと、２週間は当然、期間的には問題ないと考えています。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"決まりはそうですけれども、いろいろなご事情によって、４月中旬に出生届が出せなかった方がいた場合は、どういう扱いになるのか尋ねました。","respondent":"柏木子育て応援課長","answer":"申請の期間につきまして、そこは状況を聞きながらとは考えてありますけれども、ただ６月以降とかに申請をされても、それは対応はできない。ただ、そこは多少はご事情を聞きながら、対応はさせていただきたいと考えています。","id":"exchange-010"},{"speaker":"若林委員","kind":"意見","question":"そうすると、ここでは支給は出納の関係も当然あって、一応５月下旬までと。０歳から１８歳、一日でも早くお手元に届くように、最大限の努力をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"筒井副委員長","kind":"確認","question":"確認も含めて２点ほどお聞きしたいと思います。補助率は国の１０分の１０ですけれども、自由に決めていい、裁量で決めていいということなのか尋ねました。","respondent":"柏木子育て応援課長","answer":"１点目の所得制限ですが、この物価高対応子育て応援手当につきましては、所得制限はございません。一応、設置までの期間が短いので、先ほどご答弁したとおり、随意契約で経験があるところにお願いしたいと考えています。","id":"exchange-012"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、先ほどの質問の中で、そのような方はどういった扱いになるのか教えてください。周知を分かりやすくお願いしたいと思うのですが、その辺り、いかがか尋ねました。","respondent":"柏木子育て応援課長","answer":"離婚等で物価高対応子育て応援手当の受給者が変わる場合ですが、今、１月中旬に通知を予定していますので、そちらにその件はきちんと記載して、周知を図っていきたいと考えています。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"コールセンターの話で今ほかの委員から質問があったのですけど、契約金額の上限は国から示されているのでしょうか。１０％ぐらいとかそういう数字なのかどうか、２,０００万円で契約することも可能なのか、国からそういうルールがあるのか。","respondent":"柏木子育て応援課長","answer":"今、手元にある資料では、そこら辺の金額の制限は特に見当たらないところです。","id":"exchange-014"},{"speaker":"筒井副委員長","kind":"質問","question":"コールセンターの経費が１,２４０万８,０００円、具体的に出ているのですけれど、これはどういう根拠か尋ねました。","respondent":"柏木子育て応援課長","answer":"内訳といたしましては、コールセンターにつきましては約５００万円で、システム作業で約７００万円になってあります。システム作業につきましては、対象者の抽出ですとか、あと振込のデータ等の作成に関わる経費です。","id":"exchange-015"},{"speaker":"つる委員長","kind":"質問・要望","question":"これは答弁の正確性も含めて、Ｑ＆Ａも確認いただきたいのですが、改めて私からも聞きます。逆に１０月に入って転出した人は、品川区からの支給なのか、転出先の自治体からの支給なのか、そこを説明するよう求めました。","respondent":"柏木子育て応援課長","answer":"１０月１日以降に、住民登録がされたとなりますと、それは品川区からの支給になります。ですので、新生児で、１０月１日以降に他の自治体に転出された方は、転出された先の自治体から支給はされるという形であります。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/843512?Template=document&Id=7281#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":9104,"voices":62}},{"id":"r07-20251225-5","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"総務委員会","time":"午前１０時５０分～午前１１時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"第１４４号議案、令和７年度品川区一般会計補正予算","agenda":"第１４４号議案、令和７年度品川区一般会計補正予算","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"区長へ緊急要望させていただいた物価高騰支援について、また区独自の上乗せを実施されるということなので、そのことについて大変感謝しております。お伺いしたいのですが、プラス２,０００円、区内商品券というのは考え方としてあったのかどうかというのを教えてほしいと求めました。","respondent":"加島財政課長","answer":"計５,０００円として、短期集中的な支援とはなりますけれども、５,０００円相当のギフトカードをお配りしたいと考えた次第です。区内の共通商品券を考えなかったのかですけれども、もちろん検討の俎上にはのってまいりました。","id":"exchange-001"},{"speaker":"西本委員","kind":"確認","question":"生活応援という形の中では２,０００円の上乗せ、そこら辺の東京都からの縛りはどういう、あまり縛りはなかったのですか。４万２,０００人ぐらい対象なのですけれども、両方としてまとめてやったほうがよかったのではないかと思うのですけれども、いかがか尋ねました。","respondent":"加島財政課長、崎村企画課長","answer":"プッシュ型で支援を行うこと、また緊急性がありやむを得ない場合などに実施することとされているところですので、国との関係において。しながわ生活応援事業と、それから物価高対応子育て応援手当給付金のほうで… それに上乗せするという形ですので、新たな組織をつくるということではなく、既存の組織での対応と考えているところです。こちらを円滑に、かつ迅速に進めていくために、組織を新設するです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"それから、組織の中で心配なのは、新しい部署ということで、これは時限でいいのですか。これが終わったら戻るという形で、一応区切りがついたら組織改正は元に戻すという認識でよろしいのか尋ねました。","respondent":"加島財政課長、崎村企画課長","answer":"１点目の使い道というところについて、今回、５,０００円を使って何を買ったかということまで把握することは求められておりません。５,０００円の中で幾らが使われて、そういったギフトカードを使って制度設計… 委員のご指摘のとおり、こちらの事業については、交付金を活用した限定的な事業となりますので、こちらの事業が完了しましたら、組織は解消するというような形で考えているところです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"利用内容というのは難しいと思うのですけれども、幾ら使ったかというのは、どうやって調べられるのだろうと。１,０００円を使った、次に２,０００円使ったという形になると、使った金額というのを把握できるという認識でよろしいか尋ねました。","respondent":"加島財政課長","answer":"換金期限が設けられて、なおかつ利用状況が反映できるギフトカードというのを、プロポーザルで探してまいります。その予定で、きちんとそういった国の交付の要件を満たせる事業者カードを探してまいりまして、区民の方のお手元にお届けしたいと考えております。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"生活ニーズに合わせて今回、ギフトカードということになったということをお聞きしましたが、これはほとんどのお店で使用が可能なのでしょうか。その点に対しても、期限が切れたら切って捨てるということで、使えないということで進めるのか尋ねました。","respondent":"加島財政課長","answer":"性別、それから世帯の状況ですとか所得に関係ないと判断いたしましたので、全区民に一律支援させていただきたいと考えているところです。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ答弁漏れがあったのですが、ギフトカード、皆さんに行き渡るのに、日数はどれぐらいかかるのか尋ねました。","respondent":"加島財政課長","answer":"区民の方のお手元に届くまでにというところなのですけれども、現在、プロポーザルで事業者は選定する予定です。仮定の話も入ってまいりますけれども、４,０００万円以上になれば、動産の買入れの議決を再度お願い申し上げることになろうかと思います。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"確認","question":"これだけ１０項目もの支援策があるけれども、１人３,０００円程度の補助金になりますという理解、区の独自の支出になってしまうという仕組みでいいのかどうなのかという確認したいと求めました。","respondent":"加島財政課長","answer":"少し説明が足りなかったかもしれないのですが、３,０００円相当の支援というところにつきましては、食料品の物価高騰に対する特別加算。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"提案","question":"プロポーザルでそういったことが出てくる事業者、そういったことを提案してくれる事業者をということですけれども、結構大変ではないかと思うのです。使用期限が設定できて、区のほうで分かっていれば教えてほしいと求めました。","respondent":"加島財政課長","answer":"今回はスキームの中でそれが必要とされておりますので、事業者の数というのはかなり絞られてくると所管からは聞いております。具体的な数まではお答えができません。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、そういうことが設定されることで、余計な支出が増えるのではないかという思いもあります。なので、国には柔軟で使いやすい、執行しやすい形をさらに求めていっていただきたいということは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"１人当たり１万円にするということも、会派の要望としても、その未消化額のところで支援を検討してほしいと申し上げていました。区としての、この辺りについてお考えがあれば、教えていただきたいところです。","respondent":"加島財政課長","answer":"７,０００円の上乗せについてというところにつきましてですが、こちらにさらなる上乗せを行うべきかどうかというのは検討させていただきました。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"配布経費は、実際にはかかるということで言えば、１回の配布でできるだけ効率的に配布ができたらいいかなというのを改めて感じた次第です。会派の緊急要望の中にも書かせていただきましたけれども、これは今回の配布ではなく、それ以降の中長期的な視点でご検討いただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"できるだけ物価高騰負担軽減に資するものというようなことで要望させていただいて、ギフトカードで５,０００円と、大変よかったと思っています。荒川区なんかはどうもやるようだと報道されていて、この２３区でも、どういうお考えかをお聞きしたいと思います。","respondent":"加島財政課長","answer":"コロナ禍で現金給付がございましたように、それが仮に消費ではなく貯蓄に回ったとしても、私どものほうでは把握ができないという状況にあります。","id":"exchange-012"},{"speaker":"塚本副委員長","kind":"確認","question":"どういうイメージでしょうか。そこだけ最後、確認したいと求めました。","respondent":"加島財政課長","answer":"プロポーザルで事業者を選定してまいりますので、発送ができるような体制を同時並行で整えていく必要があると考えておりますので、準備面も含めて努めさせていただきたいと考えております。","id":"exchange-013"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"もっと言うと、こんなのが可能かどうか分からないけれども、自分たちの意思でふるさと納税とかやって、五十何億円も出ているわけではないですか。そういうことが法的に許されるかどうかは分からないけれども、ただそういう人に対しては何か対策したいという気はあるではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"委員長報告","agenda":"委員長報告","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"その中に分からないところがあったので、どういうことを示しているのかということを教えていただきたい、確認したいということです。これは具体的にどう変わるのかを確認させていただきたいということです。","respondent":"久保田企画経営部長","answer":"多分この間、会派説明のほうは、１月２９日にやっていただくということで日程をお知らせしたということです。〔「後」と呼ぶ者あり〕 そうですか。それとあと予算編成を、その日程を設定するということは我々区長部局のほうで決定しますので、そのことを表現された内容ではないかと考えています。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"なので、具体的にどういうことなのかというのを教えてください。動議をかけるぞと思っていますけれども、分かりやすいように、１月の総務委員会のときにはご説明いただければありがたいと思っていますので。","respondent":"久保田企画経営部長","answer":"以前の議案説明会で、田中議員から予算案の説明についての発言がありまして、議案説明会の日程の話とか。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=7289#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":18186,"voices":52}},{"id":"r07-20251225-10","meetingId":"r07-cm12","date":"2025年12月25日","dateIso":"2025-12-25","committee":"議会運営委員会","time":"午後 １時２０分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982705?Template=document&Id=7285#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":815,"voices":8}}]);
